INSERT  IGNORE INTO `chunks` (`id`, `document_id`, `kb_id`, `seq`, `text`, `page`, `bbox`, `metadata`, `token_count`, `qdrant_point_id`, `created_at`) VALUES (1,1,1,0,'◎邬小辉JIANGYOUSHUYUANXINGZHITUWEN 江右书院之图文主编\n\n阳明书院龙江书院Contents 前言燕山书院目录白鹿洞书院曲山书院白鹭洲书院石莲书院鹅湖书院新兴书院象山书院义学复古书院江西书院十大人物复真书院江西书院十大事件山角书院匡山书院豫章书院复初书舍友教书院衡公书舍东湖书院武城书院墨庄书院青云书院泷冈书院阳明书院爱莲书院潋江书院横溪书院易堂书院朗山书院新安书院科山书院鳌峰书院涧东书院竹隐书院华林书院昌黎书院叠山书院龙光书院信江书院南昌书院四大书院赣州书院宜春书院紫阳书院明经书院六柳书院含珠书院凤仪书院东山书院明月轩书院端明书院天宝古书院奎光书院仰山书院正谊书院兴鲁书院桂林书院雯峰书院上饶书院吉安书院抚州书院\n\n应宿第书院怀仁书院问渠书院流坑文馆如蘭书院元猷书院盱江书院◎前言鳌峰书院朱凤巘书院虹高峰书院同文书院云溪书院柳山书院东佳书院江右书院冠华夏净明堂书院之图文长芗书院书院，是中华文化史上一个醒目亮点，是中国教育史上一种独特复礼书院的文化现象。书院，记录了诗书中国。书院的鼎盛，反映的是中华民族对于文化传播与学术自由交流的龙溪书院强烈追求。在古代中国，书院就是一个文化象征的符号，代表的是有',1,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',516,NULL,'2026-08-16 21:12:07'),(2,1,1,1,'书院的鼎盛，反映的是中华民族对于文化传播与学术自由交流的龙溪书院强烈追求。在古代中国，书院就是一个文化象征的符号，代表的是有景德镇书院萍乡书院鹰潭书院九江书院着一定文化水准的话语圈。那些执着于传道的儒家士人满怀学术独立后记与自由的精神向度，在书院的形式助推下探寻着自我思想与现时意识的完美融合。正因为如此，儒家士人往往把书院看成独立研究学问的安身立命之所，捆绑着其“独善其身”的生活道路。书院的创建目的之一就是为了超世脱俗的精神追求。这就是为什么我们今天看到的书院，大都建立在僻静优美的名胜之地。“江右书院甲天下”。在一千多年的古代书院历史中，江西一直是全国书院发展的中心地区，并且数度“独领风骚”，成为中国的一\n\n个文化重地，拥有独特的历史地位。上世纪八十年代，季啸风先生率报国情怀，一代文章节义，乃白鹭洲书院文化之写照。领全国百余学者普查古代书院，发现全国有书院七千三百余所，其中……江西九百九十所，居全国各省之首。而根据江西省地方志办编纂的《江已经远去的是辉煌，不曾离开的是记忆。远去的历史如同人的西书院》最新统计，江西有书院近两千所，比过去统计的数量增加了记忆，会散落太多的碎片，需要重新拾起、还原。也许书志里记录',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:07'),(3,1,1,2,'西书院》最新统计，江西有书院近两千所，比过去统计的数量增加了记忆，会散落太多的碎片，需要重新拾起、还原。也许书志里记录一倍多。的是遥远的抽象故事，而目光所能碰触到的碎片，给予我们的却是江西之美，美在山水；江右之盛，盛在人文。美景看不尽，人文实实在在的景象。捡拾这些碎片，会让我们感受到历史更加鲜活。道不完。当今天我们再去打捞这段历史时，那些曾经遍布在江右大地从历史变迁到自然变幻，总有一些东西是磨灭不了的，虽然无数书上的书院建筑，留给了我们一个渐行渐远的儒雅身影。在浩浩苍穹之院在历朝历代的更替中成为废墟，但在尚存的瓦砾墙垣间，我们依下，莽莽林野之中，那一座座古朴而散落的书院，像是一尊尊历史的然能看到书院曾经的辉煌气势。它更像古代书院制度的一个封存的雕塑，守望在丛林山野或溪泉河畔。在读书人眼里，在文化人心里，标本。那都是一块丰碑，都是一个不可磨灭的印记，都是一座神圣而高雅的标本是用来记忆的，历史是不能忘记的。江右书院已经封存在殿堂。历史记忆里，但其思想与教化的传承却一直延续至今。江西自古人当我们伫立于庐山五老峰下，石门涧近在眼前，枕流溪的溪水从文荟萃，一个很重要的原因就是江西私学自古十分发达。从孔子开',4,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',505,NULL,'2026-08-16 21:12:07'),(4,1,1,3,'当我们伫立于庐山五老峰下，石门涧近在眼前，枕流溪的溪水从文荟萃，一个很重要的原因就是江西私学自古十分发达。从孔子开这里穿越山涧，流向远方，高耸入云的松柏和翠竹隐掩下的白墙灰瓦，私学之风起，孔子弟子澹台灭明就游学南昌，结草为堂，授徒讲学，无不在传说白鹿洞的故事，揭示先贤的哲理。与其说白鹿洞书院供奉尤其唐宋以后江西的书院更是蓬勃兴起：高安桂岩书院和德安东佳着朱子的雕塑，不如说是朱子的《白鹿洞学规》昭告于天下，首创了书院是我国创办最早的私家招徒授业书院；庐山的白鹿洞书院学规中国办学的准绳。成为后世书院准绳；上饶的鹅湖书院首开学术自由辩论之风；吉安之图文江右书院行当我们伫立于徐岩的丹霞三峰山下，赫然醒目的“象山书院”之的白鹭洲书院绵延八百年，至今仍有三千学子，朗朗书声不断。而摩崖石刻让无数的造访者为之震撼，仿佛看见陆九渊“登而乐之，乃到近代，一批优秀的私立学校脱颖而出。尤其是经过改革开放三十建精舍”“宇宙便是吾心，吾心即是宇宙”，学苟闻道，不舍昼夜。多年努力，江西的民办教育从无到有，从小到大，由弱到强，成为在这片茂林修竹的地方，万千莘莘学子从四方聚来，相与讲习的读书全国民办高等教育三强，进入了民办教育大省的行列。',4,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:07'),(5,1,1,4,'在这片茂林修竹的地方，万千莘莘学子从四方聚来，相与讲习的读书全国民办高等教育三强，进入了民办教育大省的行列。书院文化就之声远播信江两岸。这样薪火相传，浸润着一代又一代，渗入魂灵、化作基因。那一片当我们伫立于鹅湖书院，竟不知鹅湖不是湖水而是鹅山，似乎昭源于李白韩愈周敦颐、飘自陆九渊朱熹王阳明的琅琅书声，在新时示“智者乐水，仁者乐山”的哲理。一如当年“鹅湖之会”，学以聚代继续声声入耳、句句传情，让下一代依然优雅如瓷、坚韧如丝。之，问以辩之，行以仁之。从此，百家争鸣成为中国大学学术发展道书院虽然是一种古老的办学模式，但古老并不代表落后，老树路。“尊德性”与“道问学”及无极而太极也，千年话题，一直延展。春深更著花。季羡林先生在《中国书院辞典》序言中写道：“我们以至于辛弃疾与陈亮亦在此“长歌相答，极论世事，纵谈十日，共商可以这样说，在中国流行了一千年的书院这种古老的办学模式，在复国之计”。今天还有其意义。我们完全可以取其精华，去其糟粕，利用这个形式，当我们伫立于赣江之畔，白鹭洲依水而居，章贡合赣，一江赣水加入新的内容，使它为我们的社会主义建设服务。”如今，风靡全',4,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',483,NULL,'2026-08-16 21:12:07'),(6,1,1,5,'当我们伫立于赣江之畔，白鹭洲依水而居，章贡合赣，一江赣水加入新的内容，使它为我们的社会主义建设服务。”如今，风靡全滔滔北去，多少故事从这里演绎成经典，多少人物从这里擢升为圣贤。国的国学传统教育，足以说明书院的魅力与积极作用。“载色载笑，从容水竹间。”从这里走出去的文天祥，写下了“人生书院虽然作为教育主体的地位已不复存在，但是书院的精神血自古谁无死，留取丹心照汗青”的千古绝唱，其一身壮士义胆，一腔脉却在永不间断地传承着。江右书院缔造的“理学”“心学”“汉学”，\n\n以及由它而衍生的大学堂和现今的高等学府，如逐日的夸父，正随着朝阳前行，成为赣鄱大地上一道亮丽的风景。我们在翻看江西师范大学的简介时，“学校缘起于庐山白鹿洞书院”的表述赫然在目。书院已不仅仅是一个供人们参观欣赏的旅游景观。作为江西传统文化的瑰宝，书院文化滋养了一代又一代的江西人，为中国的文化教育事业的发展做出了不可磨灭的贡献，书院绝不能消失，也不会完全废止。但据江西省第三次全国不可移动文物普查统计，全省现有书院仅存一百七十多所。保护与传承书院，是我们后人义不容辞的责任。古人尚且可以“裹粮而来”“结庐而居”，我们完全可以承载历史、精进前行。',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:07'),(7,1,1,6,'保护与传承书院，是我们后人义不容辞的责任。古人尚且可以“裹粮而来”“结庐而居”，我们完全可以承载历史、精进前行。幸运的是，江西各地各有关部门和单位在书院保护、研究、利用方面，持之以恒地做了大量的工作，取得了显著成效。我们欣慰地看到，在保护利用书院文物的过程中，江西省坚持不懈地开展书院研究，初步形成了以高校、书院管委会、部分文化研究单位学者和专业工作者专兼职相结合的研究队伍，出版和发表了一大批有重要影响的学术成果。南昌师范学院书院研究中心就是其中一个以书院为专门研究领域的学术机构，他们对书院文化开展了卓有成效的研究，力图还原江江右书院行右书院的前世今生。这无疑是一件十分有价值的事情，可喜可贺。我们有理由相信，只要我们将书院文化遗产保护工作提升到保护中华文脉、民族基因的高度，以敬畏之心礼敬书院，保护好现存的书院建筑，深入研究书院的内在价值，合理利用书院文化资源，就一定能守护好书院文化之根，再现江右文化的时代光芒。因为，历史给我们的感觉，一直都是如远若离。但，历史与当下相连，从未走远。江西书院遗存分布图\n\n白鹿洞书院四大书院之图文白鹿洞书院石牌坊天下第一书院——白鹿洞',5,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',488,NULL,'2026-08-16 21:12:07'),(8,1,1,7,'但，历史与当下相连，从未走远。江西书院遗存分布图\n\n白鹿洞书院四大书院之图文白鹿洞书院石牌坊天下第一书院——白鹿洞庐山有一座山峰叫五老峰，五老峰的东南峰下有一座书院，书院依山傍水而建，书韵墨香弥久流芳。清代有一位叫王昶的学者，他在《天下书院总志》序中评价这座书院为“天下书院之首”。著名学者胡适1928年游历庐山时也曾到过这座书院，他在《庐山游记》中说，“白鹿洞，代表中国近世七百年的宋学大趋势。”这座书院就是著名的——白鹿洞书院。白鹿洞书院，三面环山，一面临水，山谷盆地，古木参天，清幽匝地，溪中流水潺潺，鸟语花香伴清风明月。这样清静寂寥的环境，确实非常适合读书、研习，它与我们心目中古代学府的印象一拍即合。\n\n那是唐贞元年间，一名叫李渤的读书人与他的哥哥在此隐居读书。据说李渤训养了一头白鹿，通人性，每每悬纸条于鹿角，它便到二十里外的集上替主人购回纸墨，人称“白鹿先生”。后李渤做了江州（今九江）刺史，认为该处为研学之洞天福地，便在此建亭台楼阁，植花草树木，这便是白鹿洞书院的雏形了。北宋初年，江州的乡贤明起等在白鹿洞办起了书院，“白鹿洞书院”从此始，但不久即废。',5,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',484,NULL,'2026-08-16 21:12:07'),(9,1,1,8,'台楼阁，植花草树木，这便是白鹿洞书院的雏形了。北宋初年，江州的乡贤明起等在白鹿洞办起了书院，“白鹿洞书院”从此始，但不久即废。南宋淳熙六年（1179），有一天，知南康军（治今星子县）朱熹带领一群官员兴致勃勃来到白鹿洞书院，展现在他眼前的却是一片断垣残壁，满目疮痍，只有溪涧流水与林中清风依然如故。多么清静、优雅的环境呀！朱熹决心重新修复这座书院。他多次上书朝廷，力陈修复书院的重要性，希望得到朝廷的支持。朱熹在南康任上的几年时间里，为白鹿洞书院竭尽了全力，做了一个读书人为着理想全身投入、孜孜不倦的所有事情，归纳起来有如下这些：第一，重建院宇。第二，遗官帑筹措院田。这是维持书院的长久规划，也是白鹿洞书院存留下来的根本原因。第三，收集书籍。并将一些诗、帖刻石入碑。第四，亲兼洞主。自为导师，开堂讲学，并邀学古石桥思贤台者讲学，开创了“讲会”制度。第五，招收学生。第六，制定学规。在总结前人办学经验教训基础上制定了《白鹿洞书院揭示》，也就是《白鹿洞书院教条》《白鹿洞书院学规》。它成为此后封建社会官学、书院通行的教条规则。第七，订立课程。将《四书》作为基本课程。其余还需学习《五经》《楚辞》及古代诗文。之图文',7,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',503,NULL,'2026-08-16 21:12:07'),(10,1,1,9,'它成为此后封建社会官学、书院通行的教条规则。第七，订立课程。将《四书》作为基本课程。其余还需学习《五经》《楚辞》及古代诗文。之图文一个人做了这么多事情，而且每一件事情都不是简单地一蹴而就，朱熹为此耗尽了江右书院行书院牌匾白鹿洞石刻\n\n之图文江右书院行正学之门前古牌坊\n\n朱子白鹿洞教条之图文高美亭心血，殚精竭虑。在他的努力下，特别是奏请匾额与御书，邀请不同流派学者登堂讲学，制定《白鹿洞书院揭示》，与陆九渊的“南康会”等等，使得白鹿洞书院一时名声大振，影响深远，由此成就了朱熹与白鹿洞书院一段辉煌历史，奠定了白鹿洞书院在宋代“四大书院”（湖南长沙岳麓书院、河南登封嵩阳书院、河南商丘应天书院）首席地位。它还与吉安白鹭洲书院、铅山的鹅湖书院、南昌的豫章书院并称为“江西四大书院”，白鹿洞书院出过３名状元，300名进士，为江西的人才培养作出了贡献。白鹿洞内白鹿雕塑如今的白鹿洞书院，从外表看，其实更像江南水乡的民间大院，青瓦白墙，屋檐四\n\n端翘角如翼。石木与砖木筑就的五个大四合院子，透着明、清建筑风格。它们沿一条溪流纵向推进，每座院子门前流水淙淙，内部又互相串连，曲径通幽。绿树掩映中，一股清幽淡雅的香气悠悠飘拂，令人坠入无尽的遐想之中。',7,'null','{\"page_end\": 10, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',518,NULL,'2026-08-16 21:12:07'),(11,1,1,10,'进，每座院子门前流水淙淙，内部又互相串连，曲径通幽。绿树掩映中，一股清幽淡雅的香气悠悠飘拂，令人坠入无尽的遐想之中。当你的脚步从书院的先贤书院、棂星门院、白鹿书院、紫阳书院、延宾馆五座院子依次流连，当你的眼光停留在朱子祠与孔圣殿悬挂的康熙皇帝的御书匾额“学达性天”“万世师表”，以及孔子、朱子、“二程”（ 程颢、程颐）与周敦颐画像的排列位置上，你该知道朱熹对白鹿洞书院的贡献多么伟大！枕流溪白鹿洞书院的一碑一石都镌江右书院行刻着朱熹为书院所付出的努力。那些碑廊里、摩崖上的石刻书法，或楷、或隶、或篆、或行、或草，醒目灵动，仿佛都在无言诉说书院当年的兴盛。朱熹的《白鹿洞书院揭示》被抄写在黄色布幔上，挂在明伦堂上供人阅读，其内容（五教之目、为学之序、修身之要、处事之要、接物之要）今天读来，仍令人信服、称赞。而当你念到“贯道溪”“枕流桥”这些出自朱熹的命名，御书阁、明伦堂外柱的楹联：“泉清堪洗砚；山秀可藏书”“鹿豕与游，物我相忘之地；泉峰交映，仁智独得之天”。这些与朱熹相关的诗句，你脑海中的朱子形象会越来越清晰、高大、鲜活。你仿佛看见身穿长衫、手拿书卷的朱子正带',10,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',482,NULL,'2026-08-16 21:12:07'),(12,1,1,11,'这些与朱熹相关的诗句，你脑海中的朱子形象会越来越清晰、高大、鲜活。你仿佛看见身穿长衫、手拿书卷的朱子正带着一群学子沐清风明月，伴溪水长流，大声朗诵吟哦，正所谓一幅“书声琅琅之余，有呦呦鹿鸣为伴”场景。其实，朱子复兴白鹿洞书院，年届49岁，正是年富力强干事的最佳时期。与他的为官之政相比，朱子无论在白鹿洞书院建树，还是在理学上的成绩都要出色得多。究其原因，如他一首小诗《观书有感》言明：半亩方塘一鉴开，天光云影共徘徊。问渠那得清如许？慎思门\n\n白鹭洲书院白鹭洲书院大写意千里赣江浩荡北去，流到赣中名城吉安，二水中分一绿洲：其长三里、宽一里，茂林修竹、百鸟栖息。古庐陵一批又一批学子乘舟来此读书，读得海内倾慕、汗青喷香。它就是七百多年来累经毁兴、遐迩闻名的白鹭洲书院。今天，这片中流砥砺的绿洲，已有大桥相连，让繁华的城市拥抱，四周浪花飞溅，道心堂舟楫往来。东边，隔岸的佛教名山——青原山，苍茫叠翠。洲头北部古树丛，隐约两座诗题古壁效青莲”。重檐杰阁、岿然耸立的古楼——白鹭洲书院主体建筑之一的风月楼和云章阁……南宋淳祐元年（1241），新任吉州知府江万里，一位著名忠烈之士，造诣很深的学“三山半落青天外，二水中分白鹭洲”。',10,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',509,NULL,'2026-08-16 21:12:07'),(13,1,1,12,'南宋淳祐元年（1241），新任吉州知府江万里，一位著名忠烈之士，造诣很深的学“三山半落青天外，二水中分白鹭洲”。白鹭洲的得名，源于李白的这句名联。该者，官至宰相。他看见赣江中这一绿洲，心生欢喜，令筑精舍，创“白鹭洲书院”。院洲屹立于浩阔赣江，双水夹流，情景正与李白诗句相合，故用作洲名。北宋宣和年间，内，立文宣王庙、棂星门、云章阁、道心堂、万竹堂、风月楼、浴沂亭、斋舍，后增建“六吉州通判徐俯有“空看白鹭洲” 诗句。南宋初年，尹直卿送周必大诗“我公不向庐陵住，之图文君子祠”，祀程颐、程颢、周敦颐、张载、邵雍、朱熹等六人。羞杀青原白鹭洲”。元代买思永为重修白鹭洲书院作记：“谓洲在二水间，取唐人诗句江右书院行江万里自任山长（校长），讲学其中，“载色载笑，从容于水竹间，忘其为守。”以白鹭名其洲，因以名书院。”本郡俊秀在此求学，如沐春雨，如坐春风。影响巨大，盛极一时：庐陵“制科飙举，名清代吉安知府林逄春的诗句：“庐陵文物照江天，院寺钦崇自昔年。水占芳名分白鹭，白鹭洲全景，中为书院所在地——白鹭洲\n\n（明）汪太守馆例十二条风月楼硕云蒸，几当宇内之半。”春秋间，科甲捷报震四乡。宋宝祐四年（1256），金榜601',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',505,NULL,'2026-08-16 21:12:07'),(14,1,1,13,'（明）汪太守馆例十二条风月楼硕云蒸，几当宇内之半。”春秋间，科甲捷报震四乡。宋宝祐四年（1256），金榜601名进士，吉州占44名，且多为白鹭洲书院学子，为全国之最。文天祥独占鳌头，理宗重修白鹭洲书院记（2014）（清）符山长课规十则皇帝曰：“此天之祥，及宋之瑞也！”御笔题写 “白鹭洲书院”匾额。从此，该书院名扬海内，与庐山白鹿洞书院、铅山鹅湖书院并称江西三大书院。后人访谒白鹭洲书院，感慨系之：“自昔庐陵地，名贤史册香。文章宗永叔，节义重天祥。庐陵学子的表现没让天下失望。国难当头，文天祥的《正气歌》“人生自古谁无死，滟滟清波漾，振振白鹭翔。江公风范在，千古仰遗芳。”之图文留取丹心照汗青”的壮烈爱国情怀，使中国史书为白鹭洲书院写下重重的一笔。“鹅湖鹿洞寻常事，不信风流限古今。”清代曾在白鹭洲书院主持讲席的著名学者江右书院行后来，庐陵郡州内外竞相仿效白鹭洲书院，书院相继建立，士子科举成名，仕宦成群，施闰章如此赞颂白鹭洲。学者成林，作家成派，著述成山，志士成仁。由此，庐陵文化千年昌盛，为江右文化重心。“二月江南花满枝”的季节，我再次走进白鹭洲书院，品读那一副副穿越历史烟云、棂星门全景，书院第一任山长欧阳守道雕像',12,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:07'),(15,1,1,14,'“二月江南花满枝”的季节，我再次走进白鹭洲书院，品读那一副副穿越历史烟云、棂星门全景，书院第一任山长欧阳守道雕像\n\n书院小景书院一角书院一角江右书院行风月楼边汉白玉古吉台书院牌匾\n\n江万里雕塑云章阁饱染书香墨魂的楹联，全间广厦重开，看杰阁层楼，势凌霄汉；五百里德星常聚，合南金东箭，辉映江山。” “芟景式地欣赏“大写意”的其芜，行其涂，似有天作地生之状；视其细，知其大，岂独山原林麓之观。” “陵谷经白鹭洲书院——几迁，此地依然为砥柱；江河同万古，斯文有幸见回澜。”……之图文“鹭飞振振兮，不与江右书院行波上下；地活泼泼也，无分水东西。”“字水文山中山院蔼吉士 ；葭苍露白宛伊人。”“ 智水仁山，日日当前逞道统；礼门义路，人人于此见天心。”“六代暮云沉，试看二水中分，与建业地形似否；一亭春雨霁，惟问四山环抱，比滁洲风景如何。”“白鹭交流，挹注直将分泗水；青螺高峙，步趋端可接尼山。”“风过试留声，檐角振文江之铎；月斜还有影，楼头照字水之书。”“千万书院内门',12,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',429,NULL,'2026-08-16 21:12:07'),(16,2,1,0,'鹅湖书院千年学府——鹅湖书院闻名中外的天下四大书院之一——鹅湖书院位于江西省上饶市铅山县，早在南宋时期就名振武夷了，当时为了纪念大理学家朱熹与陆九渊的“鹅湖之会”而由鹅湖寺改为书院，是理学大儒朱熹、陆九渊、陆九龄、吕祖谦的过化之地，在中国书院史上产生过重要影响, 现为国家重点文物保护单位。鹅湖书院坐落在武夷山余脉风景秀丽的铅山县东南鹅湖山北麓，周围青山环抱、秀“斯文宗主”古牌坊峰拱立，远眺一带信江宛如素练正浣，山垅平坂之中，良田阡陌、溪水成韵，偶尔有几只白鹭从水田中振翅腾飞、翱翔啾鸣，一派典型的江南田园风光。来铅山游历这千年学府，您会被这古朴典雅、清新优美的环境所吸引，会被这闪烁着中华民族文化光彩和浓郁高雅的文化气息所迷恋。这里的每一间房舍，每一块碑刻，每一棵古树，都深含着隽永的老师的桌椅，下面的长方形桌子和条形凳子是生徒读书之地，正面墙上朱熹手书“忠、孝、文化品位，传递着理学文化内涵。廉、节”四个大字，端庄稳健持重敦厚，以示学子为人正直、求学为国报效之意。四进之图文鹅湖书院是五进五出的院落，走进拱型大门，是第一进院，迎面是石牌坊，上书“斯',1,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',477,NULL,'2026-08-16 21:12:07'),(17,2,1,1,'廉、节”四个大字，端庄稳健持重敦厚，以示学子为人正直、求学为国报效之意。四进之图文鹅湖书院是五进五出的院落，走进拱型大门，是第一进院，迎面是石牌坊，上书“斯院落是五间四贤祠，供奉孔子和朱、吕、二陆，每逢孔子及四贤生日或重大节日，全体江右书院行文宗主”和“继往开来”，后面是“状元桥”，据说古代只有考取进士的士子才能通过，师生都要来这里拜祭。五进院落不大，主要是三间御书楼，踏着窄梯上去，会看到上面今天所有游客都可以从桥上走过，体会当年状元郎的感觉。二进院落里有仪门五间，院存放着历代皇帝的赠书、款、匾及藏书。朱红色的御书楼金碧辉煌，飞阁流丹，平地空旷，子里的古香樟和古桂柏，绿树成荫，给人秀丽雅静之感。三进院落是五间讲堂，中间是书院大门全景\n\n花香鸟语，给求学士子一个安静的学习环境。鹅湖书院的建立以及在教育史上和书院史上产生深远的影响，主要是因为这里发生了两次极为著名的“鹅湖之会”——朱熹与陆九渊之会、陈亮与辛弃疾之会。亭上对联南宋淳熙二年（1175），两位当时学术界的巨擘——朱熹和陆九渊，在鹅湖寺进行了一次中国哲学史上少见的辩论，鹅湖寺也因此名声大振。这次鹅湖之会，是当时的明贤吕祖谦牵头，邀',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',500,NULL,'2026-08-16 21:12:07'),(18,2,1,2,'（1175），两位当时学术界的巨擘——朱熹和陆九渊，在鹅湖寺进行了一次中国哲学史上少见的辩论，鹅湖寺也因此名声大振。这次鹅湖之会，是当时的明贤吕祖谦牵头，邀请朱熹与陆九渊、陆九龄兄弟来鹅湖，本意是和会朱陆观点和思想。这次鹅湖之会涉及问题很多，中心是“论及教人”。据《象山年谱》引朱泰卿的回忆，“鹅湖之会，论及教人，元晦之意，欲令人泛观博览而后归之约。二陆之意，欲先发明人之本心而后使之博览。朱以陆之教人太简，陆以朱之教人为支离。陆先生更欲与元晦辩，以为尧舜之前，何书可读，复斋止之”。朱熹主张多读书，多观察事物，根据经验加以分析、综合与归江右书院行朱子手书“节”“孝”朱子手书“忠”“廉”水映古牌坊\n\n纳，然后得出结论。陆氏兄弟则认为，仿淳熙二年“鹅湖故事”，约辛弃疾、心明则万事万物的道理自然贯通，不必朱熹到铅山紫溪相会，讨论世事与学问，多读书，也不必忙于考察外界事物，去朱熹因故没来。陈亮与辛弃疾二人在“鹅此心之蔽，就可以通晓事理，所以尊德性，湖同憩，瓢泉共酌，长歌相达，极论世事，养心神是最重要的，反对多做读书穷理逗留弥旬”，谱写了一曲慷慨激昂的爱之工夫，认为读书不是成为至贤的必由国之歌，成为中国历史上又一段佳话。之路。',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:07'),(19,2,1,3,'逗留弥旬”，谱写了一曲慷慨激昂的爱之工夫，认为读书不是成为至贤的必由国之歌，成为中国历史上又一段佳话。之路。在会上，由于两家学说针锋相对，鹅湖书院于是成为文人墨客寄情山水发互不相让，结果不欢而散，吕祖谦和会思古之幽、挥毫长吟渲郁勃之气的胜地。朱陆宣告失败。此乃第一次鹅湖之会。鹅湖书院被正式命名是到明朝景泰十三年后的淳熙十五年（1188），年间（1454）的事情了，明代宗皇帝十辛弃疾和陈亮也约在鹅湖相会。这年冬分重视书院教育和理学思想，鉴于鹅湖天，南宋著名思想家、文学家陈亮本想书院在江南一带的作用及影响，于是下书院内景陈亮与辛弃疾的鹅湖之会雕塑之图文江右书院行鹅湖书院主楼古碑刻\n\n旨委托大理寺正卿李奎、江西巡抚韩雍对文宗书院重新扩建，增修了泮池、书楼，增建了纪念朱熹、吕祖谦、陆九渊、陆九龄的“四贤祠”，象山书院在祠内重塑了四贤塑像。第一次以鹅湖书院为名招收生徒。鹅湖书院最辉煌时期是在清朝。清顺治四年（1647），江西巡四贤祠内朱、吕、二陆塑像抚蔡士英捐资扩建鹅湖书院，并立碑将其与白鹿洞书院、象山书院、白鹭洲书院一起列为江西四大书院。但是到了康熙五十六年（1717），书院因没有保护与修缮，建筑已经',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:07'),(20,2,1,4,'碑将其与白鹿洞书院、象山书院、白鹭洲书院一起列为江西四大书院。但是到了康熙五十六年（1717），书院因没有保护与修缮，建筑已经破败不堪，于是鹅湖书院进行了历史上规模最大的修复扩建工程，使书院占地面积达2.1万平方米。重泮池修后的鹅湖书院以其恢宏的气势、超大的规模、著名的鹅湖之会和在之图文江南书院中的地位与影响，被誉为江右书院行天下四大书院之一。“象山书院”摩崖石刻陆九渊与象山书院入德之门——穷理居敬贵溪，属信州，地处信江中游。三府（广信府、饶州府、抚州府）交境，为交通便利、市场繁荣、文化先进之地。贵溪为人才之乡。在延续一千多年的科举史上，贵溪先后走出进士近三百名。贵溪拥名山胜迹。春秋时期，智圣鬼谷子驻足云梦山岩洞修道授徒。东汉时，四海云游祖天师张道陵屯足云锦山垒灶炼丹，正一派道教由此而生，改称龙虎山。南宋之际，理学大师陆九渊选址应天山，创办象山精舍，结庐讲学。远看应天山形似一头大象，故改名象山。陆九渊命名书院为“象山精舍”，并自号“象山翁”。象山（应天山）地处上清镇与彭湾乡之间，海拔881米，巍峨峻秀、高耸入云。唐代马祖道一曾在此结庐建寺，因此又叫禅师山。象山是龙虎山国家森林公园的重要组成',4,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',502,NULL,'2026-08-16 21:12:07'),(21,2,1,5,'象山（应天山）地处上清镇与彭湾乡之间，海拔881米，巍峨峻秀、高耸入云。唐代马祖道一曾在此结庐建寺，因此又叫禅师山。象山是龙虎山国家森林公园的重要组成\n\n教学；切己自反、改过迁善的自我修养；偏重精专创新的读书指导；寓教于乐的野游活动。除此之外，陆九渊在象山精舍办学，还有两个突出的特点：一是不用学规，而提倡言传身教、相互感化；二是不拘泥学生斋舍，而要学生结庐而居，携粮就读。遗址残垣一正因为如此，清代全祖望在全面考查书院“始终盛衰兴废”之后指出“岳麓、白鹿……东莱之丽泽，陆氏之象山，并起齐名，四家之徒遍天下”，乃为“南宋之四大书院”。陆九渊在象山精舍讲学历时五年，绍熙二年（1191），奉诏知荆门，临时嘱托傅季“徐岩”摩崖石刻鲁代为主掌。该书院一直延续到宋庆元二年（1196）贵溪知县刘启晖立祠泉山方丈之址。门人“春秋致祭惟谨”，彭世昌曾为其购集图书。绍定三年（1230）杨简门人赵彦械任江西提刑，重修精舍，并作象山书院记。“道在笃行，不在空言；道在返求，不在外骛”。又反复阐明陆学师训：“六经当注我，我何注六经”“反思自得，反而求之”。并反击有人疑陆学为禅的说法乃“是未之思也”。云：“诚意，正心以至治国、平天下，原于之图文',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:07'),(22,2,1,6,'又反复阐明陆学师训：“六经当注我，我何注六经”“反思自得，反而求之”。并反击有人疑陆学为禅的说法乃“是未之思也”。云：“诚意，正心以至治国、平天下，原于之图文致知二字，果禅学乎？”记文又说：“象山盖学者讲肄之地，山空屋倾、将遂湮没。载江右书院行新以存先生之故迹，使人因先生之故迹，思先生之学，思先生之教，孜孜日思，乃至不勉、象山书院复原图部分，重峦叠嶂，飞瀑流泉，原始森林遮天蔽日。应天寺、象山精舍相继选址在此。陆九渊创办的象山精舍，不仅建筑“气象万千”，而且教学和管理都颇具特色。首先，陆九渊规定了“明理、志道、做人”的办学宗旨，确定了以《诗》《书》《礼》《易》《乐》《春秋》《论语》《孟子》以及尚未编印在学徒中相互传抄的《象山先生文集》作为教学的主要内容。为了实践自己的办学主张，陆九渊在象山精舍采用了多种多样的教学形式，运用了一些与众不同的教学方法。诸如严肃认真的升堂讲学；颇似禅宗机锋的谈话遗址残垣二\n\n不思，从容中道，是谓大成。”宋绍定四年（1231），陆九渊的再传弟子江东提刑袁甫，以应天山祠宇荒颓、交通不便为由，将书院改建于县城信江南岸的三峰山下徐岩。书院',5,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',485,NULL,'2026-08-16 21:12:07'),(23,2,1,7,'”宋绍定四年（1231），陆九渊的再传弟子江东提刑袁甫，以应天山祠宇荒颓、交通不便为由，将书院改建于县城信江南岸的三峰山下徐岩。书院落成，袁甫具以本末缘由上奏朝廷，绍定五年（1232）得诏赐“象山书院”匾额。袁甫还为象山书院确立了教育目的——“明道”，并将《陆象山文集》列为书院的教学内容。由于袁甫的亲自谋划，书院日益兴旺，以至“远近学者，闻风云集。”绍定六年（1233）七月，陆九渊故里金溪县令陈咏之建象山书院在县治西，付子云为首任山长。当时听众甚广，士风翕然相善。元代倪堂任江西提举，重修象山书院。明正德五年（1501），武宗皇帝诏刻“象山书院”四字于西峰峭壁。万历八年（1580），书院奉张居正之命废除，改为象山祠。象山书院自迁建于三峰之图文陆九渊雕像书院小径\n\n山以来，前后持续350年之久。后人赋诗云：“千寻峭壁俯青溪，野竹含风弄晚凄。江西书院十大人物祠下几年无过客，崖前此日重留题。未逾沧海难忘楫，欲步丹霄信有梯。帐望讲堂荒草合，日斜惟听鸟声啼。”徐岩旧址现为贵溪一中，校内书院遗址已妥为保护，“象山书院”四个摩崖石韩愈（768—824），字退之，自称“郡望昌黎”，刻大字远远就能看见。',6,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',499,NULL,'2026-08-16 21:12:07'),(24,2,1,8,'址已妥为保护，“象山书院”四个摩崖石韩愈（768—824），字退之，自称“郡望昌黎”，刻大字远远就能看见。世称“昌黎先生”，唐河南河阳（今河南孟州）人。唐代杰出的文学家、思想家、哲学家。元和十四年（819）正月向宪宗上书《论佛骨表》，触怒了迷信佛教的宪宗，由刑部侍郎贬为袁州刺史（宜春太守）。韩愈到袁州后重视教育，为培养造就古袁州人才起到了积极作用，并写下了“莫以宜春远，江山多胜游”等名篇、佳句。为纪念韩愈任袁州刺史时期的功绩，北宋皇祐五年（1053）袁州知州事祖无择于府学明伦堂西侧，兴建韩文公祠崇祀。元末毁于兵火。明正统十四年（1449）之图文袁州知府姚文重建祠于宜春台右侧, 匾曰“昌黎江右书院行书院”。象山书院旁石崖胡仲尧（约934—995），北宋洪州奉新人（今江西奉新县）。胡仲尧在南唐李煜时曾任寺丞之职，入宋后任洪州学助学，以国子监主簿致仕。奉新胡氏是我国历史上有名的聚居家族，合族同居累十数世，义不析爨，室无私财，家族内部治理肃如公门。宋太宗雍熙二年（985）诏旌门闾，胡仲尧诣阙謝恩，获赐白金器二百两。淳化时期，当地因旱歉收，胡仲尧将家族储粮减值以售，使饥民得到赈济。后又',7,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',495,NULL,'2026-08-16 21:12:07'),(25,2,1,9,'宋太宗雍熙二年（985）诏旌门闾，胡仲尧诣阙謝恩，获赐白金器二百两。淳化时期，当地因旱歉收，胡仲尧将家族储粮减值以售，使饥民得到赈济。后又以私财建造南津桥而得到宋太宗嘉奖，准许每年以香稻時果入贡。为扩大家族影响，促进家族发展，据《宋史》记载，胡仲尧构学舍于华林山别墅，聚书万卷，大设厨廩以延四方游学之士，史称华林书院，与德安义门陈氏东佳书堂、建昌洪氏雷塘书院并称为鼎峙江东三书院，名闻天下。象山书院史料图\n\n周敦颐（1017―1073），原名敦实，别称濂溪陆九渊（1139-1193），字子静，号象山，谥文安，先生，又称周元皓，因避宋英宗旧讳改名敦颐，字金溪县陆坊青田村人。南宋著名理学家、思想家和教育茂叔，号濂溪，道州营道楼田堡（今湖南省道县）家，宋明两代“心学”的开山之祖。与朱熹齐名，而见人。北宋五子之一，程朱理学代表人，北宋思想家、解多不合。主“心即理”说，言“宇宙便是吾心，吾心理学家、哲学家、文学家，学界公认的理学鼻祖，即是宇宙”“学苟知道，六经皆我注脚”。南宋淳熙年称“周子”。北宋熙宁五年（1072），周敦颐在九间，陆九渊应门人之谓筑室应天山，创“象山精舍”，江建濂溪书堂，撰《爱莲说》《太极图说》《道书》',7,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:07'),(26,2,1,10,'北宋熙宁五年（1072），周敦颐在九间，陆九渊应门人之谓筑室应天山，创“象山精舍”，江建濂溪书堂，撰《爱莲说》《太极图说》《道书》门徒云集，结庐而居。陆揖升讲座，从容授学，后之成等著作，开理学与书院结合之先河。江西萍乡、赣州、为赣学大本营。明王守仁继承发展陆九渊之学，成为“陆修水等地多有濂溪书院之建。王学派”，对后世影响极大。江万里（1198-1275），名临，字子远，号古心，曾巩（1019—1083），字子固，建昌军南丰（今南康军都昌（今江西省都昌县）人。南宋著名爱国丞相，江西省南丰县）人，后居临川。北宋散文家、史学家、民族英雄，是南宋末年士林和文坛领袖，著名的政治家政治家。曾巩文学成就突出，其文“古雅、平正、冲和”，和教育家。创办的白鹭洲书院，千年来培养出文天祥等位列唐宋八大家之一，世称“南丰先生”。北宋至和17位状元，2700多名进士。任正式官职91种，三度为相;二年（1055），曾巩创办兴鲁书院，意在“兴五帝三一生为官清廉，政绩斐然，直言敢谏，忧国爱民。在国王之道”“上承曾子之家学，以继周公孔子之传者”。破家亡之际，江万里与其子江镐，毅然率180多家人兴鲁书院创建后，曾巩亲自讲学，制定学规，还经常邀',8,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:07'),(27,2,1,11,'王之道”“上承曾子之家学，以继周公孔子之传者”。破家亡之际，江万里与其子江镐，毅然率180多家人兴鲁书院创建后，曾巩亲自讲学，制定学规，还经常邀之图文投止水池殉国，希望以自己及家人之死唤醒“天下忠义请知名学者莅院讲学，为抚州培育出了大批优秀人才，江右书院行节烈之士闻风而起，聚集万千众人之力，保江山社稷不兴鲁学院或为抚州书院杰出代表。移腥膻，道德文章不堕宇内”，其一生堪称古今之完人，千古道德风范之楷模。朱熹（1130—1200），字元晦，一字仲晦，号晦庵，吴澄（1249-1333），字幼清，晚字伯清，元抚州崇晚称晦翁，又称紫阳先生、考亭先生，谥文，又称朱仁凤岗咸口（今属江西省乐安县）人。自幼聪慧、勤奋好学，文公，南宋江南东路徽州婺源（今江西婺源）人。南宋末中试乡贡。宋亡后隐居家乡，潜心著述，学界称其为“草宋理学家，理学集大成者，尊称朱子。朱熹家境穷困，庐”先生。元武宗至大元年（1308），被征召任国子监自小聪颖，弱冠及第，绍兴十八年中进士，历高孝光丞，至治元年（1321）任翰林学士; 泰定元年（1324）宁四朝。于建阳云谷结草堂名“晦庵”，在此讲学，为经筵讲官，敕修《英宗实录》。其核定《老子》《庄子》',8,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:07'),(28,2,1,12,'丞，至治元年（1321）任翰林学士; 泰定元年（1324）宁四朝。于建阳云谷结草堂名“晦庵”，在此讲学，为经筵讲官，敕修《英宗实录》。其核定《老子》《庄子》世称“考亭学派”，承北宋周敦颐与二程学说，创立《大玄经》《乐律》《八阵图》等，对《易》《春秋》《礼宋代研究哲理的学风，称为理学。其著作甚多，辑定《大记》及郭璞《葬书》均有纂言。元统元年因病逝世，谥“文学》《中庸》《论语》《孟子》为四书作为教本。朱正”，有《吴文正公全集》传世。吴澄是元代杰出的理学家、子淳熙六年兴复白鹿洞书院，亲订《白鹿洞书院揭示》，经学家、教育家，他与当世经学大师许衡齐名，并称为“北使之成为天下学宫、书院之通规，其有功于书院大矣。许南吴”，以其毕生精力为元朝儒学的传播和发展做出了重要贡献。\n\n胡居仁（1434-1484），字叔心，号敬斋，余干县梅港人。明朝理学家、书院教育家。幼时聪敏异常，时江西书院十大事件人谓之“神童”。师事崇仁硕儒吴与弼，而醇正笃实，饱读儒家经典，尤致力于程朱理学，过于其师。常与友人陈献章、娄谅、张元祯等人交游，吟诗作赋，遂成“余干之学”，名闻当时，影响后世。胡居仁绝意仕进，筑东佳书堂位于德安县，',8,'null','{\"page_end\": 9, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',500,NULL,'2026-08-16 21:12:07'),(29,2,1,13,'人陈献章、娄谅、张元祯等人交游，吟诗作赋，遂成“余干之学”，名闻当时，影响后世。胡居仁绝意仕进，筑东佳书堂位于德安县，室山中，学者日众，先后创办丽泽堂、南谷书院、碧峰建于唐大顺元年前后（890），为江州义门陈氏的高等学堂。书院等。曾两主白鹿洞书院，以布衣终身，万历中追谥东佳书堂是目前所知史料最“文敬”。为可靠的始建于唐代的书院代表，是中国书院发展史上的第一个里程碑，作为书院东佳书堂的设立王守仁（1472—1529），字伯安，别号阳明，浙早期形态的代表，标志着书江绍兴府余姚县（今属宁波余姚）人。因曾筑室于会稽院在民间的兴起。山阳明洞，自号阳明子，学者称之为阳明先生。明代著名的思想家、文学家、哲学家和军事家，陆王心学之集大成者，精通儒家、道家、佛家。王守仁（心学集大成者）和孔子（儒学创始人）、孟子（儒学集大成者）、朱熹（理学集大成者）并称为孔、孟、朱、王。其学术之图文江右书院行思想传至日本、朝鲜半岛以及东南亚，产生了重要而深远的影响。阳明先生之武功、文治多成就于江右，阳明及其后学对于推动明代江西书院讲会与会讲功莫大焉，故赣州、吉安多有阳明书院之建。\n\n华林书院位于奉新县，创始人为南唐胡仲尧，北宋时期，宋真宗',9,'null','{\"page_end\": 10, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',509,NULL,'2026-08-16 21:12:07'),(30,2,1,14,'及其后学对于推动明代江西书院讲会与会讲功莫大焉，故赣州、吉安多有阳明书院之建。\n\n华林书院位于奉新县，创始人为南唐胡仲尧，北宋时期，宋真宗曾御笔赐诗称“一门三刺史，四代五尚书。他族未闻有，朕今止见胡”。华林书院文学派和道教色彩浓厚，也是目前所胡仲尧兴华林书院知我国最早招收女性的学校，为胡氏培养了许多杰出人才。之图文江右书院行匡山书院位于泰和县，建于后唐长兴年间（930-933），后唐明宗李嗣源敕翰林学士赵凤书“匡山书院”额并旌表，称书院“馆起匡山之下，民风日盛……而风教之裨未必无小补焉”，此为中国书院史上第一个由皇帝唐明宗敕额匡山书院发布褒旌书院的文告，表明民间书院得到最高当局的肯定。\n\n南宋淳熙六年（1179），朱熹知南康军，不遗余力兴复“莽为榛墟”的白鹿洞书院，他身兼洞主，亲订《白鹿洞书院揭示》，书院为之大盛。《白鹿洞书院揭示》经宋理宗颁赐天下，成为天下学宫、书院之通规。书院因之被称为“天下书院之首”“海内书院之一”，是中国书院文化最杰出的代表。朱熹亲订︽白鹿洞书院揭示︾之图文江右书院行南宋淳熙二年（1175），朱熹、吕祖谦、陆九渊、陆九龄等人会讲于铅山鹅湖寺，讨论“尊德性”与“道问学”及无极而太极等问题，',9,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',513,NULL,'2026-08-16 21:12:07'),(31,2,1,15,'南宋淳熙二年（1175），朱熹、吕祖谦、陆九渊、陆九龄等人会讲于铅山鹅湖寺，讨论“尊德性”与“道问学”及无极而太极等问题，朱陆“相与讲其所闻之学”，各持己见，不合而罢，史称“鹅湖之会”。后人遂于会讲地建四先生祠，并发展为鹅湖书院。因著名的“鹅湖之会”而兴起的鹅湖书院是我国古代不同学派相互争鸣、君子和而不同精神的写照，在思想史、哲学史、文化史、教育史上有着极其重要的地位。﹃尊德性﹄与﹃道问学﹄的鹅湖之会\n\n南宋淳熙年间大儒陆九渊应门生彭世昌之请结庐贵溪应天山讲学，陆九渊“登而乐之，乃建精舍”，陆门弟子“结庐而居”“裹粮相迎”“相与讲习”，前后五年达数千人。象山精舍后迁至贵溪县城外三峰山之徐岩，宋理宗为之赐额，成为南宋时期象山象山精舍与赣学的兴起学派中心，是以陆九渊为代表的赣学兴起的重要标志。之图文江右书院行白鹭洲书院在吉安市区，南宋淳祐元年江万里建于赣江中央白鹭洲上。书院初建江万里自任导师，教学生徒，“载色载笑，从容水竹间”。白鹭洲书院培养了民族英雄文天祥、爱国词人邓光荐、刘辰翁等名垂青史的历史人物，成为江西“文章节义之邦”白鹭洲书院的﹃文章节义﹄的杰出代表。\n\n清光绪年间，散居于赣西北的客籍人士因土籍士绅的抵制，在求',11,'null','{\"page_end\": 13, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',516,NULL,'2026-08-16 21:12:07'),(32,2,1,16,'江西“文章节义之邦”白鹭洲书院的﹃文章节义﹄的杰出代表。\n\n清光绪年间，散居于赣西北的客籍人士因土籍士绅的抵制，在求学上受到限制，遂众筹捐金，于当时的义宁州铜鼓厅创立奎光书院，专课客籍生徒，遂使书院成为赣西北客家人创立的第一所书院，影响奎光书院与客家文化深远。土客分而治学，也是江西书院文化的一个特别现象。之图文江右书院行清雍正十一年颁发上谕，命在各省省会设立省会书院，并拨帑金白银1000两予以支持，南昌豫章书院的改建为此谕令之产物，从此豫章书院成为巡抚负责督办的省级书院。省会书院的设立表明政府出于治化的需要对书院控制的加深，书院的发展步入了一个民省会豫章书院的设立间性与自由度让渡到政府主导的时期，从书院存在的逻辑与合法性而言，书院退出历史舞台从此无可避免。\n\n潋江书院在兴国县，建于清乾隆年间，形制完整，规制完备，雄伟壮观。大革命时期，红四军党代表毛泽东在潋江书院传达中共六大会议精神并主办土地革命干部培训班，1930年至1934潋江书院与红色故土年，书院为兴国县苏维埃政府所在地，潋江书院成为江西红色书院的代表。南昌书院江右书院行',12,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',470,NULL,'2026-08-16 21:12:07'),(33,3,1,0,'豫章书院唯见豫章又新姿豫章书院的旧址，在一个小巷子中的南昌市第十八中学。巷子并非诗人眼中的雨巷，而极其逼仄、拥挤，但仍无法遮蔽那弥漫的人文气息，从书院旧址走出来的十八中学子都是丹青妙手，婉转歌喉。其实巷子并非无名小巷，巷口有一石碑——书院街。穿过书院街走进十八中，除了门前松柏树下的“豫章书院旧址”之图文江右书院行石碑和校内文化墙上有关于豫豫章书院旧址所在街道——书院街十八中内书院文化墙章书院的介绍性文字，已不见一丝古书院的痕迹。出来与校门口的老门卫问询，他坦言：“这天，亦不过是一具缺少灵魂的空壳，或者只是作为城市点缀的景点花瓶。人们关心着新里就是曾经的豫章书院。后来建的购物中心，会关心一座苟延残喘、无人问津的古老书院吗？人们顾着报辅导班、请失火焚毁了，便没有重建。”家教让孩子成为应试教育下的佼佼者，会关注古人格物致知、谈经论道的求知精神吗？一个传承了上千年尚且绵延不人们记得今年高考文理状元皆来自师大附中，但会记得罗从彦、陆九韶这些大儒名士皆断的书院，却在如此近的时期来自豫章书院吗？戛然而止，然后被新建的城市答案不言而喻。与其形在神灭，让书院徒有其表地存在着、荒芜着、被人遗忘着，中的人们安然忘却，连灰烬都',1,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',509,NULL,'2026-08-16 21:12:07'),(34,3,1,1,'戛然而止，然后被新建的城市答案不言而喻。与其形在神灭，让书院徒有其表地存在着、荒芜着、被人遗忘着，中的人们安然忘却，连灰烬都不如灰飞烟灭——痛痛快快地消散，留给世人孤傲决绝的背影，敲响世间文物保护的警无处可寻。钟。“昔时金阶白玉堂，即今“昔时金阶白玉堂，即今唯见青松在。”而后再读这句诗，心中多了些许欣慰和希唯见青松在。”我久久凝望那冀——豫章书院里传播的豫章文化、豫章精神，一定是文化夜空中的一颗璀璨星斗。校门口仅存的松柏，默默无语。豫章先生罗从彦一生淡泊名利，在坎坷的治学之路上踽踽独行。他于豫章书院讲学，我不愿斥责前人缺少文物保护深居简出，粗茶淡饭，短褐穿结，徒步治学。先生刻苦求学又倾囊相授的精神促使他所观念，我想即使把它保留至今十八中门口“豫章书院旧址”石碑在的豫章书院不断发展壮大，桃李满天下。随着罗氏后人的生齿蕃衍，分枝散叶，福建、\n\n广东还有豫章书院之建。2011年秋，豫章书院在停办109年后拿到了国家教育行政部门批复，在南昌市罗家濡溪村重办，“豫章书院”重生。其首任山长为原南昌市市长李豆罗先生，现任执行山长为吴军豹。新豫章书院重新发掘豫章书院的学约制度，并取得了国家商标总局的“豫',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',501,NULL,'2026-08-16 21:12:07'),(35,3,1,2,'其首任山长为原南昌市市长李豆罗先生，现任执行山长为吴军豹。新豫章书院重新发掘豫章书院的学约制度，并取得了国家商标总局的“豫章书院”注册商标，为保护豫章书院文脉起到了重要作用。我想，相比于重建书院，更为重要的是传承和弘扬书院内在的治学精神和思想文化，是弘扬豫章文人的气度与风骨。这才是豫章文化的胜利！“昔时金阶白玉堂，即今唯见青松在。”三吟这句诗，我心中只剩敬意与骄傲。金阶白玉终留不住，只愿豫章文化宛如松柏常青，万古长存！新豫章书院照壁新豫章书院正门之图文新豫章书院膳堂新豫章书院邀月台\n\n友教书院友教书院苦寻踪友教书院坐落在哪？听得见我们寻觅的呼唤吗？美丽荡漾的东湖畔，古老繁荣的苏新豫章书院乐礼堂老豫章书院牌匾圃路上，坐落着南昌第二中学，其现址即是友教书院的故地。据史料记载，友教书院，又名澹台祠书院，一说为友教堂，位于永和门附近。南宋初年，豫章郡守程大昌创建书院于澹台灭明墓前。南宋绍兴年间，洪州地方官钟薄发现澹台灭明墓，为之修澹台祠，后改为友教书院。清顺治十年，巡抚蔡士英重修，规模宏大，生徒云集，教养斐然，与白鹿洞书院、白鹭洲书院、鹅湖书院并称江西四大书院。1896年，友教书院成为近代全国最早改良的书院之一。',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:07'),(36,3,1,3,'生徒云集，教养斐然，与白鹿洞书院、白鹭洲书院、鹅湖书院并称江西四大书院。1896年，友教书院成为近代全国最早改良的书院之一。清末，光绪帝废八股，兴学堂，友教书院结束了一千多年的使命，改之为学堂。友教书院坐落于南昌，占尽天时地利，院资颇富。据史料记载，嘉庆九年（1804），江西巡抚秦承恩借友教书院存银2000两，为白鹿洞书院置田，并重修书院，彼时白鹿之图文江右书院行新豫章书院文瑞堂，古籍陈列室\n\n东湖书院东湖书院小巷深书院位于东湖西畔，所以竖匾额曰：“东湖书院”。沿着杂乱无章的巷道，从东湖的西侧，找到了东湖书院的旧址，高高的残墙上钉有一块路牌“东湖书院巷”。青砖裸露，树藤攀沿，一棵不知名的杂树，既看不出古老，也看不清年轮，树沿着高墙向高处去与四周的高楼争夺阳光……东湖书院在历史的长河中的确几经兴毁，但历代贤臣对修复书院矢志不移，葺修不辍。元代末年，东湖书院仍然相继不衰，伯颜子中、黄译（字楚望）俩人，先后担任东湖书院山长。黄译任东湖书院山长时，曾经揭六经疑义一千多条以教学生，后以年迈归家，不复教授。明初以后，东湖书院又几经兴废，以其地为南昌县学。之图文',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',481,NULL,'2026-08-16 21:12:07'),(37,3,1,4,'黄译任东湖书院山长时，曾经揭六经疑义一千多条以教学生，后以年迈归家，不复教授。明初以后，东湖书院又几经兴废，以其地为南昌县学。之图文清嘉庆五年（1800），罗山进士黎承惠（字湛溪），以星子县令调任南昌，时南昌江右书院行士绅以东湖书院废达五六百年，请求黎承惠予以复建，以重教化。黎承惠虽嘉其志，因府库空虚，无款可筹，又无适当地址可供选择，因而搁下。嘉庆八年（1803），正巧百花洲畔有前任陶公寓馆一所，地广两百余丈，有屋仓六十多间，索价两千金出售，黎承惠得悉后第一个捐俸购买，随后一些士绅学人也争相捐款，将陶氏馆舍买下，并着手重建东湖书院。经过一番整旧改建后，共有先生讲堂、弟子斋舍一百一十间。整个工程从九月下旬开始，到腊月中旬宣告落成，从此书院又复得振兴，文风又复得蒸蔚了！澹台灭明文化广场石刻继任南昌县令的为陆冰。陆氏也很重视书院的建设，他继承黎氏所制订的有关书院洞书院已亏空白银7000余两，以致“院长修缮有缺，生徒膏火不给”。的学规，并加以增修，规定每月朔（初一日）、望（十五日）为艺文，详加考核。陆氏认为，“千古有同心，不外这知行并进；六经皆注脚，须说得利义分明。”当年友教书院',4,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',493,NULL,'2026-08-16 21:12:07'),(38,3,1,5,'的学规，并加以增修，规定每月朔（初一日）、望（十五日）为艺文，详加考核。陆氏认为，“千古有同心，不外这知行并进；六经皆注脚，须说得利义分明。”当年友教书院政贵有恒，学尤贵有恒，因而题其讲堂曰：“恒俾多士，慎修思永，共励此通经致用之才，的这副对联虽仅见于史册，但不难想见当年书院的气魄与精神。并望后之为宰者，率由旧章，以培兹书院于久远……”曾经盛及一时的友教书院，已经谢幕了，淡出了历史舞台，“澹台灭明”几乎被这此后，东湖书院由于得到了南昌士绅的积极捐助，虽几经兵燹，均得以继续巩固和个城市所忘记。好在有我们这些个执着的人、坚守的人、淡泊的人。无论历史走出多远，发展。我们都会携手同心地去寻找，哪怕一直寻找到我们生命的尽头，也会义无反顾，在所不光绪二十八年（1902）后，西学东渐，推行变法，废科举，各省相继设立学堂，东辞！湖书院也随之改为东湖学堂。秋天，风轻云淡，气畅人爽。我们从沉重中走出来，轻松地面对人生，释然如初……\n\n墨庄书院之图文墨庄门前庭院——砥园墨庄萧萧守诚斋群山环抱里，一片一片的浓荫，将盘山小路点缀起夏日的气息。墨庄，一个美丽而神秘的名字。墨，让人自然而然地想起那墨黑的飞檐，那笔墨的书香，那翰墨世家幽静',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:07'),(39,3,1,6,'群山环抱里，一片一片的浓荫，将盘山小路点缀起夏日的气息。墨庄，一个美丽而神秘的名字。墨，让人自然而然地想起那墨黑的飞檐，那笔墨的书香，那翰墨世家幽静而清雅的气质。安义古村，枕了千年的风霜雨雪，依然静静地卧在那里，古老而静谧。我轻轻走近古村，去寻找传说中神秘的书院——墨庄。走过崇德门，穿过古戏台，漫步曦庐旁，不经意地一瞥，竟是看到了墨庄。已没有了神秘与震撼，只剩下惋惜和风霜。昔日的学堂，今日的苍凉。步入庭院，从左至右依次是四间厢房。有先生居室及公子、小姐书屋，有被称之为东湖书院巷\n\n“养拙斋”的藏书室，下面则雕不同的图案象征祥瑞，或为花鸟，甚至有习练琴棋书画的或为池鱼。宽大的正厅里，庄严的孔子画场所—守诚斋。然而像下，摆放着一张长长的书案，案上陈列仅仅能够通过那门联上着文房四宝。只可惜案几落满尘埃，砚台的刻字和介绍，才能辨的墨水已干，宣纸更是蜡黄褶皱。只有画别出它本来的作用，紧像里的孔子，用那温和仁爱的目光，依旧闭的门里透过雕纹细缝墨庄先生居室注视着来人。看去，这里已被挪为他背对正厅，对面的墙壁上赫然刻着用，摆上了新式的锅“静”字，意为：宁静致远。这让人回想碗瓢盆。曾经的琴棋书起百年前，这里是否是繁华小镇中最清净、',5,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:07'),(40,3,1,7,'用，摆上了新式的锅“静”字，意为：宁静致远。这让人回想碗瓢盆。曾经的琴棋书起百年前，这里是否是繁华小镇中最清净、画变为了现在的柴盐酱圣洁的一隅？读书者，重在静心二字。古醋，不禁让人扼腕叹息。人从寒窗苦读到金榜题名，犹如一个漫长正厅的门雕非常修道的过程。没有一颗静心，难以成大事。讲究，门腰中间是一个“人世几回伤往事，山形依旧枕寒习练琴棋书画的场所——“守诚斋”写意的行楷“福”字，流。”不知怎么，我突然想到了这句诗。三百年来，从兴起到鼎盛，再从鼎盛到衰微，多少伤心皆成往事。墨庄也好，安义也罢，不过是一个曾经美丽的印象。只有梅岭群之图文山，依旧枕着雾霭流岚，静静地看淡沧海江右书院行桑田。京台村清代石门坊先生居室与书堂间的天井石门坊上所嵌“绩绍中磊”石碑讲堂门上“燕灵桂馥”门额讲堂内部陈设\n\n阳明书院赣州书院之图文阳明院郁孤台下阳明院南宋著名诗人辛弃疾写过一首词“郁孤台下清江水，中间多少行人泪？西北望长安，可怜无数山。青山遮不住，毕竟东流去。江晚正愁余，山深闻鹧鸪。”在中国不知道“青山遮不住，毕竟东流去”的人几乎难找，但知道赣州郁孤台的人确实不多，而郁孤台边还有一个阳明院， 更是知之甚少、甚微、甚寡。',6,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:07'),(41,3,1,8,'山遮不住，毕竟东流去”的人几乎难找，但知道赣州郁孤台的人确实不多，而郁孤台边还有一个阳明院， 更是知之甚少、甚微、甚寡。阳明院坐落在赣州一中的校园内，雨过天晴，我与同事背着相机造访阳明院。当我们走进校园时，顿觉与其他的现代校园大不一样，仿佛走进了一座古建筑的博物馆，有一座飞檐翘角、红墙灰瓦的寺院，名为“光孝寺”；一口碧水清冽、围砌精致的古井，又名“廉泉”；一棵虬根盘亘、气贯凌空的大树，且名古榕树；一个造型别致、古朴风\n\n阳明院内景夜话亭内“苏阳二公夜话图”石碑之图文阳明院旁古榕树情的长亭，取名“听泉亭”；一幢古老如初、天井四合的小楼，正名“阳明院”……整个校园，古迹众多，古书院的风情、风景、风范犹存。而且每一座古寺、每一棵古树，每一口古井，每一个古亭，每一处古屋都有一个故事，都有一段传奇……阳明书院，原名濂溪书院，明正德年间，南赣巡抚、佥都御史王守仁巡抚赣南时，在书院演讲“致良知”学说。明崇祯十三年（1640）改名廉泉书院，迁于光孝寺旁，清道光二十二年（1842）在原址上重建书院，改名“阳明院”。光绪二十八年（1902）知府查恩绥改书院为赣州府立中学堂。写阳明书院，就不能不写古井。',7,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',498,NULL,'2026-08-16 21:12:07'),(42,3,1,9,'道光二十二年（1842）在原址上重建书院，改名“阳明院”。光绪二十八年（1902）知府查恩绥改书院为赣州府立中学堂。写阳明书院，就不能不写古井。廉泉为赣州市著名的古迹，有1500多年的历史，据说在北宋绍圣年间，苏东坡因反对王安石变法而被贬到惠州。路过赣州时，苏东坡拜访了当时著名的隐士阳孝本，两人很是投机，一同遍访当地名胜，在廉泉水边通宵长谈。后来人们在泉边建了夜话亭，在亭中竖了一块高大的石碑，上刻“苏阳二公夜话图”。一副对联“照影廉泉无愧色；倚亭夜话有知音”。写阳明书院，就不能不写古寺院。\n\n在阳明书院旁有一座千年古刹，因此未见到书院先见古寺。据考证，光孝寺为赣州三戒深省修养古今硕彦星驰”。首座寺院，与第一座道观——上坛观并称。光孝寺内有一口大钟，钟悬于寺侧，“晓击写阳明书院，就不能不写古树。则破长夜，警睡眠；暮击则觉昏衢，疏冥昧。”其所发之音或称鲸音，在古虔州好比是在阳明院门口，有一株十几人合抱粗唤人晨起晚眠的信号，陪伴了一代又一代人。的大榕树。我不是生物学专家，无法考究写阳明书院，就不能不写古亭。眼前这棵大榕树的年龄，是王阳明先生亲走进阳明书院，映入眼帘的便是一座造型古朴的风雨亭，名曰“知觉亭”，亭上有联“凭',8,'null','{\"page_end\": 9, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:07'),(43,3,1,10,'眼前这棵大榕树的年龄，是王阳明先生亲走进阳明书院，映入眼帘的便是一座造型古朴的风雨亭，名曰“知觉亭”，亭上有联“凭种的吗？赣州又称虔州，还称之为宋城，栏送目，榴红草绿堪怡性；倚案凝神，日丽风清好读书”，“四时广学格致中外俊才骥列；这榕树会不会是宋朝的呢？苏轼东坡先生也不给我留下一些什么话来，王守仁阳明先生也没有任何的记载。我想，这也无妨。古树一定见证了历史，古树伴着古书院走过了春夏秋冬。故人西辞，古树尚在，我们的书院文化一如古树，万古长青。写阳明书院，就不能不写古宅。绿树掩映下，一栋两层的砖瓦结构的房子，当门额上一块牌匾“阳明院”。拾古榕掩映下的阳明院级而上，转过一条甬道，来到门庭，门虚掩着，推门而入，是一个既不传统，也不现代，既有北方的特点，又有南方风范的四合院建筑。说中式的吧，又有一点西洋的味道，之图文说南方的粉墙黛瓦，又有一点北方四合院的特质。门口嵌有一块花岗石，上面镂刻了王江右书院行阳明的生平和肖像。离开赣州时，大雨滂沱， “风声、雨声、读书声，声声入耳”，风雨中赣州市渐渐远去，但阳明书院一直在我心中。那些莘莘学子，风雨无阻，行走在求学路上。也许，这就是书院文化不倒的至根至本。知觉亭阳明院旁的光孝寺',9,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:07'),(44,3,1,11,'远去，但阳明书院一直在我心中。那些莘莘学子，风雨无阻，行走在求学路上。也许，这就是书院文化不倒的至根至本。知觉亭阳明院旁的光孝寺\n\n夜话亭廉泉江右书院行阳明院内庭院阳明院旁古井——三潮井\n\n潋江书院书院墨香过潋江静静的潋江书院，坐落在潋江之滨的文昌路西侧。据同治《兴国县志》载：潋江书“模范兴国”牌匾院始创于清康熙五十七年（1718），在城北瑶冈之麓。乾隆三年（1738），由兴国知县徐大坤迁建于今址。而现在你所看到的书院，则是20世纪70年代末由国家文物局和江猛抬头，有雕梁画栋，为讲堂。讲堂为砖木结构，一厅二间，讲堂上方“模范兴国”匾西省人民政府拨款按原貌全面修复建成的。由毛泽东题写。穿过讲堂，跨过天井，来到拜亭。魁星阁则位于拜亭之后，比拜亭高五书院由门庭、讲堂、拜亭、魁星阁、文昌宫、崇圣祠和“三程过化”牌坊等组成。级石阶，重檐歇山顶，阁顶有堆塑“双龙戏珠”。正面两檐之间有“魁星阁”三字的横额，整个建筑雄伟壮观，气势恢宏，具有浓郁的民族特色和地方特点。悬挂于阁顶和阁棚之间。当年，毛泽东就在这里热情接待来访的苏区干部和当地群众。书院右前方为牌坊式门楼，门额上楷书阳刻“潋江书院”四个遒劲大字。跨过门庭，',9,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',506,NULL,'2026-08-16 21:12:07'),(45,3,1,12,'当年，毛泽东就在这里热情接待来访的苏区干部和当地群众。书院右前方为牌坊式门楼，门额上楷书阳刻“潋江书院”四个遒劲大字。跨过门庭，文昌宫是毛泽东旧居和办公旧址，至今仍保存有他当年用过的东西。进入中庭，铺砌着厚实的青砖，整齐有序，历经岁月风雨的侵蚀，履痕深深。上石阶，古代建筑中，有一类独具特色的建筑，即“庙学合一”建筑。潋江书院即是这种在古代建筑中也少见的建筑群体。尤其在文昌宫东侧有一座崇圣祠，初为庙宇，是祀供圣人先贤的，20世纪30年代初期，毛泽东曾在这里举办“土地革命干部训练班”，又将之图文此作为讲堂，从而与“庙学合一”建筑初衷取得完美结合。江右书院行祠前，立有四柱三间红石牌坊一座，是为“三程过化”牌坊。“三程”即程珦与其书院门楼“秀汇双江”门庭\n\n讲堂“三程过化”牌坊二子程颢、程颐。“三程过化”牌坊要比潋江书院的历史久远数百年。宋仁宗庆历四年（1044）洛阳人大中大夫程珦以大理寺丞来兴国知县事，其子程颢、程颐随父来兴国暂居侍读，师从时任南安军（即今大余）司理参军周敦颐。自三程过化，兴国的学堂、县学逐渐兴办，兴国百姓从此崇圣祠儒雅尚文，悉心求学。潋江书院历经几个世纪，几经毁弃，又几经重建，增建，江右书院行',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:07'),(46,3,1,13,'国的学堂、县学逐渐兴办，兴国百姓从此崇圣祠儒雅尚文，悉心求学。潋江书院历经几个世纪，几经毁弃，又几经重建，增建，江右书院行修补，使之渐臻完备。这是中华民族传统文化的结晶，这是将军县兴国人的骄傲，同时也是客家人的一份荣光！“三程过化”牌坊侧景\n\n易堂书院江右书院行易堂九子雕塑翠微峰高书声远宁都有个翠微峰无人不知无人不晓，但翠微峰上有个“空中学堂”——易堂，知之者甚少。翠微峰上竹树杂生，颇有苍翠之气。峰顶虽然宽度不大，而狭长的两端却有八百多米。漫游之后，我们找到一块平地，有人挖出几块古砖，砖上刻有卦象，四断二连，是“震”卦。卦象下端是“草堂”二字，这一定是易堂古砖了。找到易堂遗址，我们都非常兴奋。据说“易堂九子”在此读史讲经、授徒造士达六十余年。“易堂九子”是指明末清初以魏禧为首的九位文学家。他们分别是魏祥、魏禧、魏礼、李腾蛟、彭任、曾灿、林时益、彭士望、邱维屏。以魏禧为首的“易堂九子”于巍巍峰巅结庐盖舍，躬耕自给，聚居“易堂”，讲“易”读史，切磋学问，以培养经世有用之才为己任，使求学者遍布数十县著作上千卷。尤以魏禧著述最丰，与侯方域、汪琬并称“清初散文三大家”。翠微峰主峰',12,'null','{\"page_end\": 13, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',492,NULL,'2026-08-16 21:12:07'),(47,3,1,14,'才为己任，使求学者遍布数十县著作上千卷。尤以魏禧著述最丰，与侯方域、汪琬并称“清初散文三大家”。翠微峰主峰\n\n据彭士望《翠微峰易堂记》载：易堂居翠微峰中段，土木结构，左右并列两进厢房，是“三魏”父母的住房和魏祥的“东庑”、邱维屏的“慢庑”。沿山顶绝崖建有房屋数间，是林时益、彭士望、李腾蛟、曾灿的居室。魏禧的“勺庭”，在易堂西北，“广榭阑干廊步，花木纷呈”。经易堂后圃登百级台阶，有莲池一泓，池边有腊梅、竹子、桃花、梧桐等，新安书院四时花不绝。士望有诗曰：“云中莲叶秋池艳，天半桃花春井香”。1650年，十万清兵围宁都。伯子魏祥冒险进城斡旋，挽救了全城百姓的性命。1677年，黑白遗画卷帙中吴三桂的部将韩大任十万败军两次经过宁都上三乡，伯子遂遇害。中国的文脉，正是在以“易堂九子”为代表的文人志士那种“真不怕死”的精神中虔州城东北，四季轮回中依旧保持着自己最原色的面目，婉约而古雅，参透这层视界，得以延续。这是我漫步在翠微峰顶，沉浸在四百年前的读书声中才能想到的。可见其重彩一面。梁屋深巷内的新安书院，在渐渐消逝的历史中慢慢堆积成了此刻的砖瓦，这时的青砖灰瓦、山墙雀替在寂静中更告诉路人她深刻的历史。',13,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',500,NULL,'2026-08-16 21:12:07'),(48,3,1,15,'梁屋深巷内的新安书院，在渐渐消逝的历史中慢慢堆积成了此刻的砖瓦，这时的青砖灰瓦、山墙雀替在寂静中更告诉路人她深刻的历史。新安书院自清乾隆五十一年（1786）在梁屋巷开建，这是一个浩大的工程，直至十五年后的嘉庆六年（1801）仍在续建，粉墙、黛瓦、马头墙、砖木石雕以及层楼叠院、高脊飞檐、曲径回廊等均在时代的变迁中被缓缓雕琢。而站在深巷古弄，看不出她里子之图文江右书院行易堂古井翠微峰风景新安书院残存旧楼',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',201,NULL,'2026-08-16 21:12:07'),(49,4,1,0,'的丰富。这如一个人，外面看起来不施粉黛毫不起眼，而其内涵却让人惊叹不已。新安是徽属六邑（即今安鳌峰书院徽歙县、休宁、祁门、黑多县、绩溪和江西省的婺源6县）的总称，因六邑均在新安江流域，历史上曾置新安郡而得名。而赣州新安书院的另一个更具实际意书院第一进歇山式厅落义的名字叫安徽会馆。在寸土寸金的梁屋巷内，新安书院兀自占地达一千五百余平方米，整个建筑前后共三进，砖木混合结构，两侧有耳房等附属建筑。第一进院落屋顶为歇山式，与两边的厢房相连，均饰有鎏金木雕雀替，并在屋顶绘有彩画。在二、三进院落之间原有人工池塘，构筑着徽派的梨花伴雨的意向，青石旱桥和两厢的附属建筑上雕刻有神态各异的瑞兽。作为毫不吝啬金钱的徽商，在赣州建设的新安书院与在武汉、襄阳、景德镇等地建设的新安书院一般，建筑的砖块很多都刻有“新安书院”铭文。1945年抗战胜利后，安徽籍旅赣商人利用新安宾馆公积金及房产，在新安书院内设立了新安小学，后被中山路小学合并。之图文现新安书院第一进院落及两边厢江右书院行房保存完好，二、三进已毁，只存有青石柱子及红石柱础，1988年被赣州市人民政府确定为赣州市文物保护单鳌峰书院侧景位。深巷古弄中，被披上了民国建筑',1,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:07'),(50,4,1,1,'青石柱子及红石柱础，1988年被赣州市人民政府确定为赣州市文物保护单鳌峰书院侧景位。深巷古弄中，被披上了民国建筑外衣的新安书院，如一座大门紧闭的润泽百年攀鳌峰老宅院，其内高低错落的马头墙，原本古色古香的徽派建筑在即将凝固的中国教育史，绕不开书院；中国文化史，绕不开书院；甚至，中国政治史，也绕不空气里将人的思绪拉到从前，驻足在开书院。自唐至清书院成为中国社会、政治、教育活动的重要背景，影响深远。在乡村社会，穿越百年时光的老宅，让不懂历史的书院是地方的文化中心，如石城县的鳌峰书院。人也懂得去回味历史的变迁，惊叹光走进今天的高田中心小学，仰头可见遒劲有力的“鳌峰书院”四个大字。据《高田阴如梭，更迫不及待地想去了解这城镇志》记载“清光绪二十六年（1900）庚子，邑廪生温和美等地方绅士，奉县儒学署之市浩繁卷帙中的黑白遗画……命，择址于坝上建鳌峰书院。”石城北部的学生，读了私塾以后，要升学者，必须进入鳌峰书院学习。光绪三十一年（1905），清朝廷宣布废除科举，设立学堂。鳌峰书院自然也随之改革，变学制为三年，分为甲乙丙三班。由丙升乙，由乙升甲，甲班学完毕业。新安书院文保单位石碑\n\n泽躬尔雅”。其事迹为石城教育事业',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:07'),(51,4,1,2,'然也随之改革，变学制为三年，分为甲乙丙三班。由丙升乙，由乙升甲，甲班学完毕业。新安书院文保单位石碑\n\n泽躬尔雅”。其事迹为石城教育事业写下了光辉篇章。于是，从书院，到初等小学堂，到高级小学，再到中心小学，鳌峰书院虽鳌峰书院内漆画一鳌峰书院内漆画二然在不断改名字，却身处百年动荡洪流而安然无恙，依旧诲人不倦，弦歌内景一不辍，历史上先后培养出北宋名相陈恕、南宋探花巫双瑞以及江西高等学堂创始人翰林黄大壎等名人。夏日，穿过层叠交错的小山，沿着弯曲的石板路，踏过青石砌成的古桥，嗅着清新的荷香，再次走进高田，走进鳌峰书院，面前的百年老书院依然青砖铺地、粉墙玄瓦，一派素静。只是走到街上，看那些田间农民，或是街上小贩，提笔便是一手漂亮的毛笔字，开口能吟古典诗词，提嗓能唱客家大戏，才能让人感受到一个地方的文化，居然会浸润如斯。十年树木，百年树人，于是，对千年风尚、百年书院顿生敬意。之图文鳌峰书院牌匾江右书院行教学采用新编国文、算学、地理、历史等，此外还有手工、图画、体育等课。在科举考试渐入尾声的年代，建设一座书院，显然不再是为了应付科举，而着眼的是真正地培养人才。就像曾任鳌峰书院校长的温凤翔的一首诗所说的，“从教',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:07'),(52,4,1,3,'座书院，显然不再是为了应付科举，而着眼的是真正地培养人才。就像曾任鳌峰书院校长的温凤翔的一首诗所说的，“从教从政数年头，莫不委心任去留。捧檄只因思报国，读书原不为封侯。”早在宋宝元己卯年（1039），高田堂下温革“屡试不第，乃捐家资尽市买书，归辟义馆，建楼储之，以供学者，并给廪食”，因建楼动工之日，开挖地基，拾到五铢铜钱，故名“青钱书楼馆”。据《堂下温氏谱》载，温革建起义馆后，“四方学者，接踵而至，诵诗读书，鳌峰书院正门内景二\n\n华林书院宜春书院之图文华林书院牌匾华林书院观浮云因为工作原因，我经常到各地景区景点学习调研，对当地的历史古迹和文化遗存尤有兴趣。每当徜徉在残垣断壁之下、荒烟蔓草之间，内心便特别宁静，像是访得一位敦厚老者，又似偶遇一位远年挚友，那份喜悦与亲切无以言表。一日，在奉新县调研，忽然想起华林书院遗址，很想去寻古探幽一番，当下就请陪同的干部带着我即刻前往。华林书院距县城仅26公里，车子一路疾驰，来到一个山谷，只得下车行走，走了十几米，前方兀立着一个爬满藤蔓的古老牌坊。据介绍，这是唐宋时期的道教胜地“浮云观”之山门——万年宫牌坊。穿过牌坊向右望去，一棵高耸入云的古杉孤零零立在山坡上。',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',505,NULL,'2026-08-16 21:12:07'),(53,4,1,4,'时期的道教胜地“浮云观”之山门——万年宫牌坊。穿过牌坊向右望去，一棵高耸入云的古杉孤零零立在山坡上。据考证，这是当年胡仲尧亲手所植，距今已有一千余年的历史。\n\n古杉左侧，便是华林书以博取“孝悌声华辉北阙，院遗址了。门闾显赫耀南方”。华林书院，古代江二是求仕性的书院。南三大书院之一，与义华林书院的办学目的只有一门陈氏东佳书堂、洪氏个，那就是为胡氏子孙求取雷塘书院并峙江东。胡功名利禄。仅宋代华林胡氏氏先祖胡藩的子孙为了一门就走出进士55名，官“显诗书之门第，振仕至刺史、尚书、宰相者不乏宦之宗风”，以培养胡其人。宋真宗曾赋诗御赞：氏子弟，建成了具有一“一门三刺史，四代五尚书。胡仲尧墓定规模的书院。宋代国他族未闻有，朕今止见胡。”八百洞天石刻子监主簿、教育家胡仲三是开创了收容女生之尧将华林书院发展成了一所规模宏伟、震惊文坛、名噪全国的学府，比庐山白鹿洞书院先河。在我国历史上许多著早扬名100多年。据《天下一统志》记载，“名公巨卿，胜友如云，远客千里而来，主名的书院中，至今还没有听人倒屐相迎”，出现了“纷纷游客豫章回，俱道华林就学来”的兴盛景象。说过有收容女生的，可华林华林书院的办学有三大特色：书院在此方面却谱写了新的',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',512,NULL,'2026-08-16 21:12:07'),(54,4,1,5,'人倒屐相迎”，出现了“纷纷游客豫章回，俱道华林就学来”的兴盛景象。说过有收容女生的，可华林华林书院的办学有三大特色：书院在此方面却谱写了新的一是家族化的书院。他们的办学宗旨，就是为了把累世聚居、数代传经的家风传下去，一页。宰相向敏中曾有“花凝玉勒含烟露，酒泛金樽醉之图文绮罗”的诗句以纪实。江右书院行立于书院遗址前，但见青山环抱下的这一方空地，华林书院遗址一已是芳草萋萋荒凉地，由大条石铺就的建筑基石仍镶嵌在荒草之中。遥想当年的书院：正厅前茶厅，茶厅前小厅，小厅前书院，书院前凉亭水阁，凉亭水阁前客厅，客厅前竖门，竖门前鼓门，鼓门前三重之元门，元门前石梁，石梁前勾曲门，勾曲门前槽门。每有宾客至，以鼓而报内堂，方出迎宾也。华林书院遗址二是何其宏阔精致的园林式建筑群呀！而如今，青山依旧，书院不再，主宾不再，琅琅书声亦不再矣……万年宫牌坊\n\n四周围墙，书院比幼时所见更加开阔明亮，又因为自己长高了，反见着它更显矮小。昌黎书院仿佛是见着一位失散多年的亲人，环顾书昌黎书院亦重访院，倍感亲切，又实感陌生。离开时，我再次昌黎书院，位于现宜春四中校园内。现在保留的一栋院舍是清嘉庆十五年（1810）回眸，古老的书院又恢八月修建的。',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:07'),(55,4,1,6,'昌黎书院，位于现宜春四中校园内。现在保留的一栋院舍是清嘉庆十五年（1810）回眸，古老的书院又恢八月修建的。复了它的寥落寂静，正曾几何时，家住在当年破旧的昌黎书院内。重访书院，所见已不是幼时的四合院了。如今日之书院文化，已拾阶而上，一排由三栋平房相连的灰瓦白房豁然出现眼前，中间的主楼略微缩进去些，不复当年的鼎盛繁荣。与左右两排的平房形成品字形，主楼前面种着一些花草，整个书院前是窄窄的水泥坪，但我相信，真理是永恒种着一排柏树和一些绣球花，我们去时，绣球花正开得如火如荼。整体来看，因为拆了的，是历久弥新的，就之图文江右书院行像太阳，虽然古老，却每日常新，古圣先贤的教育，也如和煦的阳光，普照寰宇，带给人类幸福和美满。昌黎书院院舍重建于袁山公园内的昌黎阁\n\n讲的学生有近千人。一年后，朱熹又为龙光书院作《心广堂记》和龙龙光书院光书院诗，并在记中提出了自己的治学思想。自此，龙光书院成为程朱理学中一座重要的里程碑。进入元代，学士欧阳圭斋（欧剑匣亭、剑池阳玄）“为重书龙光书院、文明堂额匾及作序，一时书院之名扬天下”。书院中漫步，时光也变得格外的幽静，也难怪当初朱熹讲学月余，便赋《龙光书院》',5,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',494,NULL,'2026-08-16 21:12:07'),(56,4,1,7,'光书院、文明堂额匾及作序，一时书院之名扬天下”。书院中漫步，时光也变得格外的幽静，也难怪当初朱熹讲学月余，便赋《龙光书院》诗赞云：“一道荣光带碧山，天风吹雨度云关；树浮空翠名村坞，泉落飞虹泻石湾；赤之图文龙光书院大门江右书院行“龙光”射斗牛之墟去龙光书院走走，已是一年前的想法，却由于各种琐事而一直被搁置。然而，我终于还是去了。这座安静地深居在丰城西南部荣塘境内的书院，乃是宋高宗赵构赐名的一所著名书院。自创办至民国元年毁书院改学堂，民国立学校，时达八百余年的办学历史，在丰城教育史上具有极为重要的地位。北宋大观元年（1107），有名为陈瑞者迁居荣湖，首办第一件事是立荣塘义学。明陈廷章《龙光书院事实》曰：“吾祖荣湖应龙公于宋大观丁亥，立书院于古丰县治之上榜……有志以立义学，以诲乡邑及四方之来学者。捐剑池庙、山寺桥陂上田五百亩以给之，远近无不感动。”乾道三年（1167），书院迎来了大理学家朱熹。朱熹应邀在龙光书院讲学，前来听圣殿\n\n岭豹栖朝气隐，剑潭龙起夜光寒；咿唔何处经年韵，多在湖东乔木间。”在书院的左边，有一剑池。王勃在《滕王阁序》写到的“物华天宝，龙光射斗牛之墟”指的就是这个剑池，',6,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',497,NULL,'2026-08-16 21:12:07'),(57,4,1,8,'岭豹栖朝气隐，剑潭龙起夜光寒；咿唔何处经年韵，多在湖东乔木间。”在书院的左边，有一剑池。王勃在《滕王阁序》写到的“物华天宝，龙光射斗牛之墟”指的就是这个剑池，它乃是春秋时干将、莫邪所铸名剑“龙渊、太阿”宝剑的出土地。翻开中国整部浩浩荡荡的书院史，丰城也有着浓墨重彩的章节。据不完全统计，从宋代至清末，丰城先后创建了近五十所或大或小的书院，如莲溪书院、龙光书院等，在江西乃至全国书院史上都可谓是影响巨大，厥功甚伟。绍兴二年（1132）四月，“有司奏闻，承敕额龙光书院。”宋高宗亲赐“龙光书院”匾额，这对龙光书院来说是莫大的荣耀。龙光书院的建筑也是别具风格。整个布局具有四合院式的特点，院落坐北向南，分前后两进，首为大门，中为大殿，后为六经楼；院内东西两翼，前有左右庑，中两侧为讲堂、客馆、花台、读书室、会膳堂等；院外附属建筑有山寺、望光亭、剑光祠、晚晴斋等。而院中古木参天，松柏积翠，更是给淡雅的书院增添了几分秀色。可以说，书院八百多年的文化、历史和精神都凝聚其中。拂去八百年的苍茫岁月，踱步于书院，我只能凭着自己的一颗心去寻找、去触摸。或许，当历史的风烟将这些珍贵的记忆尘封起来时，我们会发现，那书院深处有一弯源',7,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',506,NULL,'2026-08-16 21:12:07'),(58,4,1,9,'拂去八百年的苍茫岁月，踱步于书院，我只能凭着自己的一颗心去寻找、去触摸。或许，当历史的风烟将这些珍贵的记忆尘封起来时，我们会发现，那书院深处有一弯源头活水，正滋润着我们日渐干裂的心田。水，们渐干书院内景龙光书院重修碑记之图文江右书院行书院六经楼全景\n\n长生成仙。南宋著名理学家、思想家朱熹曾两次到这里讲学，因朱熹别号紫阳，故时人又称其为“紫紫阳书院阳书院”。这里还有这样一个传奇故事：淳熙五年（1178），经宰相史浩推荐，朱熹出任南康（今江西星子县）知军，此后他先后洗墨池两次到樟树阁皂山讲学，有一次讲学时学生张洽见其脚步沉重，气喘吁吁，全身酸痛，劳累不堪，甚是心疼。晚上就寝前，张洽特地捧出阁皂山崇真宫一阳道人酿造养生酒给恩师饮用，并神秘地告诉他：“今晚喝了此酒，明日恩之图文师必定神清气爽、疲惫顿江右书院行紫阳书院大门紫阳书院再度寻紫阳书院位于樟树市阁皂山山麓。在大万寿崇真宫往东北方向一百米处，有一砖混结构的宫院，便是紫阳书院，又名道德宫，占地约860平方米。宫院原是按灵宝道派“三教合一”道义供奉孔子、释迦牟尼、李耳的观宇，真的是儒、释、道集于一宫。最近我',7,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',482,NULL,'2026-08-16 21:12:07'),(59,4,1,10,'结构的宫院，便是紫阳书院，又名道德宫，占地约860平方米。宫院原是按灵宝道派“三教合一”道义供奉孔子、释迦牟尼、李耳的观宇，真的是儒、释、道集于一宫。最近我一直在研究儒、释、道，并写了一篇长达4万多字的文章《解读儒释道经典，浅谈品位人生》，文中我就为这三者如何做到“三源合流，九派归一”而纠结，没想到在这里找到了答案。在紫阳书院，三者有机地结合，又名“道德宫”也。道德宫是名人论道讲学、唱和燕憩的场所。灵宝派是道教教派，始创于东晋末年，其基本信仰是强调劝善度人，鸣水桥边噀石亭\n\n留有朱熹对联：“水流激石如飞雪；树影连山欲化云。”宫院明代毁于山火，清雍正庚戌岁（1730），本地太学生黄衍出资改建为砖混结构。现庭院门额上“紫阳书院”四个苍劲的枯笔字，是朱熹手写的拓刻。宫院有楼阁十一楹，藏北宋熙宁赐龙图天宝文御书一百二十卷。进门左边的这棵银杏树，是当年朱熹为创杏坛气氛而亲手种植的，距今已有八百多年了。庭院内古木参天，枝繁叶茂，浓荫蔽日。元初的四棵金桂、银桂、四季桂自西向东排植于中间，还有罗汉树、紫玉兰、紫荆等观赏和药用珍贵草木，多逾百年之物。四季和风习习，常年飘香十里，所以明代又有“桂苑宫”之称，并存碑刻于庭院内。',8,'null','{\"page_end\": 9, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:07'),(60,4,1,11,'紫荆等观赏和药用珍贵草木，多逾百年之物。四季和风习习，常年飘香十里，所以明代又有“桂苑宫”之称，并存碑刻于庭院内。据说紫阳书院的那副对联也是朱熹品笔所书，“杏坛绛帐堪可继；鹿洞鹅湖当并传”。由于紫阳书院坐落在阁皂山中，且阁皂山为道教名山，在历史长河中有许多的书院原本就与儒释道融为一体，紫阳书院与华林书院一样，与道教结缘，特别是紫阳书院，桂苑宫牌匾又名道德宫，且同为匾额，分列于门首之上，这在书院史上是极为罕见的。离开紫阳书院，当踏过鸣水桥，我在想，一个人无论多么的伟大，他的生命都和常人一样不会永生，但他所种植的文化之树、思想之树却植根于大地，扎根于人心。站在紫阳书院门前，仰望“道德宫”，深悟“道德文章”才是永留人世的经典。之图文江右书院行书院内景消。”次日清晨，朱熹起床后发觉自己果真两脚轻盈，精神倍增，全身体力充沛，甚是兴奋。当得知该酒乃阁皂山一阳道人用当地地道药材和民间酿造的白酒泡制，还未起名时，朱熹良思片刻后，挥笔题书“劲力奇”三字赠与一阳道人。次日讲学完毕乘兴写下了七律《题崇真宫》一首，诗曰：蹬道千寻风满林，洞门无锁下秋阴。紫台凤去天阙远，丹井龙归地轴深。野老寻真浑有意，道人谢客亦何心。',9,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',503,NULL,'2026-08-16 21:12:07'),(61,4,1,12,'次日讲学完毕乘兴写下了七律《题崇真宫》一首，诗曰：蹬道千寻风满林，洞门无锁下秋阴。紫台凤去天阙远，丹井龙归地轴深。野老寻真浑有意，道人谢客亦何心。一樽底处酬佳节，俯仰山林慨古今。“劲力奇”酒由此得名，并逐渐声名远播。另外阁皂山鸣水桥处也山门\n\n派凄凉之境，当年清雅幽静、鸟语花香之景无迹可寻，与我的想象相差甚远，本想凭吊一番的心情荡然无存。房子右侧有一棵大树，相传是袁鲁训当年六柳书院所种，总共六棵，现在就剩这一棵。袁鲁训十分仰慕陶渊明，在创建书院时，效仿陶渊明自六柳书院柳诉情称“五柳先生”，也在书院前种下六棵柳树，并自称“六柳居士”，书院因此得名。据史料去寻访六柳书院时已是黄昏。一场暴雨过后，乡间空气异常清新，一道完美的彩虹记载：当年此院坐北面南，院外柳絮飞扬，石飞架一望无垠的绿野之上。仿佛，老天也来为寻访助阵。径倾斜，漫步有声。院内花园溢香，景色宜人。六柳书院位于宜春市袁州区寨下镇横塘村。横塘村，自古重视教育。从建村至清末院阁建筑古朴幽雅，落落大方。有“文山幽谷静，数百年间，先后办起了曲池书院、六柳书院、定安书院等13所书院，占袁州区总数27莺歌错啼哀”之称。所的一半。其中最负盛名，且保存至今的为六柳书院。',9,'null','{\"page_end\": 10, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:07'),(62,4,1,13,'数百年间，先后办起了曲池书院、六柳书院、定安书院等13所书院，占袁州区总数27莺歌错啼哀”之称。所的一半。其中最负盛名，且保存至今的为六柳书院。袁鲁训所植古柳1481年袁京后人袁鲁训创办六柳书堂，供家族子弟读书。“横塘历来多名士”。横塘袁姓过去曾成为“江右名宗”，寨下镇也被称作“文化之乡”。按族谱记载，横塘一共出了14个进士，13名举人。像文天祥式的抗清英雄——袁继咸，清大理卿正、资政大夫袁芳松等都是横塘人，都曾就读于六柳书院。从书院走出来的学子，最负盛名的是袁鲁训的曾孙袁继咸，他曾与文山（文天祥）、叠山（谢枋得）并称为“江右三山”。书院在横塘村横塘小学旁边的一小巷内，书院的整体保存尚完整，但厅堂和里屋却江右书院行破败不堪，堆积着各种废弃物，到处覆盖着厚厚的灰尘，仿佛一位行将就木的老人，一书院房舍\n\n凤仪书院凤仪书院探古今初秋的宜春幼儿师范高等专科学校（即原高安师范），舒适干爽，沿石阶而上，在绿树掩映中有一个贴有红色瓷砖的沿门，显得异常醒目：红墙绿瓦的洞门顶上，横嵌着一块石刻碑牌：“凤仪书院”，四个涂漆红字遒劲有力。岁月流逝，沧海桑田，关于凤仪书院，我试图探寻除了这块石碑之外的历史留存。',10,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',501,NULL,'2026-08-16 21:12:07'),(63,4,1,14,'一块石刻碑牌：“凤仪书院”，四个涂漆红字遒劲有力。岁月流逝，沧海桑田，关于凤仪书院，我试图探寻除了这块石碑之外的历史留存。据同治《高安县志》载：凤仪书院位于“府署后，凤山侧”，即现在的高安市政府后的碧落山东侧，解放初期的高安师范校址。凤仪书院创建于清乾隆二十四年（1759）。清朝著名理学家戴震所撰《凤仪书院碑记》载：“瑞州旧有筠阳书院，在南城，奉宋之周子、二程子、张子及朱子、陆子，而明王文成亦与焉，号七贤。今太守杨公守兹郡阅二载，百废使眼色举，闵其即于坠驰且地隘，乃徒建北城高广地。地故为祀刘文成公址，祠废碑犹存，太守因以列七贤中而八，又筑后楹，奉眉山二苏氏如旧制。苏、刘盖尝官是间，留名贤迹也，于是更以新名曰‘凤江右书院行仪书院’，昭昔之日鸣凤之瑞，引为今多士幸际。”凤仪书院是因苏辙、苏轼、刘文成（刘伯温）等名士得名，象征凤鸣朝阳之祥瑞而引百鸟朝凤之喜庆。凤仪书院为瑞州太守杨仲兴倡导所建，养学资金来自高安、上高、新昌（宜丰）等三县府衙置办的田亩、竹山，其性质当属官办书院。书院以程朱理学为研学根本，以筠阳书院旧制为办学模式 。宋元丰间（1078—1085），苏子由谪筠，兄',11,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',491,NULL,'2026-08-16 21:12:07'),(64,4,1,15,'书院以程朱理学为研学根本，以筠阳书院旧制为办学模式 。宋元丰间（1078—1085），苏子由谪筠，兄子瞻便道视之，寓焉，先夕无约而梦同，因匾其堂曰：“同梦”。故书院生员住房有“同梦堂”之说。沿袭筠阳书院旧制，凤仪书院也设文化堂、会讲堂、同梦堂、诗经堂、书经堂、周易堂、春秋堂、礼记堂，另外还有仪门、正门、书楼、厨房、茶厅等书院建筑。凤仪书院建立后曾多次修整或重建。清道光年间（1821—1851），知府朱锦琮重修。咸丰年间（1851—1862），太平军攻入瑞州府治，书院被毁。同治九年 （1870）九月知府黄廷金率属捐资重修，并书“凤仪书院”石匾额于院门。同治十二年（1873），江西巡抚刘坤一颁发存院书籍共计3274卷。光绪二十七年（1901）八月，清廷颁布兴学诏书，要求书院都改为学堂，除京师已设大学堂切实整顿外，指示各省所有书院在省城的都改设大学堂，各府、厅、直属州的都改设为中学堂。凤仪书院为瑞州府属书院，所以改为瑞州府合府公共学堂。宣统元年（1909），瑞州府合府公共学堂改称瑞州中学堂，\n\n附设师范科。后日寇侵略中国，凤仪书院为日寇所毁，现仅有毁而不烂的清同治黄廷金所书“凤仪书院”石匾传世。',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',502,NULL,'2026-08-16 21:12:07'),(65,4,1,16,'附设师范科。后日寇侵略中国，凤仪书院为日寇所毁，现仅有毁而不烂的清同治黄廷金所书“凤仪书院”石匾传世。1996年高安师范校庆90周年，石匾东移额于洞门，并撰联：“凤丹羽秀书濡诗染；仪正行端院萃府菁”。史料记载，由于凤仪书院请名家讲学，一时名声大振，学子云集，培养了一大批人才。明月轩书院凤仪书院在高安教育史上有承前启后的重要地位。早在唐朝元和末年（841-819），国子监祭酒——高安人幸南容致仕归故里后，再调露乡洪城（今上游水库内）创办了桂明月轩书院著风岩书院。据考，该书院为唐代江西五所书院之一，也是全国最好的书院之一，开高安兴学办校之先锋，培育了不少名士。从唐到清，桂岩书院培育出进士22名，举人2名，早就听说高安的贾家古村有一处明月轩书院，那一日，风和日丽，艳阳高照，伴着贡生8名。好天气和好心情，我与几个朋友踏上了寻访明月轩书院之路。高安教育素享盛誉，改革开放以来，更是得时遇势，蓬勃发展。高安市委市政府在畬山贾村，位于高安锦江以南，始建于五代十国后晋开运三年（946），是一处保实施“教育兴市”战略中，坚持三抓：一是开源节流抓投入；二是排忧解难抓稳定；三存完好的历宋、元、明、清各朝的典型江南古村建筑群。',12,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',508,NULL,'2026-08-16 21:12:07'),(66,4,1,17,'实施“教育兴市”战略中，坚持三抓：一是开源节流抓投入；二是排忧解难抓稳定；三存完好的历宋、元、明、清各朝的典型江南古村建筑群。现在居住在这里的村民大都姓贾。是固本强基抓质量。从1977年恢复高考制度以来，被大中专录取的人才名列全省各县（市）从贾氏的族谱中，我们得知，最早居住于此的人多为畬族，因而这里被叫做畬山。在贾村，之首，被誉为“教育大市”“才子之乡”。有明月轩书院等大小书院6所，基本被毁，唯一保留下来的就是“明月轩书院”了。戴震在《凤仪书院碑记》曾写道“……相语以道德，相勖以躬行”，道出了学以致天气十分炎热，骄阳似火，我们一行随着导游穿行于宽窄不一的巷道里，拐过一个用的观点，他同时又说：“六经之文，邃深而博大，学焉者，各有所至，或履之为德行，丁字巷，蓦然见一块简易的匾牌，一看就是现代人做的，上书“明月轩书院”，下面还或抒之为文章，或措之成丰功伟绩，如八贤、如二苏之卓卓著乎！”附有小楷文字：“明月轩书院清代中期建筑，文革中毁损严重，但有两个标记清晰可见，至此，笔者颇受启发：一如戴先生文章所说，青年学子学“六经”，以苏轼、苏辙、其一是‘双喜’木雕图案，独具匠心，双喜图案还带有蝴蝶坠子，似行云流水，十分飘逸，',12,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:07'),(67,4,1,18,'至此，笔者颇受启发：一如戴先生文章所说，青年学子学“六经”，以苏轼、苏辙、其一是‘双喜’木雕图案，独具匠心，双喜图案还带有蝴蝶坠子，似行云流水，十分飘逸，刘伯温等历史名人为榜样，抑或独善其身，抑或兼济天下……这也许就是高安为“才子之图文之乡”的秘诀所在，也许就是凤仪书院的文脉传承……江右书院行\n\n明月轩书院古村一角古村光影极像如今的博士帽，寓意古书院学子个个金榜题名。其二是书院天井出水口，竟然是个倒刻的石桃，寄寓书院桃李满天下，据说，官至宰相的傅作秋正是书院的骄子。”我驻足在明月轩书院门口良久，匾牌上的每一个字我都细细地咀嚼，这么一个古村，能有这么厚重的文化底蕴，实在是令人拍案叫绝。但是古老的书院经受不住历史和时光之图文江右书院行的侵蚀，门梁破败，十分凋敝。我知道，能遗存下来已实属不易，要放在别的村子，也许早就拆去了，也许早就成残垣断壁了。它的存在还要感谢一个人，这个人就是已故的村支部书记贾克久。他对古村的保护付出了一腔热血，他把古村当作了他的生命，他也确实为古村而付出了生命。我们从明月书院走出来，心情从沉重中有所释然，导游介绍说，贾家村文风鼎盛，明、清两代500年间，贾村出了8个举人，10个进士，',12,'null','{\"page_end\": 13, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:07'),(68,4,1,19,'我们从明月书院走出来，心情从沉重中有所释然，导游介绍说，贾家村文风鼎盛，明、清两代500年间，贾村出了8个举人，10个进士，各类官员达35人。贾村人也有习武之风，曾出过几个武举人。崇顺堂的主人贾荣连就是一个武举人。历史过去，繁华已尽，但畲山贾村依然矗立，今时的人们对它更为重视、赏识，更能领略到它往日的光辉和今日的价值。厚德堂贾氏宗祠内牌匾\n\n舍——培根学堂。一幢创建于1919年的西式洋楼——培根职业学校，该校由墨庄刘氏中最早接受“五四”新思想的刘化成所创办，是专门培养农业人才的职业院校。在全省也是独此一天宝古书院家。最近，我查阅了熊步成老先生写的《简介古书院与新学堂宜丰书院》，天宝唯“柏友山居”（书院），文曰“西安府周知吴之才建，以谋其子侄，其子吴泰来、吴甘来等先后成进士，多捐官俸以提起宜丰县的天宝古村，我的心结就难以打开，孩提时穿行在古村的祠堂巷道、渠资馆舍，礼聘名师，远近愿学者归之”。据当边井旁，觉得古村就像一位慈祥的老人；长大后远离了这个古村，曾写过一首诗，大意地人讲，在天宝古村先后有几所书院，几兴几废，是穿过了这道古老的门，即是离开了家同时离别了乡，觉得古村就像一位沧桑的老人。',13,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',500,NULL,'2026-08-16 21:12:07'),(69,4,1,20,'地人讲，在天宝古村先后有几所书院，几兴几废，是穿过了这道古老的门，即是离开了家同时离别了乡，觉得古村就像一位沧桑的老人。亦不能确切地认定为哪些年月和哪些宅院。天宝古村现有民宅230余幢，明清古建筑141幢，其余为解放初期仿古民居，房屋无论如何来叙述天宝的古书院都不为过，坐北向南，分排林立，规划完整合理。著名的建筑有刘氏宗祠、昭公祠、进士第等。此外，新学堂门廓而眼前“培根学堂”让我产生了无限的遐想。还有莅堂翁祠、五芳翁祠、秀圃翁祠、杞翁祠、朴庵公祠、二阳公祠、论斋翁祠、如三翁祠、这是一幢典型的西方建筑，古书院和新学堂在这里显得协调和包容。我国的书院文化始益新公祠等建筑，还有48条巷和48口井。于唐，兴于宋，止于清。从1895年“公车上书”到1898年“戊戌变法”，旧书院与新天宝古村除有千年古书院之外，在小巷远方，在古宅深处竟落座了一栋西洋的校学堂亦不变亦变，“立沛纶音，停罢科举”。站在天宝古村的古书院和新学堂前，禁不住思绪万千，这里是中国书院兴废的见证，之图文似乎跨越了千年的历史，似乎走过了千年的文化，我不知该为古书院的衰落感到悲哀呢，江右书院行还是要为新学堂的开创感到欣慰？新学堂全貌远观新学堂',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:07'),(70,5,1,0,'奎光书院奎光书院客家风铜鼓，一个位于赣西北边陲的山区小县，一个拥有“中国长寿之乡”“国家级生态县”等众多绿色奖牌的美丽山城。在铜鼓工作四年多的时间里，吸引我感染我的，不仅是这里清新的空气和田园般的山水，更是这里独特而厚重的客家文化和红色文化，而铜鼓奎光书院就是这么一个在青山绿水之间展现着铜鼓客家文化和红色文化的缩影。从县城铜鼓大桥南端步行，穿过马路，上一段缓坡，你就能看见奎光书院像一位安详的老者静静端坐于此。书院依山而建，上下两栋，土木结构，每栋间均有天井相连，书院旧围墙是典型的客家建筑。据史料记载，清道光十七年（1837），由铜鼓客家人周玉衡、卢瑞英等发起，数十姓客家人捐资助学，创办了奎光书院，现存部分仅为当年的三分之一。之图文江右书院行走廓书院内景客家人是崇文的。他们特别看重读书人，有“茅寮出状元”之谚。为了子弟成龙，光耀门楣，客家人往往集中全家族、全宗族的力量来培养子弟读书。奎光书院果然不负众望，自创建以后至清光绪三十二年（1906）废科举制度的百余年间，虽历经沧桑，但奎光书院全景\n\n在铜鼓早期教育史上却写下了厚重的一笔。书院人文蔚起，学子科甲连登。进士10名、举人59名，秀才、监生更是无法统计。',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',509,NULL,'2026-08-16 21:12:08'),(71,5,1,1,'在铜鼓早期教育史上却写下了厚重的一笔。书院人文蔚起，学子科甲连登。进士10名、举人59名，秀才、监生更是无法统计。大革命时期，赣西北第一个中共支部的5名成员，就有4人是奎光书院的毕业生。中央苏区河西道委书记兼独立师政委陈葆元，中共铜鼓县首任县委书记陈逸群，铜鼓农民运动领袖李建康，北伐功臣赖益躬（北伐烈士）均出正谊书院自奎光书院。如今走进书院，只见整个房子内外墙都写满了“共产党十大政纲”“ 土地政纲”“红军万岁”“打倒土豪劣绅”等文告标语，有些清晰有些模糊，这些都无不印正谊书院株潭吟证了书院那段峥嵘岁月。历史走到今天，当我们游走于奎光书院古色古香的门洞之间时，仿佛穿梭了两个世一听说“赣西”之名，我内心总是弥漫着温暖和自豪。因为我老家河对岸的小村，纪，会情不自禁思考书院文化留给当下我们的是什么？正如奎光书院的校歌所唱的那样：便俗称赣西，村旁矗立着一所有140多年历史的正谊书院（现为株潭初级中学），俗称“良好校风要发扬，学知识，学本领，品德更优良。” 奎光书院的历史变迁，也深刻反为赣西学堂。映了铜鼓客家人在长期迁徙和发展中凝炼出了“吃苦耐劳、开拓进取、崇先报本、和衷',2,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',487,NULL,'2026-08-16 21:12:08'),(72,5,1,2,'” 奎光书院的历史变迁，也深刻反为赣西学堂。映了铜鼓客家人在长期迁徙和发展中凝炼出了“吃苦耐劳、开拓进取、崇先报本、和衷在光绪元年（1875），株潭客籍举人谢大舒、曹瑞祥“以兴起斯文为己任”而竭共济、敢作敢为、爱国爱乡”的客家精神。我想这正是当下继承和弘扬书院文化的根本，力倡建正谊书院。宣统三年（1911），杨守洛、谢济沂等人将正谊书院改为高小。民国也是树立社会主义核心价值观的有益促进。我相信，奎光书院一定可以在传承中焕发新三十三年（1944），正谊小学改为江西私立赣西初级中学。解放后，学校扩建，改名为的光彩。株潭公社第二中学。1973年更名为株潭初级中学。校名多次更迭，但古院门额上那块“正沩山之麓，定江之旁，美哉书院，锦绣风光。站在书院门前，铜鼓县城尽收眼底。谊书院”匾额从未摘下。定江水在奎光书院的眼皮底下向东流去，不舍昼夜。每次拜谒，奎光书院都能带给我无如今，我每次走进正谊书院，总感觉她正穿过岁月的幔帐，以其母性的温柔、神圣尽的遐思……的慈爱与博大的胸怀，向我们款款走来。我拂去岁月厚厚的尘埃，嗅到了门楼、廊房等之图文古迹散发出的浓浓书香。江右书院行书院主楼走廊文昌宫残碑书院旧楼印象\n\n桂林书院桂林书院槛外行',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',513,NULL,'2026-08-16 21:12:08'),(73,5,1,3,'我拂去岁月厚厚的尘埃，嗅到了门楼、廊房等之图文古迹散发出的浓浓书香。江右书院行书院主楼走廊文昌宫残碑书院旧楼印象\n\n桂林书院桂林书院槛外行桂林书院始建于明正统元年（1486），是学者夏子哲创建的一所家族书院，位于江西省丰城市同田乡镇坊村东镇坊（中）小学文昌阁内，1996年被列为丰城市重点文物保荷花池护单位。桂林书院原名桂林书楼。据状元邢宽所撰《镇坊桂林书楼记》，夏子哲号复轩，洪武年间举人出身，曾出任枞阳、溧水等地巡检司的巡检。为了使子孙读书上进，他便建设了这座桂林书楼。书楼建于风景优美的莲池之上，前峙虎岭，后倚象山，桂花飘香十里，书声日夜相闻。从明代到清代，书院规模不断扩大，成为当地方圆几十里著名的学府。清道光年间，夏学谦对桂林书院进行了改扩建，有讲堂、文昌阁、膳厅、斋舍等，有学田200余亩，以供师生膏火薪俸。明末大学士姜曰广，革命烈士夏日晖，近现代文学家、之图文江右书院行正谊书院石刻桂林书院大门正谊书院序\n\n革命老人、《辞海》主编夏征农，都是桂林书院培养的高才生。2002年桂林书院重修，卸任上海市委书记的夏征农亲自写信给省委书记孟建柱，请求省委予以支持。在夏老和孟书记的关怀下，江西省慈善总会为桂林书院拨维修专款',2,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:08'),(74,5,1,4,'2002年桂林书院重修，卸任上海市委书记的夏征农亲自写信给省委书记孟建柱，请求省委予以支持。在夏老和孟书记的关怀下，江西省慈善总会为桂林书院拨维修专款10万元，使书院顺利重修。夏老欣然命笔为桂林书院题词：“历代讲学园地，而今修建一新，为国树人有望，值得铭记在心”。现在，桂林书院主楼文昌阁，为重檐歇山顶，共两层，上层为阁楼，下层是正堂，全木质构成。外披檐回廊，前廊和左、右廊有16根石柱，文昌阁建筑面积374.2平方米。院外竖坊式门楼，大门上横刻阳文“桂林书院”，两侧直行楷书对联：“桂蕊飘香，书声吟破山中月；林峦耸翠，诗思敲残槛外花。”四周绕以围墙，总建筑面积1300多平方米。院内外遍种丹桂，飘香秋日。大门两侧有千年古樟数棵，尤为壮观，更是烘托了书院庄严肃穆的环境。吉安书院江右书院行书院侧景主楼\n\n阳明书院阳明书院净居人夏日一天，吉安市青原山古木葱郁，鸟语花香，天空晴好，一碧如洗。笔者陪同一批慕名而来的客人参观风景秀美的阳明书院。来到阳明书院门口，一座古色古香、庄严肃穆的崭新大院赫然在目。明朝正德五年（1510），时任庐陵知县的王守仁偕同邹守益在青原山开讲“良知之学”。此后，王阳明每年春、秋两季在青原山讲座。',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:08'),(75,5,1,5,'明朝正德五年（1510），时任庐陵知县的王守仁偕同邹守益在青原山开讲“良知之学”。此后，王阳明每年春、秋两季在青原山讲座。王阳明去世后，每年春秋两季，青原山都要举办大型王学讲会。庐陵因此被誉为“理庭院学之邦”，阳明书院因此被誉为“东南邹鲁，西江杏坛”。明万历年间，门下弟子邹元上依次为传心堂、五贤祠、魁星阁，前后三进；北院为核室。标等人倡议，建会馆于翠屏山之阳。清道光十九年，会馆年久失修，吉安知府鹿春如倡走过门斗、传心堂，来到五贤祠。“五贤”分别指王守仁、邹守益、聂豹、欧阳德、导建立阳明书院于如今之地。光绪年间废除科举，书院停罢。1994年，阳明书院被列为罗洪先。邹守益，安福人，明代科举探花。罗洪先，明朝嘉靖年间殿试状元。他们都是市级重点文物保护单位。2012年10月，阳明书院复建工程启动。2014年3月正式对之图文庐陵的达官名士，对推动和传播王学思想和庐陵文化功不可没！外开放。当地政府遵循修旧如旧、建新如旧的原则，采用砖木建筑结构，按照当年景象江右书院行走到大天井，周围两层木质教学楼房，八间教室均为展览室，一幅幅照片，一段段进行全面修复。书院坐东北朝西南，分南北两院。南院为教工楼、号房、庖湢；中轴线大门全景',5,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:08'),(76,5,1,6,'走到大天井，周围两层木质教学楼房，八间教室均为展览室，一幅幅照片，一段段进行全面修复。书院坐东北朝西南，分南北两院。南院为教工楼、号房、庖湢；中轴线大门全景\n\n传心堂内“蜚声庠序”牌匾五贤祠与传心堂传心堂内“学可师王”牌匾文字，记载着一串串坎坷、曲折而又闪光的岁月：“阳明书院”“青原讲会”“德化乡里”“发展阶段”“宗族谱牒”“祭祀祖先”……王阳明良知学体系内容丰富，特别是之图文江右书院行他的亲民思想影响深远。它有三层内涵：一是爱民保民。他说：“君子贤其贤而亲其亲”“如保赤子”。二是顺应民心。“民之所好好之，民之所恶恶之，此之谓民之父母”。三是安民富民。“修己便是‘明明德’，安百姓便是‘亲民’。”这对于今天的道德教育有重要的启示意义。五贤雕像先生居室、号舍、庖室\n\n照壁江右书院行讲堂群峰叠嶂环抱的青原山阳明书院中，颜真卿、苏轼、杨万里、李纲、黄庭坚、解缙、徐霞客……一串串名字如散落的璀璨宝石；学子、古柏、古井、“墨迹四宝”、传心堂、五贤祠……一处处遗迹蕴涵着岁月的沧桑与厚重。穿越五百多年的时光，他们无一不在诉说传奇，每一个传奇都散发似曾相识的温暖，那温暖就像一片青草地、一群阳光下翩',5,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',497,NULL,'2026-08-16 21:12:08'),(77,5,1,7,'穿越五百多年的时光，他们无一不在诉说传奇，每一个传奇都散发似曾相识的温暖，那温暖就像一片青草地、一群阳光下翩翩起舞的蝴蝶、一穹蓝得醉人的天空，一些生命里渐行渐远的东西慢慢回归……\n\n龙江书院龙江书院蕴乡情怀揣着青色的怀念与纯蓝的憧憬，我来到一座宁静的书院——龙江书院。光阴凝滞，往事潜沉。各种情愫在内心滋生、翻涌，推动我的脚步，在书院徘徊又徘徊。龙江书院坐落于井冈山市龙市镇的五虎岭南麓、龙江河畔。清道光二十年（1840）春，由当时的永宁县知事杨晓倡导，联合湖南酃县、茶陵县的客家乡绅集资捐款修建。书院坐西南朝东北，宽38.2米，纵深53.4米，占地面积2000平方米，由前后三进，左中右三组，以中轴线对称布局构成的建筑群组成。共有7个厅堂、42间房子、11个天井。前厅为考课坐处，中厅称 “明道堂”，后厅谓“文星阁”。三厅依次以天井相连。天井书院牌匾左右两侧均有回廊与厢房相通，分设启秀斋、珍席斋、锦心斋、漱芳斋、梯云斋、步月斋和报功祠、崇文祠等，名字响亮，文气十足。请外面的名师来书院讲学）、“走出去”（派学子赴白鹭洲书院、豫章书院等地参观学习）龙江书院创建后，制定了一整套严格的管理制度，共分二十条，对掌教山长、坐局',7,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:08'),(78,5,1,8,'请外面的名师来书院讲学）、“走出去”（派学子赴白鹭洲书院、豫章书院等地参观学习）龙江书院创建后，制定了一整套严格的管理制度，共分二十条，对掌教山长、坐局的办法，故龙江书院成绩斐然。近70年间，共培养进士与举人50余人，成为孕育湘赣之图文绅士、起闭馆时间、官课、师课、生员录取比例及条件、生员伙食补助标准、田租管理、边界山区栋梁之才的摇篮。江右书院行书院事务、县宪官绅莅院考课等均有详规。因管理得法，治学严谨，并采用“引进来”（邀最震撼的是对书院那段红色历程的景仰之情！书院全景\n\n文星阁朱德房内陈设之图文明道堂内景明道堂\n\n燕山书院燕山书院古画廊在江西省遂川县堆子前镇，有一座全国罕见的清代建筑——燕山书院。该院建造于文星阁二楼井冈山会师会谈地清朝中期，至今有二百多年历史，它罕见的历史奇观和古老的文化底蕴引起诸多学者和1927年11月，毛泽东在龙江书院创办第一期军官教导队，包括谭震林、贺敏学等专家的关注。经考古学家和专家认定，该院的建筑风格、教育方式，在全国都属罕见。150余人，学员中不少人后来成为人民解放军高级将领。书院一院门上留有对联“红军燕山书院位于遂川县堆子前镇鄢背村井下村民小组4号。清乾隆间，其祖黄由相',8,'null','{\"page_end\": 10, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:08'),(79,5,1,9,'150余人，学员中不少人后来成为人民解放军高级将领。书院一院门上留有对联“红军燕山书院位于遂川县堆子前镇鄢背村井下村民小组4号。清乾隆间，其祖黄由相中官兵夫薪饷一样；白军里将校尉起居不同”，真实地记录了当时的历史。率义方、义言、义齐三子开新基于井下村。乾隆三十八年（1773），黄由相去世，乾隆龙江书院还是著名的“井冈山会师”旧址。1928年4月，朱德、陈毅等率领南昌五十九年（1794），义方、义言、义齐兴建燕山书院与正亮堂，于嘉庆十一年（1806）起义保留下来的部队和湘南暴动农军来到龙市，与毛泽东领导的秋收起义部队胜利会师。竣工，费时13年。正亮堂大梁上现存“嘉庆十一年丙寅”纪年的标志，光亮明显。在龙江书院的文星阁，毛泽东与朱德首次见面，两人相谈甚欢。正亮堂为黄氏宗祠，住宅平面呈横排长方形，二井三进，内有9个厅堂，18个天井，这里的一草一木应该铭记，戎马倥、红旗漫卷的井冈山革命斗争时期，小小龙江之图文99间房，当地人称“九厅十八井”。房屋过道纵横连贯，有分有合。屋内的门窗、槅扇，书院，一代伟人欣然入住，既留下“一庭花草半床书”的革命佳话，又演绎出“万里风',10,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',484,NULL,'2026-08-16 21:12:08'),(80,5,1,10,'房屋过道纵横连贯，有分有合。屋内的门窗、槅扇，书院，一代伟人欣然入住，既留下“一庭花草半床书”的革命佳话，又演绎出“万里风大都选用坚硬木材雕刻鎏金，外墙上的窗户用红粉石雕刻而成，可谓古色古香，溢光流彩。云三尺剑”的经典传奇。书院侧景燕山书院全景\n\n燕山书院是井下村黄氏子弟研习攻读的地方，教师有家族中的先生，也有外面请的先生。听村里的老人家说，黄氏子弟及亲戚子弟都要到这里来读书院简介与布局图书，最多的时候有200 －300人。他们在这里读书是不要钱的，这种风俗一直延续到上个世纪之图文初。期间，此处共走出两名进士，他们分别是江西南安“忠信”门额知府周勋与广西太平知府黄存镗。据专家介绍，这处书院有三大特色。一是书院顶梁、壁板上的百幅中国彩绘画，历经了两百多年的风吹雨打，燕山书院彩绘画依旧鲜艳夺目。书院内景\n\n二是院旁的一眼古井，虽然井底早已被封存，但却从未干涸过，水源从何而来，令人费解。三是书院内有许多规则错落的小房间，专家根据书院两侧回廊的结构来推测，燕山书院实行的是分班教育，从启蒙教育一直到科举时文教育都有。这与同期其他书院的学生齐聚课堂、听先生讲学的教育方式迥然不同。燕山书院正以其独特的魅力引起学界的重视。曲山书院',10,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',515,NULL,'2026-08-16 21:12:08'),(81,5,1,11,'这与同期其他书院的学生齐聚课堂、听先生讲学的教育方式迥然不同。燕山书院正以其独特的魅力引起学界的重视。曲山书院薪火相承读曲山从吉安县城出发，沿着吉永公路一路向南，大概20分钟的车程，便到了千年古镇——永阳镇，从古镇街口往右拐，约行3华里，掠过一大片青翠的田野，会看到一片古村云集的地方。这片地方，当地人习惯叫做曲山。曲山依廖岭，临平湖，山清水秀，阡陌纵横，物产丰富。廖岭横亘，弯弯曲曲蜿蜒盘旋十多里，故取名曲山。不过，这个地名在现在的行政版图上已经找不到了，它是风行于宋、元、明、清时期的一个地名，曾经的曲山现在划分为3个村委会15个自然村。曲山在清以前因出了状元萧时中，榜眼萧良友，刑部尚书、兵部尚书萧维祯等众多文人雅士、乡贤名宦而成为闻名遐迩的村子，被誉为江右大宗、江南望族。曲山先后建了十之图文多个书院，从这些书院走出了二十多个进士，朝廷命官上百人，县州教谕几十个，其中江右书院行状元萧时中，榜眼萧良友，兵部尚书、刑部尚书、太子少保、历四朝皇帝的进士萧维祯，正亮堂全景文昌阁廖阳书院旧址——曲山小学\n\n抗倭英雄萧廷宣等一大批人物彪炳史册。愚斋书院。愚斋书院为萧不敏所建。萧不敏（1308—1434），号愚斋，早年从进士',12,'null','{\"page_end\": 13, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',512,NULL,'2026-08-16 21:12:08'),(82,5,1,12,'抗倭英雄萧廷宣等一大批人物彪炳史册。愚斋书院。愚斋书院为萧不敏所建。萧不敏（1308—1434），号愚斋，早年从进士王子让学诗，是个饱学之士。萧时中永乐辛卯以大魁入翰林，不敏领甲午（1414）乡荐会试，因弟弟时中为主考，避嫌投状礼部而归。回乡后，以授徒为业，成为江南名师。京师国老称之曰：“庐陵文章之盛莫如萧时中，功业之盛莫如萧维祯，至于首倡道学江右愚斋一人耳。”其门生学业、政绩卓著，学生萧缊仪任湖广武昌训导，萧缉熙任广东吴川训导，萧训任光禄寺署丞，萧必俊明经进士任高邮龙州训导。今愚斋书院已无迹可寻。廖阳书院。廖阳书院为萧不敏之子萧维祯所建。萧维祯（1406—1472），名肇，号廖阳居士，官至兵部尚书，1465年退休回家创办了廖阳书院。廖阳书院教学严谨，培养了众多人才，而且著书立说，文采斐然，成为曲山最有名的书院。其学子萧淮中著有《丽川集》；萧纶章著有《默斋集》；榜眼萧良友著有《龙文鞭影》。乡人遵照维祯的意愿，在廖阳书院内放置了一巨型赑屃，头向廖阳书院前的青云、扶摇二塔，远视平湖。如今廖阳书院的房舍已毁，在原址上兴建了曲山小学，只存一巨型石龟和一棵古樟树，石龟是否为当年的赑屃已无可考。',13,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',499,NULL,'2026-08-16 21:12:08'),(83,5,1,13,'廖阳书院的房舍已毁，在原址上兴建了曲山小学，只存一巨型石龟和一棵古樟树，石龟是否为当年的赑屃已无可考。荆州书院，为萧锷建，现已无迹可寻。惜阴书院，为萧允设于曲山南楼。萧允曾写了七律《书惜阴书院》一首，以励后人：“家无别业为孙谋，惟仗残编作校雠。书诵唐虞诗雅颂，经传周易史春秋。三千礼乐无疏略，十二时光强进修。细剪烛花潜体认，人间岁月正如流。”惜阴书院今亦无可寻。之图文养教书院，清初，由曲山一经堂四兄弟所建。2015年上半年此书院仍在，后因村廖阳书院石龟廖阳书院古樟\n\n养教书院牌匾里建设公共活动场地拆毁，留“养教书院”石刻牌匾，断成两截，在文化大革命中村民教室，大礼堂的两侧是厢房，做寝室和厨房，前面一个大院子，是学生活动的场地。星为保护牌匾，在石刻上覆盖了石灰保护，如今仍未洗去，但仔细辨识仍可以认出“养教灿书院前面的两层楼和厢房虽经岁月风霜，破败不堪，依然耸立，但已成为村民养牛的书院”字样。场所，令人不胜唏嘘。之图文星灿书院，为清末邑庠生萧魁斗的侄、孙所建。萧魁斗，字星灿，号亦白，一生授宋明清时期，曲山先后建起的这些书院薪火相承，为曲山培养了数不清的人才，是江右书院行徒为业。',13,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',493,NULL,'2026-08-16 21:12:08'),(84,5,1,14,'萧魁斗，字星灿，号亦白，一生授宋明清时期，曲山先后建起的这些书院薪火相承，为曲山培养了数不清的人才，是江右书院行徒为业。其侄国贞、孙儿柏生，根据星灿的意愿，利用星灿的遗留资金，经过精心设计，曲山成为江南望族、江右大宗、人文荟萃之地的一大重要原因。建造了星灿书院。星灿书院很具有现代学校的风格，中间是大礼堂，前面是两层楼四个养教书院主楼，2015年下半年拆毁星灿书院主楼',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',184,NULL,'2026-08-16 21:12:08'),(85,6,1,0,'石莲书院之图文江右书院行罗洪先修行的石莲洞石莲书院古溶洞石莲书院因位于我故乡吉水县的石莲洞而得名，原本不叫这个名字，而叫正学书院。正学书院由明朝嘉靖八年状元罗洪先创办，距今已有五百多年历史。但由于石莲洞的名气大于正学书院，因而正学书院这个名称反倒被世人所遗忘。石莲书院的创始人罗洪先，是一位才华横溢的封建士子，吉水盘谷黄澄溪人。他一路过关斩将，至明朝嘉靖八年殿试，一举夺魁，轰动一时。但罗洪先与其他科举士子不同，在高中状元、朝廷授予他翰林院从六品修撰之职时，他竟然请辞，归隐石莲洞。归隐之后的罗洪先以传播王阳明学说为使命。为此，他在石莲洞旁边大兴土木，办起了书院，叫做正学堂，后来改名正学书院。在他心目中，世界上所有的学问，唯有王阳明心学才是真正的学问，因而被他称为“正学”。他亲自担任正学书院的首任山长，四处邀请学者名家前来讲学，其中有欧阳德、聂豹等人。一时间，正学书院名声远播，前来从布满藤蔓的残墙\n\n学者一时如云，使之与白鹿洞书院、鹅湖书院齐名，万历五年进士曾乾亨、万历十一年侧有厢房是书院杂役探花刘应秋，都是这里走出去的著名学子。罗洪先去世之后，依然有众多学子前来求学，的居所；二进为“正',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',498,NULL,'2026-08-16 21:12:08'),(86,6,1,1,'侧有厢房是书院杂役探花刘应秋，都是这里走出去的著名学子。罗洪先去世之后，依然有众多学子前来求学，的居所；二进为“正依然有许多学者前来讲学，“洞主乘龙去，何时更返槎。岩头明月在，常照石莲花。”学堂”；三进为“观罗大纮刻在石莲洞岩壁上的这首诗，就是众多学子缅怀罗洪先的一个历史见证。复阁”；两侧为“六石莲洞，因为罗洪先而知名，因为读书声而留名。在我残存的记忆里，书院的地面秀堂”和“归静处”，都铺着青砖，很是平整。书院依山势而建，分为三进：一进为书院山门和下房，院内两是“传道授业解惑”之处。二三进的房屋高大，前栋与后栋之间地势高差较大，有半人高。石莲书院历经沧桑，但从未断过书香。从古至今，一直开办着学堂，或官学，或私塾。在我幼年时期，书院称为阜田育红中学，后又改名为阜田五七中学；1977年，之图文阜田五七中学将高中江右书院行部搬回阜田圩镇，并改回原名阜田中学，书院旧房石莲洞旁古树与石门遗址全景\n\n新兴书院新兴书院惜字塔新兴书院, 是一座建于宋咸平年间（998—1003）的书院。它是当地历史上最早的县级书院，同时，也是同一历史时期吉安市的第二大书院。它坐落于偏远的衙前镇上境村，衙前镇是遂川北部的一个小镇，而新兴书院就坐落',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',513,NULL,'2026-08-16 21:12:08'),(87,6,1,2,'县级书院，同时，也是同一历史时期吉安市的第二大书院。它坐落于偏远的衙前镇上境村，衙前镇是遂川北部的一个小镇，而新兴书院就坐落在上镜这个村子的中央。新兴书院有一个院坪，院坪的前面是一个池塘，在池塘的边上，有一棵又一棵的大樟树，樟树的边上是千亩农田；还有一座“惜字塔”，又被称之为惜字楼、焚字库、焚纸楼，书院遗址树木繁茂这座惜字塔建于宋代，是用于烧毁有文字的纸张的地方，是古人敬惜字纸的理念得以体现的场所之一。从书院的侧门进去，可以看到一根一根粗大的木柱子，它们早已经在岁月的浸染之中斑斑驳驳，那屋顶上的画板，早已经看不出原来的模样。之图文新兴书院培养出很多人才，从宋至清，走出的进士、举人、秀才，有100多人。皇新兴书院培养出很多人才，从宋至清，走出的进士、举人、秀才，有100多人。皇江右书院行书院旧房初中部留在石莲洞，叫做阜田中学石莲分校；1981年8月，石莲分校脱离阜田中学，更名为石莲中学；2003年，石莲中学撤销，并入阜田中学，其校舍开办了石莲完全小学。时移事易，校园的变迁也是历史的必然，这里虽已不再叫正学书院，但罗洪先当年的求大夫第，书院侧门学精神，依然生生不息，传承至今。\n\n三进式院落内景江右书院行书院藻井',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:08'),(88,6,1,3,'时移事易，校园的变迁也是历史的必然，这里虽已不再叫正学书院，但罗洪先当年的求大夫第，书院侧门学精神，依然生生不息，传承至今。\n\n三进式院落内景江右书院行书院藻井书院牌匾\n\n义学“名登天府”牌匾帝册封的翰林以下的学士有22人；朝廷、州、府所赐的牌匾就达36块。现悬挂于彭氏宗祠梁上的“名登天府”牌匾，就是历史最好的见证。更值得一提的是，作为一座书院，它带动了一个镇的兴旺发达，伴随着每年上千的学子带着随从来到书院求学，在书院的周边，形成了三条大街、五条小街的繁华景象。今天，新兴书院虽已经在岁月沧桑之中老去，但不老的仍是它的文化，是它的传承，是它烙在人们心里那永远不变的对文化的敬畏。上镜彭氏宗祠之图文江右书院行义学与卢氏玉祠全景卢家洲义学感怀在吉安，有太多的书院，随随便便拿出一个来，都能让人惊叹。这些书院，仿佛是镶嵌在城市中的宝石。虽然在岁月流逝中蒙上了尘土，但只需轻轻擦拭，便又会露出别致的光芒，引领着我们去探究那古老的故事。出吉安市区西南方向13公里处，有一个地方叫曲濑，曲濑多古村，而最有名的要数卢家洲古村。它是江西的第一个状元卢肇的后代在吉安这片土地上建造的。走进卢家洲，昔日的新宅早已斑驳，昔日的辉煌依稀可辨。',3,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:08'),(89,6,1,4,'它是江西的第一个状元卢肇的后代在吉安这片土地上建造的。走进卢家洲，昔日的新宅早已斑驳，昔日的辉煌依稀可辨。遗存的63栋明清建筑，每一栋都在向世人诉说着尘封的故事。在众多的建筑中，有四栋保存完好的古建筑非常特别，那就是卢家洲义学所在地。作为吉安市境内唯一保存完好的村级义学，它的意义非常明显。走进义学，古朴庄重的气息扑面而来。它就在卢氏玉祠的旁边，没有玉祠的开阔大气，\n\n却处处透露着实在。义学旧址分为两层，两层都有教室。屋内有天井采光，里面的窗户和一般民居的小漏窗不同，大而美观。义学故址前卢氏玉祠汉白玉门坎、门当汉白玉柱础的院落里，花草和果树并立，不知见证了多少勤奋的读书人。义学的院墙上，“卧薪尝胆，生聚教训”八个大字不知激励了多少寒门的学子。古村内三百多年树龄的罗汉松汉白玉门当特写200多年过去了，义学具体止于何时已不可考。据《义学碑记》记载，清嘉庆十九年，村里的族长公卢嘉缙发之图文前人所未发，倡导设立江右书院行义学。他一方面动员官用堪与故宫媲美的汉白玉做门框的卢氏宗祠员、地主回乡兴办义学，卢家洲明代古斜塔义学主房一方面拿出祠堂地租填补不足，加上私人捐款，义学就这样在卢家洲人的共同努力下成立了。如今义学成了遗址，而',5,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:08'),(90,6,1,5,'一方面拿出祠堂地租填补不足，加上私人捐款，义学就这样在卢家洲人的共同努力下成立了。如今义学成了遗址，而受过义学恩泽的人却大有人在。年逾八旬的现任族长公卢明琦至今还记得在义学就读的往事。义学内景在卢家洲古村，卢氏玉祠、斜塔、罗汉松被称为卢家洲的“三宝”，而义学，显得更为低调。然而，这个昔日承载着诗书教化功能的场所，在退出了历史舞台后，却依然矗立在那里，用无声而“科第征贡”牌楼\n\n至此，“复古书院”历经文庙、学宫、书院、学堂、学校，以及私塾、初小、高小、初中、复古书院高中的多轮变迁；从最王造时为复古书院题写的“为学日益”牌匾初招儒生20名，到在千年“复古”书流香校2000多名国家全日制高中生的规模；跨越这里高楼林立，古樟婆娑，一派现代气息，然而，这里却是名噪了江西近千年的“复了近千年的光辉历史。古书院”所在地。期间从1940年至2014复古书院起源于“学宫”（安福县令李康成于宋朝元丰四年，选城东南一华里的东年的74年间，共培养背重建而成）。至明朝嘉靖十三年，时任南京礼部郎中的邑人邹守益回乡，见“学宫”初高中学生达11万之年久失修，与知县程文德商议修建，历时两年建成，为此邹守益亲自题名“复古书院”。众。',6,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',506,NULL,'2026-08-16 21:12:08'),(91,6,1,6,'初高中学生达11万之年久失修，与知县程文德商议修建，历时两年建成，为此邹守益亲自题名“复古书院”。众。从1978年全国恢光绪三十一年，“复古书院”改为“复古学堂”。宣统元年，朝廷颁新宪，诏学堂复高考以来，为国家输更名学校，“复古学堂”又改为“安福县立高等小学校”，设初小、高小“四三”制，送了5000多名大中专共有十三届学生在此毕业。蜚声海内外的“安福三杰”罗隆基、王造时、彭文应，以及复古书院古樟近景人才。爱国诗人王礼锡，国民政府中宣如今，走进这所书香浓郁的千古书院，已找不见一丝丝古迹古物的痕迹，只有筑造部长彭学沛等一大批名人，都先书院时县令亲手栽种的复古古樟历经千年风雨依然挺立。但是，这丝毫不能掩盖“复古后就读过这所学校。书院”在中国教育史上创造的辉煌业绩。江右书院行民国十九年，国内硝烟弥漫，学校停办。民国二十九年，“七君子”之一、邑人王造时从上海回乡，其时省府通令学校复课，复古书院古樟群命各县创办县立初中。王造时倡导周利生、王博之等人将学校修复古书院图影缮，使其升格为“县立初级中学”。1958年，更名为“安福中学”，实行初高中并举的新教学体制；1980年，又被列为省级重点中学；',7,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',497,NULL,'2026-08-16 21:12:08'),(92,6,1,7,'缮，使其升格为“县立初级中学”。1958年，更名为“安福中学”，实行初高中并举的新教学体制；1980年，又被列为省级重点中学；1994年，时任国务院副总理的邹家华，百忙中题写了“安福中学”校名；20世纪末，“安福中学”分离成为一所独立的省级重点高中。复古书院旧址所在地——安福中学\n\n复真书院记忆深处乃复真萃胜楼门前石狮萃胜楼，书院主楼小时候，常常听父亲说起复真学堂的名号，说起它那昔日的辉煌和热闹，那时的我，心中便对它有了一种向往。向往着能进入复真学堂学习，最终却只能成为埋在我心灵深处的一个梦。参加工作后，偶然认识了一位从复真学堂毕业的学生，让我更进一步深入地了解了它。复真学堂，后更名为洲湖中学。缘于学校录取洲湖镇本地的初中学生和附近几个乡镇的高中学生而更名。其实，洲湖中学，原是一座书院，名叫复真书院，为明代几个学者所建，距今已有400多年历史。萃胜楼侧景“七步半”阶梯据史志记载，明嘉靖三十七年（1558），著名理学家、教育家邹守益倡导，刘邦采、刘阳、尹一仁、周儒等几位学者主持，远近百姓赞助，在原道教“北贞观”旧址创建书院，为当时著名的讲会式书院。理学家刘阳题匾“砥德砺材”，门楼曰“萃胜”，萃胜楼乃之图文',7,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',509,NULL,'2026-08-16 21:12:08'),(93,6,1,8,'刘阳、尹一仁、周儒等几位学者主持，远近百姓赞助，在原道教“北贞观”旧址创建书院，为当时著名的讲会式书院。理学家刘阳题匾“砥德砺材”，门楼曰“萃胜”，萃胜楼乃之图文书院的主体。复真书院是当时安福县南乡（今洲湖、金田、寮塘、甘洛等乡镇）的一所江右书院行重要学府，以陆象山、王阳明二先贤的“良知”“惜阴”为本，是安福古代最大的书院之一。自明迄清，复真书院几经修葺。清光绪三十一年（1905）改为复真学堂，为当时安福县四大学堂之一。民国初年，复真学堂易名复真学校，首任校长为拔贡彭廷珍。1938年下半年，江西省立南昌实验小学一部分迁移至此，设省立实验小学洲湖分校。1949年，设立“洲湖中心完小”。1957年8月，创办“安福县洲湖初级中学”，后改为“江西省安福县洲湖中学”。迄今为止，洲湖中学是江西省乃至全国连续办学历史最长的学校之一。无论是古代的复真书院，还是近现代的复真学堂、复真学校，均始终尊崇先贤的古训，校风严，学风正，为国家培养了众多品高学厚的人才。例如清代的“钦点翰林”王邦玺；王邦玺的儿子王仁熙、王仁照兄弟二人，也曾得到复真书院的熏陶，后中举；王邦玺的',8,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',479,NULL,'2026-08-16 21:12:08'),(94,6,1,9,'例如清代的“钦点翰林”王邦玺；王邦玺的儿子王仁熙、王仁照兄弟二人，也曾得到复真书院的熏陶，后中举；王邦玺的曾孙王礼锡，自小在由王邦玺与彭廷珍共同创办的复真高等小学堂学习，毕业后考入省立吉安第七师范学校，后成长为杰出爱国诗人。建国后的洲湖小学或洲湖中学，形成了“崇真求实，开拓进取”的优良校风。一代复真古樟掩映下的书院门楼\n\n又一代莘莘学子勤勉求学，从复真书院的土地上，走向全国乃至世界各地。登上七步半阶梯，书院古楼霎时进入眼帘。门楣上“萃胜楼”三字苍劲有力。山角书院书院大门口的古樟，用盘曲的虬枝诉说岁月的沧桑，繁茂的绿叶透出新春的气息。相传，古樟为炎帝南巡亲手栽种。萃胜楼大门两侧，一对石狮，略带粉红的古旧颜色，张着大嘴，向内侧微微昂起头。数百年来，石狮忠实地履行它守护书院的职责。这座昔日的书院，如今的洲湖中学，古色古香的萃胜楼和那复真古樟，与现代化的教学楼交相辉映，古今交融，熠熠生辉。“复真古樟”石碑之图文江右书院行泮池山角书院融儒道在安福县金田乡，有一个省级历史文化名村——柘溪古村。村中古建筑格局保留完好，尤其是独特的“儒、佛、道”三教共存的建筑文化，给古村覆上一层神秘的色彩。',8,'null','{\"page_end\": 9, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',495,NULL,'2026-08-16 21:12:08'),(95,6,1,10,'在安福县金田乡，有一个省级历史文化名村——柘溪古村。村中古建筑格局保留完好，尤其是独特的“儒、佛、道”三教共存的建筑文化，给古村覆上一层神秘的色彩。山角书院就是集儒道文化为一体的建筑代表。相传，书院始建于清代咸丰年间，是由一位名叫刘汉生的进士创建的。书院建成后初取名文昌阁，寓文运昌盛之意。后因柘溪村背靠武功山南段的天平岭，坐北朝南，三面环山，更名为“山角书院”。书院坐落在柘溪村口的大路旁，坐南朝北，占地面积486平方米。村口竖立着高大而古典的牌坊，一抬眼，“世代恒昌”四个正红的大字跃入眼帘。“千年古村人杰地灵文运昌盛；百姓乐土物阜民康遗风朴淳”“楚翁功德尔凯福，家族兴旺，根深叶茂；山角书院进士村，人文发达，裕后光前”， 牌坊左右的对联依旧展示着柘溪人曾经的辉煌和对生活的感念。沿书院旁公路行百十米，往左可见书院正门。萃胜楼\n\n书院一直三进，共三层。一楼正厅有个大“回”字型的天井，天井上方是巨大的天窗，透过天窗便可看到气势非凡的魁星楼。听老村长说，当时的山角书院是金田乡唯一的学堂，每年都有方圆十里的数十名学子入院就读，人才辈出。一进天井从宋至清，柘溪村出过秀才92名、举人14名、贡士1名、进士11名，四至',9,'null','{\"page_end\": 10, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',508,NULL,'2026-08-16 21:12:08'),(96,6,1,11,'里的数十名学子入院就读，人才辈出。一进天井从宋至清，柘溪村出过秀才92名、举人14名、贡士1名、进士11名，四至八品官员56名，废科举后书院全景有国学生28名。民国时期，碑文上镌刻着“清顺治进士、通议大夫、竹庵公自记”，这“过人之笔”无疑是山角书有大学生9名、中专学历的院孵化出来的另一项重要精神文化成果。达30名。近现代从村中亦山角书院与进士亭，以及建于清朝顺治年间、体现佛教立意的竹林寺，互为犄角，走出了3位教授，2位副教遥相呼应，构成一个独特的文化三角。这种和谐统一、并行不悖、相得益彰的文化现象授。一批批优秀人才从古村在全国都属罕见。之图文中走出，柘溪村因此也成了江右书院行“天上麒麟原有种，门前桃李自春风。”随着时代的变迁，山角书院虽已完成它的二进厅堂安福的名门望族，成了安福历史使命，但仍肩负着民俗文化的承载。它曾经创造的辉煌依然熠熠生辉，它已经成为史上赫赫有名的“进士村”。在村东向三百米处的一条古道上还建有一座“进士亭”，柘溪古村永恒魅力的风景线，成为安福崇文重教的精神标志，成为庐陵文化不可磨灭的该亭建于清康熙戊午年间，是村里进士刘竹庵为纪念他父亲而建造的感恩亭，亭内石刻记忆原乡。山角书院侧景\n\n匡山书院',10,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',512,NULL,'2026-08-16 21:12:08'),(97,6,1,12,'该亭建于清康熙戊午年间，是村里进士刘竹庵为纪念他父亲而建造的感恩亭，亭内石刻记忆原乡。山角书院侧景\n\n匡山书院匡山书院牌匾匡山书院笃思行宋初年间）创办的中国第一所官方认可的民办书院。书院教绩颇丰，民风日淳，消息传至唐明宗耳里，特命翰林学士书“匡山书院”并制成匾额赐之褒誉。书院创建后20多年，因慕罗韬先生高义，金陵名门望族刘、王、胡、陈、尹、杨、书院这个名字始于唐朝，是国家用来藏书和校典的地方，后来演变为讲学和藏书之肖等七姓皆迁居泰和，传入了尊崇儒术、清正平和、仁孝纯厚、居官廉慎的为人处世哲学。处，具备了讲学、藏书、祭祀三大功能。而泰和的“匡山书院”当属江西最早的书院之书院创建后700年间，续罗韬先生遗志，在相隔不到20里的范围内，苑前先贤先后于一，远在五代时期的后唐就颇具规模，略有名气了。相传匡山书院办学比河南嵩阳书院宋代在王山村创办了精忠堂读书楼，明代在固陂圩创办了仁善书院，清代在琴塘村创办早4年, 比庐山白鹿洞书院早10年，比长沙岳麓书院早35年。一经创立，便成为了中了明达书院，至今文脉不断，绵延不绝。匡山书院创建后900年间，启罗韬先生遗志，',10,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',481,NULL,'2026-08-16 21:12:08'),(98,6,1,13,'早4年, 比庐山白鹿洞书院早10年，比长沙岳麓书院早35年。一经创立，便成为了中了明达书院，至今文脉不断，绵延不绝。匡山书院创建后900年间，启罗韬先生遗志，国文化坐标上的一个重要原点，中国民办教育的兴起、江右学派的产生乃至理学思想的泰和全境书院林立，书声琅琅响彻青砖黛瓦。形成均发端于此。而今，经过一千多年的岁月洗礼，匡山书院孔圣殿、五经阁、学宫等实体建筑已经匡山书院，乃公元932年泰和先贤罗韬先生（罗韬，字洞晦，生于晚唐时期，卒于荡然无存，遗址上创办了一所小学，沿袭了院名。匡山书院散落的遗物几经辗转，被族人收集保存于宗祠之中。白驹过隙，斗转星移，匡山书院创建后越千年，今日的泰和人，不仅把教育刻在牌之图文匾上，写在斑驳墙上，更把教育种在心田里……江右书院行书院旧址旁祠堂书院门楼\n\n复初书舍书院牌匾复初书舍复如初“一双布鞋一顶帽，走南闯北立商号”“飞檐翘角坡屋顶，青砖灰瓦垛子墙”，说的就是中国历史文化名村——燕坊，一座画舫一般的庄园。在这个“庄园”里至今遗存着一个古代人习书之所——复初书舍。相传复初书舍，是鄢氏、饶氏共同兴建的。燕坊先辈们在赚了钱、建了宅之后，仍',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',487,NULL,'2026-08-16 21:12:08'),(99,6,1,14,'着一个古代人习书之所——复初书舍。相传复初书舍，是鄢氏、饶氏共同兴建的。燕坊先辈们在赚了钱、建了宅之后，仍不忘教育后代，于是在村中建起了“复初书舍”“衡公书舍”等习书之所。从第一次走近复初书舍，敬畏之心油然而生。这是村中唯一一座向南而开的书舍门坊，大约建于清朝早、中期。复初书舍的规模不大，和村中常见的天井院式住宅构造基书院内石门书院大门本一致。砖木结构，平檐有垛，悬山顶，单层，一门一进。面宽10.7米，进深16.4米，王羲之的艺术风格。移步舍内，书舍堂内正中上方挂有“袭峰堂”的匾额，匾额右侧有“道建筑面积178.4平方米。门楣上方阳刻“复初书舍”四字, 堪称行书书法的杰作，颇有光甲辰季冬吉旦”字样，可见书舍曾经的风光。之图文人杰地灵的燕坊，自鄢苍然南宋开基建村以来至清朝，走出的各级人才40多位。江右书院行有鄢蔼然、鄢邦梯、鄢士邦、鄢永庚、鄢月樵进士5人；有鄢瑞亭、鄢德垣、鄢培善、鄢维周等奉政、朝议及奉直大夫15人；有鄢荆山、鄢文柯、鄢南台等知县同知9人，还有承德郎16人。从这里可以看出来，燕坊官宦众多，涉足全国。可想而知，复初书舍承载过多少燕坊先人的梦想。',12,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',485,NULL,'2026-08-16 21:12:08'),(100,6,1,15,'还有承德郎16人。从这里可以看出来，燕坊官宦众多，涉足全国。可想而知，复初书舍承载过多少燕坊先人的梦想。复初书舍历经几百年的风风雨雨，至今依然屹立在燕坊村中，屹立在人们心中。“鹏抟凤起”门额书院全景\n\n衡公书舍衡公书舍潜行记酷热的7月，和朋友相约，来到了吉水县金滩镇燕坊古村，探寻一座叫衡公书舍的古书院。素未谋面，却有着像要去见一位老者般的急切心情。相传衡公书舍是燕坊古村中仍被保留的两座书舍中的一座。走进衡公书舍这一所老书院正门照壁对联房子，从外看去，老屋整体还好，庐陵风格，翘角飞檐，青砖灰瓦，风骨犹存。然而站在书舍门口，竟生出一股寒意。一股猪粪味扑鼻而来。正门开在侧墙，不是恢宏霸气的那种，红条石做的门框，仍显遒劲骨感，门框刻有对联一副，上联是“凤治烟浓窥学海”，之图文江右书院行书院屋架书院全景书院远景\n\n武城书院武城书院思追远书院牌匾恩江河畔书声琅琅，书生翩翩。两千年来，恩江水不仅养育了一代代曾氏族人，还孕育了一座古代文化庄园——武下联是“蓬山秋霁见词峰”。门楣有石雕，石雕中间似乎为拜师图，一老者坐于椅上，城书院。另有两人抱拳躬身向着老者，一幅尊教重儒样，栩栩如生；拜师图两侧雕的是喜报卷轴，',12,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',503,NULL,'2026-08-16 21:12:08'),(101,6,1,16,'门楣有石雕，石雕中间似乎为拜师图，一老者坐于椅上，城书院。另有两人抱拳躬身向着老者，一幅尊教重儒样，栩栩如生；拜师图两侧雕的是喜报卷轴，一个艳阳朗照的日子，我邀友来到书院。书院始建于1317年，由晞颜子孙竭尽家财，可见书舍建造者饱含的一番思虑。门额上是“衡公书舍”四字，算为书舍名了，四字楷体，几经周折最终建成。明朝状元曾棨从这里走出，他与朱棣巧对及写800行梅花诗的佳话遒劲有力。再看到的是，悬挂在屋梁、角落、门框等处的一张张蜘蛛网，残破不堪的木流传千古。后武城书院虽几经修茸，终不敌岁月的侵蚀，梁朽瓦破，墙塌院损。2013年门框仅够支撑墙体，老旧损坏的墙体已经斑驳陆离，存有的木雕褪去了颜色。龙潭曾氏及外徒后裔，捐资捐物，在原址上重建。所以眼前的书院，灰墙黛瓦，飞檐翘角，我们离开书舍，想去更多地寻找一些关于它的故事传说。打听到在书舍邻近的茶馆古朴雅致，崭新亮堂。抬头，门额上四个遒劲大字“武城书院”。武城结缘于“鲁国南里有一位饶兴甲老板，或许他有些了解。询问间，饶兴甲说，书舍是他的老祖宗建的，武城沂河岸上，孔夫子与弟子曾皙畅谈治国理念”一事，曾皙之子曾参也是孔子的高足，至于哪个老祖宗，不是很清楚，解',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:08'),(102,6,1,17,'武城沂河岸上，孔夫子与弟子曾皙畅谈治国理念”一事，曾皙之子曾参也是孔子的高足，至于哪个老祖宗，不是很清楚，解相传《大学》一书是他所著，后世尊他为宗圣。历来曾姓均以宗圣公曾参为自己的开派祖。放初期还在里面办过学。“可能有之图文武城即为曾氏“追远”的金色符号。江右书院行几百年的历史。”饶兴甲摸着脑袋说。走进书院，似乎能真切地听到曾经的虎啸龙吟，顿觉这书院分明是一个硕大的深潭，返回到衡公书舍，曾经的辉煌已经是个卧虎藏龙的地方。不再，昭示的是曾经的沧桑，让人“偷窥到民族步履的蹒跚”。留存的衡书院全景公书舍曾改建成猪舍，而今已成为或是飞鸟栖息的乐园，或是鸣虫嬉戏的佳所，空寥冷落，往昔的书声早已是昨日的陈迹了，让人不胜唏嘘。书院大门',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',314,NULL,'2026-08-16 21:12:08'),(103,7,1,0,'青云书院冲应山秋祭前贤一种悠远的神往，若即若离地隐藏在我心中已有几十年了。小时候，在我家的后山上，一眼就能望到天边山巅上树木隐蔽中的一道白墙壁。村里老人说，那是冲应山上的一座神坛，那时的我便对此有了一种向往。书院内景其实，这山，名不见经传，坛也并不大，但这是当地百姓心中的圣地。一年四季香火萦绕，祈风调雨顺，五谷丰登，百事顺遂，一方平安。一到下半年，农事空闲下来，祭祀就开始了。五十六都一带的民众每年都要在此举行盛会祭典，远远近近的地方抬着村坊上的福主菩萨前来朝拜。上上下下，这样的活动要持续三个多月。冲应山腹地有一座水月庵，那亦是神奇之地。古老的传说为小小的水月庵披上了一层神秘色彩。在水月庵的近旁，还有一座青云书院。书院早就倒塌了，在没膝的野草中，厅堂、天井、厢房等整个建筑格局还是依稀可辨。历尽一百多年的风雨，我们尚能看到之图文江右书院行书院牌匾书院残墙\n\n书院遗址内景二书院遗址内景一书院残垣之图文江右书院行书院遗址外观书院残墙像一个不屈的汉子傲立于深山野谷之中。青云书院始建于清光绪年间，是杨家庄举人杨兰君建造的。老先生清正廉洁，因不满官场黑暗，忍受不了那些卑劣习气，愤然辞官回乡。他看到冲应山幽美恬静的山水环境，',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',512,NULL,'2026-08-16 21:12:08'),(104,7,1,1,'老先生清正廉洁，因不满官场黑暗，忍受不了那些卑劣习气，愤然辞官回乡。他看到冲应山幽美恬静的山水环境，是一个读书养性的好地方，便在山中建造了这座青云书院。先生去世后，青云书院一度空闲。民国初年，金滩地区以廖世英、刘嘉林等为首的一帮乡间知识精英人物在此聚众讲学，青云书院名噪一时。至民国十九年，共产党人黎明九在此进行革命活动，秘密发展革命组织，并策划暴动。密事酝酿已久，业已成熟，就等待时机，却因叛徒告密，举事失败。最终，这批革命志士30多人全部壮烈牺牲。青云书院也被一把大火烧塌。冲应山、青云书院默默地为中国的命运奉献了忠诚，那段惊心动魄的历史也被风雨隐没在时空中而无人知晓。秋深矣，冲应山的神灵们、先贤们，且撮土为香，洒泉为酒，千古凭吊，谨此一祭！启明门书院遗址内景三\n\n泷冈书院千年薪火传泷冈向东沿赣江支流泷江而上，有座叫沙溪的古镇。据县志记载：在沙溪泷冈西阳宫右，宋敕赐欧阳修读书之堂。1311年里人艾幼学建文儒书院。1627年艾日升重修。1820年李维与重修。1865年李奇珠重修，并捐田五百六十多石，供膏火之费。1904年改为文儒高等小学堂。现存门楼牌坊是清康熙十年维修重建的，其正面门楣上方镌刻“西阳宫”三个大字。',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',512,NULL,'2026-08-16 21:12:08'),(105,7,1,2,'1904年改为文儒高等小学堂。现存门楼牌坊是清康熙十年维修重建的，其正面门楣上方镌刻“西阳宫”三个大字。祠右是一幢凹型建筑，赭红色的门楣上方镌刻“泷冈书院”四个繁体大字。大门左侧刻着泷冈书院简介：“清嘉庆己卯年（1819）李维与捐资重修文儒读书堂，并扩建了书院着泷冈书院简介：“清嘉庆己卯年（1819）李维与捐资重修文儒读书堂，并扩建了书院书院内景前楼，合称为泷冈书院。1959年改作中学。学校秉承欧公遗风，泷冈书院门楼培养了大批优秀人才。今为纪念欧公千年诞辰，永丰县人民政府重修。二零零七年八月六日。”之图文江右书院行祠左是“泷冈阡表碑亭”。碑亭正中竖立着《泷冈阡表》碑石，正面刻《泷冈阡表》碑文，背面刻《欧阳氏世系表》，字体端庄稳重，雄健有力。《泷冈阡表》是欧阳修为纪念母亲养育之恩满怀感激之情写下的祭文。欧阳修幼年丧父，家贫买不起笔墨。郑氏在沙滩上折荻秆为笔，以沙滩为纸，教欧阳修读书写字，成就了一段“画荻教子”的千古佳话。郑氏也因此成了中国历史上“四大贤母”之一。泷冈书院后侧还建了一个“画荻楼”。泷冈书院、欧阳文忠公祠、画荻楼和泷冈阡表碑亭等建筑被定为省级重点文物保护单位，四周砌起了高高的围墙。围墙',3,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',505,NULL,'2026-08-16 21:12:08'),(106,7,1,3,'泷冈书院、欧阳文忠公祠、画荻楼和泷冈阡表碑亭等建筑被定为省级重点文物保护单位，四周砌起了高高的围墙。围墙旁边，一所以“欧阳修”名字命名的中学崭新漂亮，正对校门矗立着欧阳修的铜铸雕像。先是文儒读书堂，后是文儒书院、泷冈书院、文儒高等小学堂、沙溪中学，演变到现在的欧阳修中学。沧桑岁月，时势变革，兴衰更替，名称虽改，文风绵延，欧公精神永存。\n\n爱莲书院青草幽巷书声琅相传在古村落中，建有高大宽阔的祠堂，是传统村落村民曾经生活的中心。在祠堂中或者在祠堂边，多有书院的遗存，如敦厚镇店下村的“爱莲书院”，梅塘镇小灌村的“省吾书院”，浬田镇浬田村的“科山书院”等。据《仕江店下周氏族谱》记载，爱莲书院始建于道光戊申年（1848），由店下村中“义士”周青亭捐资修建。爱莲书院紧靠在周氏宗祠的右边，为同时修建而成的建筑群。长度与周氏宗祠齐平，近40米，宽达14米，500多平米的建筑空间，按照祠堂的建制修建，为三进两天井的格局。爱莲书院近年经过一定的修缮，外观有所改变，主体维持了原貌。正门洁白宽厚的汉白玉门框，显示了书院不凡的气势，进入门内为一门廊，门廊再往前，便是一正圆形的门，透过门望见的是通透明亮的宽阔空间。由方至圆，由暗至明，独特',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',513,NULL,'2026-08-16 21:12:08'),(107,7,1,4,'正门洁白宽厚的汉白玉门框，显示了书院不凡的气势，进入门内为一门廊，门廊再往前，便是一正圆形的门，透过门望见的是通透明亮的宽阔空间。由方至圆，由暗至明，独特的传统建筑艺术，才能营造出这种奇特的氛围。明亮的空间正中为一天井，四周为走廊，之图文江右书院行十根方形立柱，将两边宽阔的走廊分隔成对称的格子，在这些格子中，曾经放置着一排阡表碑亭欧阳文公祠书院大门牌匾\n\n排的书桌。立柱面上，书有描金的楹联，如“日月两轮天地眼，诗书万卷圣贤心；益我无如书味好，可人还是菜根香。”立柱上支撑着双层的木质结构，楼上则是三面厢房。无疑，爱莲书院是经过精心雕琢的，才成就兼具结构和装饰的典雅与明亮舒适的宜居环境。捐建者周青亭将书院取名为“爱莲书院”，意在尊崇周敦颐《爱莲说》之义，勉励后辈秉持像莲花一样的君子品行。星移斗转，逝者如斯，古人的身影消失在斜阳阡陌中，村落中的书院因科举的废除而停办，琅琅的读书声消失了，只留下亭台楼阁静默矗立，像怀着满腹故事的老者，静书院内景静地坐着，无言。江右书院行书院与宗祠间小巷书院后堂木雕装饰霁月门\n\n横溪书院横笛清溪书香远文天祥题固山古寺平匾横溪书院坐落于万安县窑头镇横塘村，在县城东南约30公里。书院东南雄踞东华',4,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',515,NULL,'2026-08-16 21:12:08'),(108,7,1,5,'横笛清溪书香远文天祥题固山古寺平匾横溪书院坐落于万安县窑头镇横塘村，在县城东南约30公里。书院东南雄踞东华山和天湖山两座名山，门前有芦源河和蕉源河交汇的溪流，书院故而得名。依山傍水，沃野无边，绿意盎然，宁静旷远，确为修身治学好场所。据族谱记载，书院系族人张昭垲于光绪甲申年（1884）创建。张昭垲，字晏居，名善敬，号益齐，嘉庆丙子（1816）年生。书院坐北向南，砖木结构，四扇八间，宽10.9米，深13.3米。垒有四个台阶通往书院，大门楣书“横溪书院”四个字，用云纹和云雷纹圈边, 弓形额方，檐额绘文房四宝山水画，一顶二顺法砌墙。相传清嘉庆年间，张氏先人创建书院，意在重振读书风气，再出贤能。这与文张（文天祥与张氏）两姓为庐陵世家密不可分，为此还有“固山古寺”见证。“固山古寺”坐之图文江右书院行书院牌匾书院全景书院门楣\n\n落于书院西北约3公里，建于南宋，寺庙分前后两栋，中间是天井，一边有耳门，依古代祠堂规制而建。虽为寺，实为横塘张氏祖祠。寺内供奉一尊千手观音像，侧室塑有一尊文天祥雕像。每逢祭祀，族人先拜先祖，再拜文天祥。此乃文张两家原为庐陵世家的历史见证，两家在固山均有别业。后张氏自庐陵西街徙居万安横塘，仍交往甚密。文天',6,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:08'),(109,7,1,6,'此乃文张两家原为庐陵世家的历史见证，两家在固山均有别业。后张氏自庐陵西街徙居万安横塘，仍交往甚密。文天朗山书院祥中状元时，为固山寺亲题“大雄宝殿”匾额一块，款题“赠张府”，刻“文山印”，现仍存寺内。如今的书院门前被葱郁的杂草占据，院内也是杂乱无章，带着草香的牛粪掩盖了当年学子指点江山、激扬文字的意象。时过境迁，如今，学校建设相对完善，横塘作为行政村只能有一所村级小学，但横溪书院依然屹立。书院前的护林经百年书声浸润，越发显得精神，风声过处，猎猎作响，如遥远的句读之声，横亘在村庄上空。之图文书院侧景朗山书院草木深朗山书院坐落在吉水县金滩镇的栗头村一角，离村子中心有些远，遗世而独立。朗山书院所在的栗头村是一个历史悠久的古村落，建村近千年，村里的建筑、文物古迹没有遭受兵燹，保存完好，曾氏家族的世世代代也得以在此安居乐业，繁荣昌盛。清道光年间，栗头村的曾氏家族挑选能工巧匠费时费力建成了朗山书院。书院是栋砖木结构的建筑，青砖磨缝，硬山顶，朝天式防火墙，一门两进，三开间，穿斗式木构架。进深34.5米，面宽15米，面积517.5平方米。正面为庑廊式结构，门楣正上横墨楷书“朗山书院”四字。',7,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',493,NULL,'2026-08-16 21:12:08'),(110,7,1,7,'进深34.5米，面宽15米，面积517.5平方米。正面为庑廊式结构，门楣正上横墨楷书“朗山书院”四字。前厅两侧有骑楼，上下两层，且用木板隔成若干间书房。中间设天井，将头进与二进用槅扇隔开。整座建筑规模宏大，结构复杂，是个兼书院、祠堂两用的典型古建筑。书院侧墙\n\n书院侧面书院主体保存完好，但木质构件都有不同程度的损坏，天井周边也是绿草肆意生长。据介绍，书院2005年被吉水县人民政府设为县级文物保护单位，政府也曾在前些年投书院内景入了一定资金进行维护，但古建筑维护成本特别高，政府的投入还是严重不足，村里也无力贴补，目前只能这样维持着。之图文江右书院行书院远景\n\n科山书院遗落浬田见科山科山书院坐落于吉安县浬田镇浬田村。据《庐陵县志》记载，科山书院始建于元末，历经明、清代刘氏数次重修，现存建筑为清末所建。书院坐东向西，长11.9米，宽33.8米，占地面积402平方米。现所保存的建筑正面山墙为原有建筑，其后为近年重修。正面山墙上有一石灰粉饰的牌匾，镌刻“科山书院”四字楷体阳文，牌匾四周为浅蓝色框，框上点缀莲花状石灰塑浮雕，工艺精美，风格清丽，流露出别样的书院气息。书院大门两精致木刻',7,'null','{\"page_end\": 9, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',493,NULL,'2026-08-16 21:12:08'),(111,7,1,8,'墙上有一石灰粉饰的牌匾，镌刻“科山书院”四字楷体阳文，牌匾四周为浅蓝色框，框上点缀莲花状石灰塑浮雕，工艺精美，风格清丽，流露出别样的书院气息。书院大门两精致木刻边原有楹联“浬水河清海晏；科山斗转星移”，现已消失。浬田村于元朝中期由开基祖刘以立开基，距今约700年。浬田村自开基以来，文风其实，朗山书院并没鼎盛，明清两代诞生了明万历工部侍郎刘日升、刘忠、刘信、刘昭、刘轩儒、刘禹谟、在我们的庐陵书院拍摄目录刘遇奇等7名进士，70多名科举贤达。村族谱中记载，科山书院曾由刘日升的后裔重修，里，机缘巧合，让我们意外庐陵县志中也称“科山书院为刘氏百年读书之所，其代有科甲皆基于此”，科山书院之图文地走近了她。在庐陵有遗存江右书院行的书院里，她不算是保存最完好的，但也算得上保存得水映科山比较好的，相比那些只剩下断垣残址的书院，那真是一个意外的惊喜，算是我们为八角型藻井学校书院研究拾起了一颗遗落的明珠吧。书院内木结构\n\n的荣耀历史由此可见一斑。至清代，族人刘维先于光绪丙午年间钦赐翰林院检讨，对于培育了自己的科山书院，刘维先饱含深情，倡议全族捐资扩建，由此形成清新典雅的院落。民国初期，科山书院改为第四十九保立小学校。文书院内景',9,'null','{\"page_end\": 10, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:08'),(112,7,1,9,'维先饱含深情，倡议全族捐资扩建，由此形成清新典雅的院落。民国初期，科山书院改为第四十九保立小学校。文书院内景革期间，毁损严重，后重新修缮做村办小学。江右书院行书院侧景澧田村科山书院门楼\n\n涧东书院涧东书院颂东固在东固新街南端，革命烈士纪念碑下之西南，有一个书院。书院最早被称为东溪书馆，设在东固河东御龙祠内，既招收刘氏子弟，也招收外姓子弟入学。1745年，改为“牛角书院”。书院院舍青砖黛瓦，飞檐翘角，很有气派。1888年，牛角书院改称为涧东书院。1898年，涧东书院改名为“涧东小学堂”，实行课制改革。民国元年（1912）更名为“涧东初高两等小学校”。越四年，又更名为“涧东国民小学”。1927年，因“东固暴动”书院被烧毁。1941年，重建校舍。解放后，涧东小学改为东固小学。江右书院行晚清涧东书院学子曾光潮课试卷涧东书院历史悠久，从东溪书馆，到牛角书院，到涧东书院，再到东固小学，书院名虽然一改再改，然而不改的是东固人办教育的决心。书院从1745年至1898年止，百余年间为国家培养出了一大批优秀人才。如早期的刘德沛、刘承恭、刘亦材、刘亦璠、刘德淐、刘令宣，太学生刘世珖、刘亦璇，武举刘',10,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',495,NULL,'2026-08-16 21:12:08'),(113,7,1,10,'书院从1745年至1898年止，百余年间为国家培养出了一大批优秀人才。如早期的刘德沛、刘承恭、刘亦材、刘亦璠、刘德淐、刘令宣，太学生刘世珖、刘亦璇，武举刘世烆、邑文庠、刘永金，武庠刘永仑等；后来的“点炮将军”欧阳豪；留学日本明治大学，官居国民政府立法院的刘纪；赖经邦、曾炳春、刘经化等。状元及第牌匾\n\n竹隐书院竹隐书院隐何处？竹隐书院坐落在吉安市青原区富田镇横坑村前端，坐北朝南，始建于正德癸未年（1443），土坯房建构。修建年代距钱尧翁迁徙横坑（古名泓溪）立基的年代（1331）有一百多年，到了明成化辛卯年（1471）钱金鉴这代，在竹隐书院的原址上扩建为一座祠堂，叫崇义堂。崇义堂虽然改建成祠堂，实则是个书院。祠堂里人才辈出，有中国人民解放军总参三部部长、政委、少将、第六届全国政协委员钱江；有被誉为“纯化河里的一支笔”的钱克谐。1949年建国后，崇义堂就成了富田乡的文化教育中心。1964年，富田农业中学由崇义祠内景书院旁小巷花岩迁来。1969年，富田农业中学正式改名为“富田初级中学”。1970年，学校招生长岁月，竹隐书院的教育教学功能算是功德圆满，接下来她要行使的将是旅游功能——',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',494,NULL,'2026-08-16 21:12:08'),(114,7,1,11,'1969年，富田农业中学正式改名为“富田初级中学”。1970年，学校招生长岁月，竹隐书院的教育教学功能算是功德圆满，接下来她要行使的将是旅游功能——规模扩大，祠堂地面全部改造成教室，楼上作学生宿舍。1971年春，富田中学迁往今富“横坑古村游客服务中心”。田开发区“十八海”山上的新校址，横坑小学搬来，直到1983年。经过了540年的漫之图文江右书院行竹隐书院旧址崇义祠崇义祠内景\n\n叠山书院叠山书院写精神在江西省上饶市弋阳县东门，坐落着闻名全国的叠山书院。书院正门匾额“叠山书院”是由林则徐亲笔题写的。字体遒劲有力，给叠山书院增添一抹亮色，也为弘扬叠山精神传下佳话。带着一份崇敬的心情，我查阅了叠山书院的史料。叠山书院历史悠久，于元朝皇庆二年（1313）建立，是为纪念南宋著名的爱国志士、绝食殉国的民族英雄、教育家谢叠山，由他的弟子俞舜臣带领徒弟建成。书院建立后一直以叠山精神为其学院的精神要旨开展讲学活动。上饶书院之图文书院正大门——礼圣门\n\n明代宗景泰四年（1453），朝廷为谢叠山平反。明朝提学副使、理学家李梦阳，礼部尚书汪俊等名流，慕名前来叠山书院讲叠山事迹和叠山理学思想，使叠山书院的名声更加远播，成为江南著名书院。',12,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',513,NULL,'2026-08-16 21:12:08'),(115,7,1,12,'学家李梦阳，礼部尚书汪俊等名流，慕名前来叠山书院讲叠山事迹和叠山理学思想，使叠山书院的名声更加远播，成为江南著名书院。清朝乾隆年间，叠山书院增建了藏经阁。清道山长室光年间，书院又增建了由三栋平房组成“凹”字形房屋的桂花园。1849年，在弋阳县令陈乔枞的主持下，将弋阳县内所有的叠山书院合并，全都迁入今讲经堂叠山书院，进行统一管理。之图文近代教育普及后，叠江右书院行山书院于1902年被改成弋阳县高等小学堂，1912书院牌匾年更名为弋阳县立高等小学。1916年，方志敏考进弋阳县立高等小学读书，在这里他深受“叠山精神”影响和科学民主思想的启蒙教育，立志为“中国独立解放而斗争”。1917年，方志敏发起并在书院的望江楼成立进步团体组织“九区青年社”，本着“铲除人间不平，和恶势力斗！”的宗旨，他们开展了一系列的斗争，展开无神论与有神论的大辩论，在桂花园里组织学生焚烧日货等进步活动，在当时思想落后的弋阳形成了较大影响，为解放弋阳人民的思想提供了一次契机。叠山精神千百年来激励着后人学习和效仿。1952年，当年在叠山书院和方志敏一起读书的江西省省长邵式平将叠山精神完整地概括为：誓死抗元的爱国精神，关心百姓',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',500,NULL,'2026-08-16 21:12:08'),(116,7,1,13,'1952年，当年在叠山书院和方志敏一起读书的江西省省长邵式平将叠山精神完整地概括为：誓死抗元的爱国精神，关心百姓的爱民精神，敬老爱幼的孝慈精神，不慕名利的廉洁精神，坚强不屈的奋斗精神。如今，叠山书院已是江西省现存规模较大、建筑构架保存完整的古代书院之一。1987年书院被江西省列为文物保护单位。明伦堂',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',150,NULL,'2026-08-16 21:12:08'),(117,8,1,0,'信江书院朱熹题写的“碧落洞天”石刻2013年，在叠山书院建院700周年之际，江西省书院研究会在这里举行了全国书院学术研讨会，会后叠山书院再次引起业界人士的关注。弋阳县政府也高度重视，与上饶方志敏管委会一起出资重新修整了书院，重新布展，增加了书画廊等内容，把历代名人与叠山书院有关的诗词歌赋都刻在墙上供大家参观学习，进一步弘扬和传承叠山事迹叠山精神，弘扬和保护书院文化。之图文江右书院行钟灵台信江书院今胜昔在江西省上饶市, 坐落着一座信江书院，它前临信江后绕黄金山，既有泉林之趣，亦拥风竹之美，环境很是清幽。信江书院始建于康熙三十三年（1694），曾经叫做曲江书院、钟灵讲院、紫阳书院，18世纪后被称作“信江书院”至今。它曾经被誉为江西古代四大书院之一，对古代上饶教育和理学的发展产生了巨大的推动作用，至今还在发挥着作用和影响。据同治六年（1867）广信府知府钟世桢在《重修信江书院志》序中记述：“信州之有书院，自郡守张公始。”张公，即康熙年间的广信知府张国桢，由于其为官清正廉洁，当地士绅集资兴建了他的生祠，张国祯坚决不肯接受，最后将其改为义学，在大门上题\n\n匾曰“曲江书院”。康熙五十一年（1712），',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',502,NULL,'2026-08-16 21:12:08'),(118,8,1,1,'当地士绅集资兴建了他的生祠，张国祯坚决不肯接受，最后将其改为义学，在大门上题\n\n匾曰“曲江书院”。康熙五十一年（1712），知府周淳元对书院进行修葺扩建。由于书院的环境得天独厚，“钟山峙于后，灵山揖于前”，书院因此改名为“钟灵讲院”。乾隆八年（1743），信州知府陈世增重新修建了信江书院，后为纪念朱熹对上饶人民的教化，书院的名字书院大堂也改为“紫阳书院”，其后，书院首屈一指，远近闻名。当时的巡抚陈宏谋特意赠书匾“共学适道”。乾隆四十六年（1781），新任知府康其渊把书院改名为“信江书院”。1810年，书院又购两旁民房35间改为乐育堂、近思堂，改建了斗山阁、书院庭院书院内木雕五星堂、蒙泉堂及青云别墅、亦乐堂、一杯亭、问月亭、夕秀亭、三希殿等。讲堂嘉庆二十年（1815）知县周力田于春风亭后添修三希殿。同治六年（1867），之图文知府钟世桢再次大修，并重修了《信江江右书院行书院志》。增建魁星阁、钟灵台、日新书屋、课春草堂等。为明确信江书院之源流，清朝地方官府曾两次修《信江书院志》，嘉庆十四年（1809）十二月，知府王赓言上书院精舍任即重修书院，首撰《信江书院志》三“乐育堂”牌匾卷刊行，并亲自作《重修书院记》。',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',509,NULL,'2026-08-16 21:12:08'),(119,8,1,2,'十四年（1809）十二月，知府王赓言上书院精舍任即重修书院，首撰《信江书院志》三“乐育堂”牌匾卷刊行，并亲自作《重修书院记》。同治六年（1867）广信知府钟世桢重修《信江书院志》十卷刊行。光绪年间，广信知府查恩绥创设经训堂，作《经训堂章程》，辑为一卷为附编，以增刻刊行。这是目前我们能看到的关于信江书院保留下来的最早资料，弥足珍贵。自清代以后，信江书院脱颖而出，独领风骚三百余年，声名远播，成为上饶人杰地灵、人文荟萃的重要象征。清朝末年，书院日渐腐朽。中日甲午战争以后，书院陆续都被改成了新式学堂。“书院”便成了一个历史名词。解放后上饶市政府在书院旧址建了上饶师范，后迁出合并到上饶师院。1983年信江书院被列为江西省文物保护单位。现书院已被上饶市政府改为信江书院博物馆，于2015近思堂\n\n明经书院千山万壑驻明经婺源县紫阳镇考水村，一个千年文化古村。千百年来，历宋、元、明、清以经学传家，贤俊辈出，载誉四方。其中明经书院，就曾赢得了“进士走廊”的响亮称号。明经书院坐落于考水古村的中街尽头，由唐太子胡昌翼隐姓埋名，世居考水，繁衍生息而后创办的。创办这所书院原本就是一种政治上不得志的精神寄托，却无意中造就',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',503,NULL,'2026-08-16 21:12:08'),(120,8,1,3,'明经书院坐落于考水古村的中街尽头，由唐太子胡昌翼隐姓埋名，世居考水，繁衍生息而后创办的。创办这所书院原本就是一种政治上不得志的精神寄托，却无意中造就了政治和文化上的两个制高点，成为继中国四大书院之后起之秀。曾经有一建筑“进士走廊”刻记着历宋、元、明、清四朝代录取的进士就有八百余人。无怪乎，当时的天下明经书院地形图学子对这所民间的“翰林院”趋之若鹜。事实上在书院改制以前，这所书院确实是一个鸿儒云集的圣地。淳熙十二年（1185）秋，朱熹和陆九渊来考水明经书院继续鹅湖之会的辩论课题，一个理学宗师、一个心学大家，两位学师的人品、气节、学问无疑是当时学术界的泰斗。之图文这次两颗巨星的碰撞，无疑是一个巨大的震撼。这是明经书院在中国书院史上最光彩的江右书院行明经书院遗址远景\n\n一页。此后，历经宋、元、明、清四朝代，明经书院坐拥名副其实的文人圣地。四朝皇帝都赐匾于明经书院，至今保留完整的清康熙御笔亲书金字匾“儒理至宗”, 联“文官下轿；武官下马”。足见当时明经书院是何等辉煌显赫。元至大三年，胡淀为明经书院捐田300亩，其弟胡澄也捐田60亩，供祭祀和师生廪膳之资。胡淀又增书屋200间，加强主体建筑，右为大成殿，左为会讲堂，有斋庐四',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',514,NULL,'2026-08-16 21:12:08'),(121,8,1,4,'元至大三年，胡淀为明经书院捐田300亩，其弟胡澄也捐田60亩，供祭祀和师生廪膳之资。胡淀又增书屋200间，加强主体建筑，右为大成殿，左为会讲堂，有斋庐四处和“明诚”“敬义”二塾在内，形成类似今天小学、中学、大学一体化的模式。“一时四方学者云集”“历数年，学者至盈千人”，书院规模达到了最高峰。元至正十二年（1352），书院遭兵火焚毁。明成化十六年（1480），胡云峰裔孙胡浚要求合族重建。万历十二年（1584），邑侯万国钦率族人又重建明经书院。清康熙五十三年（1714），胡氏合族将书院从原山麓移建于凤山东麓。而今的明经书院，只剩2500平方米的颓墙败垣，失去了过去的辉煌。明经书院遗址之图文江右书院行族谱中关于明经书院的记载明经书院残留石墩\n\n含珠书院含珠书院潜盖里铅山是个人杰地灵、物华天宝的文化之乡。自宋朝以来素有“隔河两宰相，百里三状元，一门九进士”的美誉。含珠书院就是隔河两宰相孕育之地。含珠书院，坐落在河口镇柴家埠的横林村南的一处幽静树林山坡上，院域面积广阔，达逾千亩之境。由三进庭舍、二口泉井、五处湖泊组成。在此入仕者除本族子孙，还有周边乡村的童生。相传铅山县费氏十分重视子孙后代的培养。',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',501,NULL,'2026-08-16 21:12:08'),(122,8,1,5,'由三进庭舍、二口泉井、五处湖泊组成。在此入仕者除本族子孙，还有周边乡村的童生。相传铅山县费氏十分重视子孙后代的培养。成化二十三年（1487）丁未科、年仅十九岁的费宏，一举考中进士第一。费氏家庭通过自办书院由科举而崛起，一跃成为新门第——“西江甲族”。费氏家族办家族书院，与历史上其他文化世家一样，都传承着一种家族文化和亲亲相授的风尚。父子叔侄兄弟为师友，相互激励，共赴考场，已在费氏一门形成了求学上进的风气。费氏的家学渊源根底，为世人所称道，历三百年而不衰。江右书院行正德十三年（1518）费宏出资扩建含珠书院，聘名儒主教，一时使书院名气大振。书院遗址处的古旧建筑\n\n嘉靖八年（1529），费宏再次扩建书院，并亲自为书院题匾“含珠书院”。万历年间，费氏第八代精英费尧年在当时县城永平镇东山书院内创办了一所景行书院，惠及乡里。费氏办学，从含珠书院到东岗书院、景行书院。建立起了一套自己自创的模式，有日常所需文化知识、“四书五经”、八股文章，景仰先贤，研习先哲学说，修身养性等整套程序，同时制定了七条规训：同居、均材、奉先、训后、惇礼、守法、尚义、内外兼修，规范人生。为此推出了一批又一批精英跻身科场，终于冠盖相望，',5,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',506,NULL,'2026-08-16 21:12:08'),(123,8,1,6,'了七条规训：同居、均材、奉先、训后、惇礼、守法、尚义、内外兼修，规范人生。为此推出了一批又一批精英跻身科场，终于冠盖相望，门楣振兴，家族升腾。遗址旧房侧门之图文江右书院行墨池燕闲讲学会东山位于鄱阳湖平原的余干县，不仅是“梦里水乡”，更有“理学名区”的雅誉。北宋吴孝宗在《余干县学记》中所描绘的繁盛情景，至今仍让人津津乐道：“古者江南不能与中土等，宋受天命，然后七闽、二浙与江之西东，冠带《诗》《书》……人才之盛，遂甲于天下。江南既为天下甲，而饶人喜事，又甲于江南。”好一个江南甲天下，饶州甲江南！在经济发达的同时，余干县还形成了重视文教的社会风气。“为父兄者，以其子与弟不文为咎；为母妻者，以其子与夫不学为辱。”明代更有“人文之盛甲江南”的美誉。赵汝愚的东山书院为余干文风文脉的培育，可谓功不可没，而东山书院又与理学大师朱熹的过化密不可分，东山书院也见证了赵汝愚与朱熹的深厚情谊！书院遗址处的书院介绍\n\n“东山书院”牌匾之图文江右书院行东山书院赋碑石东山书院位于余干县城冠山羊角峰，南宋淳熙五年（1178），由赵汝愚与从弟赵汝靓创建。赵汝愚（1140—1196），字子直，号东山，祖籍浙江嘉兴，是宋太宗八世孙。祖父',6,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:08'),(124,8,1,7,'东山书院位于余干县城冠山羊角峰，南宋淳熙五年（1178），由赵汝愚与从弟赵汝靓创建。赵汝愚（1140—1196），字子直，号东山，祖籍浙江嘉兴，是宋太宗八世孙。祖父赵不求监余干酒税，始居余干县城。他少有大志，以修齐治平为己任，常说：“丈夫得汗青一幅纸，始不负此生。”26岁时，考中进士第一名，成为宗室状元。朱熹讲学东山书院，余干及周边学子纷纷前来问学。在东山书院的西峰有一天然水池，池水渗自山崖，久旱不绝，冬夏不涸，名为“龙池”。朱熹在东山书院讲学期间，经常临池洗砚，并取池水磨墨作书，朱熹走后，学子们争相效仿，日久天长，竟然把一天然池水染黑，故后人称为“墨池”。墨池旁有碑，曰“朱子注《离骚》处”，至今遗撷翠门\n\n迹尚存。每当皓月当空，俯视池水，似有明月坠池，因此“龙池夜月”成为干越八景之一。在墨池旁筑有一亭，供朱熹取水时休息，取名为墨池亭。东山书院建成后，因有理学大师朱熹在此讲学，从而使书端明书院院文风深厚，培养了大批人才，余干的很多乡贤都出自东山书院。汝愚之子赵崇宪后来官至户部尚书，其从弟赵汝靓是宋代端明书院冰溪边著名的理学家，崇宪和崇度在《宋元学案》中都列入晦翁门人，',7,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',491,NULL,'2026-08-16 21:12:08'),(125,8,1,8,'汝愚之子赵崇宪后来官至户部尚书，其从弟赵汝靓是宋代端明书院冰溪边著名的理学家，崇宪和崇度在《宋元学案》中都列入晦翁门人，此外曹建、柴元裕、饶鲁等都是受书院熏陶培养的一批理学家。端明书院位于玉山县城南侧的武安山东麓，是南宋端明殿大学士玉山状元汪应辰当到明代更有理学大师胡居仁和张吉，余干也因此而成为理学名年讲学、生活的场所。后来人们为纪念汪应辰，便将其称作“端明书院”。区，有“人文之盛甲江南”之说。汪应辰是著名的南宋学者，从小师从于喻樗、张九成、吕本中、胡安图等，又与吕赵汝愚创建东山书院及邀请朱熹讲学，对余干县的教化之祖谦、张栻为友。在学术上，主张兼容并蓄，博采百家，不能有门墙之隔，要广泛吸收功，功不可没。东山书院也与信江书院、鹅湖书院、叠山书院不同学派的学术思想，“日以亲师取友、多识前言往行为事”。不论是对同辈还是晚辈，齐名，并称上饶四大书院。都抱着不耻下问的虚心态度，张栻曾赞汪应辰“苟片善之足取，必挽后而推前。”学者称“玉山先生”，创立了玉山学派，著有《文定集》二十四卷，为《四库全书》收录。《广信府志》评价他：“广信之在南宋，以文章显者，曰汪文定公；以志操著者，曰谢东山书院门匾之图文江右书院行',8,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:08'),(126,8,1,9,'《广信府志》评价他：“广信之在南宋，以文章显者，曰汪文定公；以志操著者，曰谢东山书院门匾之图文江右书院行书院旧址古亭书院全景\n\n文节公。”将他与谢叠山相提并论，成为南宋广信府两大先贤之一。汪应辰“好贤乐善，出于天性，尤笃友爱”。他回到玉山故里，购置田地，设置书堂，潜心于性命之学，以修身讲学为事，广收弟子，培育后人，他亲自主讲、宣传他的理学思想和道德学说，许多学者纷纷慕名而来。后来人们便将他起居讲学书院文保单位牌之所，称作端明书院。端明书院成立后便命运坎坷，因战乱几度被毁。经历一百年多的风雨侵蚀，书院的部分建筑依旧保存至今，现存的旧址有书院的先贤祠，里面供奉着朱熹、汪应辰以及当时到端明书院讲学的名士学者。穿过鹅卵石铺成的小道，就是当时授课的讲堂。讲堂不远处的一口八角古井，水质仍旧甘甜，村民还在饮用。修建书院时种下的一棵大樟树，依旧枝繁叶茂，但书院已听不到以往老师的训导，没有昔日学子的琅琅书声，显得苍凉而荒寂。抚州书院江右书院行书院侧景\n\n仰山书院仰山书院皓月光再没有谁比我更熟悉仰山书院了。这个大清乾隆二年（1737）始建的书院，作为古代金溪县“培育人才之区”，一直',8,'null','{\"page_end\": 10, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',488,NULL,'2026-08-16 21:12:08'),(127,8,1,10,'再没有谁比我更熟悉仰山书院了。这个大清乾隆二年（1737）始建的书院，作为古代金溪县“培育人才之区”，一直延续到光绪末年停止科举考试，其山长或老师换过一茬又一茬，还没有谁呆过17年吧？书院内景我在书院工作了17年。从清末、民国直到解放后，仰山书院作过各种用途，办过学堂，办过民众教育馆，解放初金溪县人民政府甚至就设立在这里，后来又成为某些单位的宿舍、民居。仰山书院原貌保存下来，1999年被批准为江西省文物保护单位。近些年文化投入增大，书院得到了彻底修缮，已经成为了千年古县金溪的一个文化窗口、一张靓丽的历史名片。同治《金溪县志》卷十二“书院”载：仰山书院在学岭右。乾隆二年，知县阎廷佶倡捐买桂氏房屋改为义学，三十五年知之图文江右书院行陆九渊铜像县杨唐佑倡建讲堂三楹，工未竣调去。嘉庆二十年知县万国荣会同儒学倡率邑中善士李庭藻等，撤旧更新，创屋四十余楹，教谕干廷熊、训导李秋芳详请学使江西学政王鼎赠以额，并且为之记。其费出邑人公捐。除修书院外，余存钱文、田亩、店屋、岁收租息以赡束修（教师工资）膏火之用。道光元年知县杨献弼定有章程，通详各宪。仰山书院坐落在金溪老街一条巷子里，书院门额“仰山书院”',10,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',498,NULL,'2026-08-16 21:12:08'),(128,8,1,11,'息以赡束修（教师工资）膏火之用。道光元年知县杨献弼定有章程，通详各宪。仰山书院坐落在金溪老街一条巷子里，书院门额“仰山书院”四字是清代名臣王鼎于嘉庆二十年任江西学政时所手书。每当看到它那方饱经风霜的清水外墙，毫不张扬的青瓦檐廊时，一种淡雅、内敛、和平、协调的美感就在我心中油然而生。多数人不经意地走过，只有当它前面的场子上停满小车时，才有点惊讶——这里仰山书院大门\n\n书院牌匾陆九渊纪念馆有什么好看？我庆幸自己在它身边学习了17年，所以我能品味与享受这里特有的宁静与儒雅，揣摩与领会诞生了心学大儒的金溪地域的文化性格。想当年，多少学子，点着金溪的青油灯，读着金溪刻本“四书五经”或“象山语录”，接续象山先生“轩昂奋发”“六江右书院行经注我”的人文基因。今人面对这座仰山书院，是不是可以停下匆匆求名求利的脚步，多想一想呢？我最爱书院的月色，在关闭了山门的空寂的庭院里，我仰望星斗，书香缥缈，遗韵如月，月光如水，我心如水。我平和地享受着这份孤独，让自己与象山先生隔空相望。“江上何人初见月，江月何时初照人？”我不知道，但我分明感受到了月光里自然的慈悲与天地的悠长。有人认为中国可以恢复书院制度，我很赞成曾经看到某文章中',10,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:08'),(129,8,1,12,'但我分明感受到了月光里自然的慈悲与天地的悠长。有人认为中国可以恢复书院制度，我很赞成曾经看到某文章中的一句话：一瓶陈酒倒光了，就只有余香没有酒了，再装新酒有什么意义？留着这种余香不是更好吗？书院一角\n\n兴鲁书院兴鲁书院曾巩贤兴鲁书院为北宋著名文学家曾巩所办。曾巩祖籍山东（山东简称鲁），其先祖是孔子的得意门生曾参，“兴鲁”一词也由此得来，意在“兴五帝三王之道”“上承曾子之家学，六中内兴鲁书院简介以继周公孔子之传者”。据史料记载，兴鲁书院坐北朝南，规模宏大，房屋错落有致，内设讲堂学馆、彩亭后院，其间名花异草，绿树掩映。明清两代，兴鲁书院是抚州6县（临川、崇仁、宜黄、乐安、金溪、东乡）的讲学之所，为本地培育出了大批人才，如声名远播的明代戏曲家———汤显祖。如今的抚州一中，前身就是从兴鲁书院迁出去的抚郡中学堂。兴鲁书院，名为兴鲁，实则兴了抚州，造就了临川 “才子之乡”的美名。每念及此，顿感心中有愧。我生自临川，却没有承袭到“才子”之气，真正的才子可是如数家珍，像邓从豪、丁渝、萧涤非、吴自强……他们虽没有在曾巩座下聆听教诲，也没有在兴鲁之图文书院正襟研学，他们秉承的是“力学以求之，深思以索之，使知其要，识其微”（曾巩',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:08'),(130,8,1,13,'像邓从豪、丁渝、萧涤非、吴自强……他们虽没有在曾巩座下聆听教诲，也没有在兴鲁之图文书院正襟研学，他们秉承的是“力学以求之，深思以索之，使知其要，识其微”（曾巩江右书院行治学观）的读书理念，承袭的是抚州优良的学风。我们以邓从豪、丁渝等为傲，更以有书院残房一角书院创始人曾巩生平\n\n曾巩这样的学者和他所创办的兴鲁书院为荣。后人崇敬曾巩，喜爱兴鲁书院，为保存兴鲁书院这一瑰宝，做了诸多的努雯峰书院力。据记载，1740年，抚州知府刘永锡重修了兴鲁书院，还远请清代名臣、雯峰书院记莲乡理学家李绂担任书院山长；1781年，抚州知府陈朗为纪念曾巩、鼓励学子，雯峰书院位于莲乡广昌的甘竹镇龙溪村饶家堡，为明代史学家、教育家饶秉鉴（号在书院讲堂旁建造了一座梦欧亭；1882雯峰）于成化六年（1470）所建，是明代中叶江西影响较大的书院之一，现为市级文物年，抚州知府郑祖琛、临川知县刘绳武保护单位。雯峰书院占地5032平方米，飞檐翘脊，高墙深院，分上、中、下三厅，有等人又捐资重修兴鲁书院；1901年，读书号房56间、大小庭院3处，院中有院，园中有园，有池有楼。整栋建筑古朴典雅，抚州知府何刚德遵照清廷书院改学舍诏',12,'null','{\"page_end\": 13, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',497,NULL,'2026-08-16 21:12:08'),(131,8,1,14,'读书号房56间、大小庭院3处，院中有院，园中有园，有池有楼。整栋建筑古朴典雅，抚州知府何刚德遵照清廷书院改学舍诏山水楼轩相映，犹如一件精美的建筑文化瑰宝，展示着精妙高深的古代建筑文化。尽管令，将兴鲁书院改名为抚郡中学堂。而一样青砖黑瓦，一样木梁列架，匾额和墨迹的创意及内涵，却昭示出古人书法、构思之今，兴鲁书院正在重新散发着它的魅力，高妙。明代教育家、状元罗伦经常寓居于此，找寻田园生活的情趣，也不忘授课讲学，耳畔又能响起琅琅的读书声，临川区实并为后人留下了传世佳作《雯峰别墅记》。抗战时期，陈鹤琴率国立幼稚师范学校迁此验小学和临川区第六中学正延续着兴鲁办学。如今，雯峰书院内的墙壁上，仍保存有当年国立幼稚师范学校公布的升学录取红榜。临川六中校门，兴鲁书院旧址所在地书院的生命。雯峰书院所在的龙溪村，村民大多姓饶，村如其名，藏龙卧虎，自古贤人辈出，人书院的记忆是不应该抹去的，此番杰地灵。出土过“中华之最”恐龙化石，是以发现目前长江以南惟一保存完整的恐龙化之图文的离开不是记忆的结束，而是记忆的开江右书院行始与追寻。书院全景书院残房\n\n石而闻名的村庄。引起了中国科学院古脊椎动物与古人类研究所极大的关注，专家建议在龙',13,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',508,NULL,'2026-08-16 21:12:08'),(132,8,1,15,'始与追寻。书院全景书院残房\n\n石而闻名的村庄。引起了中国科学院古脊椎动物与古人类研究所极大的关注，专家建议在龙溪村建立“恐龙地质公园”。龙溪村内还有元代石拱跃龙桥、明代雯峰墓、鹤林寺和清代大夫第，均为“一地胜迹”。有关专家呼吁，为传承先人厚德载物的文化财书院厅堂富，将这些文物保护单位连为一体，综合开发，书院大门建成一个独具特色的旅游文化区。之图文江右书院行书院雀替书院门当书院山墙',13,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',191,NULL,'2026-08-16 21:12:08'),(133,9,1,0,'书院里的有些建筑材料据说是从苏州漕运过来的。由于时代久远，缺乏修葺，整个书院已是破旧不堪。斑驳陈旧的门墙匾额上“应宿第”应宿第书院三字，苍劲有力。大门上有过年时贴的春联，两扇木门，一院之户。追忆东坑“应宿第”入此门，顽愚变文质，邋遢改文彬，做作化坦荡，无知进有知，傲气成东坑村又叫东川陈家村，村民全部姓陈，是江西省乐安县鳌溪镇一个池塘众多、以随和，懵懂化睿智。带路的校长说，明清民居胜出的村子。东坑整个村子坐北朝南，村子前半部分，几口大水塘如几面明镜，这样的建筑遗存在偏远的山村极为四周青山和古色古香的建筑倒映其中。往村中行走，明清时期的民居错落有致，我们在罕见，这是东坑丰厚的文化底蕴和村子里寻找到了保存尚好的书院有思南书屋、如兰书院和应宿第等，还有几个不知名字崇尚才学的一个有力佐证。“应宿的书院散落在民居当中，而东坑鼎鼎有名的道山书院难寻其故迹。如兰书院在村后山脚第”大门前，有一座牌坊，据说是下，依山而建，墙体夯土而成；小巧的思南书屋坐落在村中池塘边上，因其前门朝南，皇上为表彰村里乐施好善的陈姓人正对水塘，人们只能从后门出入，后门即是北面，所以取名“思南书屋”。家而建。从前，乐安县交通闭塞，',1,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',501,NULL,'2026-08-16 21:12:09'),(134,9,1,1,'皇上为表彰村里乐施好善的陈姓人正对水塘，人们只能从后门出入，后门即是北面，所以取名“思南书屋”。家而建。从前，乐安县交通闭塞，我们一行来到“应宿第”前，映入眼帘的是门前疯长的杂草。“应宿第”虽然破东坑是乐安县城与外界来往的重要败，但风貌依存，高高的风火墙头上，“勤奋求学、步步高升、加官进爵”等图案清晰交通枢纽。那时不论平民百姓、商可见。推开陈旧的木门，跨过高高的门槛，见到的是深深的厅堂，祖位神龛依原样保存。书院檐角贾显贵、贩夫走卒、赶考书生还是之图文要饭的乞丐，只要路过东坑，就可以在此吃饱饭睡好觉，再去赶路，当时东坑陈氏村民江右书院行淳朴厚道可见一斑。书院门楼书院全景\n\n怀仁书院怀仁书院竹桥畔怀仁书院牌匾怀仁书院坐落于江西省金溪县的竹桥古村。众多学子、名士和商人。民国时期，金溪籍中国工农红军和八路军高级指挥员、晋察冀竹桥村位于金溪县城北约十公里，始建于元末明初，已有近千年历史，古代金溪至军区四分区司令员、赣东北根据地和中国工农红军第十军的创始人之一、军长周建屏曾东乡大路挨村而过。现保存完好的明、清古建筑有109幢，村中总门及上、中、下三门在怀仁书院开会议事，使书院成为江西红色书院之一。',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',500,NULL,'2026-08-16 21:12:09'),(135,9,1,2,'现保存完好的明、清古建筑有109幢，村中总门及上、中、下三门在怀仁书院开会议事，使书院成为江西红色书院之一。楼各有特色，七口水塘都有排水沟相通，井然有序，典型古建筑含“总门”“谏草传芳门”“芝兰启秀第”“文林第”“文隆公祠”“步云公祠”“镇川公祠”“仲和公祠”“怀仁书院”“养正山房”等十处，青砖灰瓦，飞檐翘脊，格局完整。镇川公祠前有清代四库全书副总裁曹地山的题额石刻“对云”，充分显示了竹桥村深厚的文化积淀，也是抚州市第二批市级文物保护单位。怀仁书院建在村子的中部，占地260平方米。据竹桥余氏族谱记载，乾隆五十八年（1793），由余步云的后人修建步云公祠时一并完工，书院为竹桥村及周边村落培养了之图文江右书院行书院全景图怀仁书院正门书院厅堂\n\n门坊上青砖红石上多雕刻有龙凤呈祥、鲤跃龙门等花卉鸟兽图案，南面墙体上石刻问渠书院阴文“问渠书院”四个楷书大字，书院内问渠书院后畬宅装饰质朴无华。书院前后共设有五个门楣，问渠书院位于江西省东乡县的黎圩镇后畲村。除大门外，周边门楣东乡县位于江西省东部，始建于明正德七年（1512），自古钟灵毓秀，人杰地灵，均为半圆型，门楣上书院内景',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',488,NULL,'2026-08-16 21:12:09'),(136,9,1,3,'东乡县位于江西省东部，始建于明正德七年（1512），自古钟灵毓秀，人杰地灵，均为半圆型，门楣上书院内景孕育了北宋杰出的政治家、改革家、文学家王安石、明朝开科状元吴伯宗、晚明“四大用红石刻成匾额“桂才子”之首艾南英、清代著名诗人吴嵩梁以及“舒体字”创始者、著名书法家舒同等名人。园”“兰室”等字样。书院与民居之间有精致的长廊。黎圩镇是王安石的故乡，后畲是王安石弟王安上的后裔村，是从黎圩镇浯溪村迁来的。根据当地村民介绍，书院是清代中期王氏先祖弃官还乡时创建。初创时为王氏家族问渠书院建在后畲村中一水塘旁，占地面积2000余平方米，建筑面积1200余平自办的学堂，专供族中子弟就学，后因教学质量高，逐渐衍变成为一所地方性的学校，方米，坐北朝南，大门开在东面，南面环水，西面是田野，为四合院式天井院建筑，斗不再只是王姓的家族学堂，邻里乡亲也都捐钱、粮和田地资助问渠书院，同时将自己的砖封火马头墙，单进厅，穿斗式构架。天井两侧建廊楼，堂房地面高出天井和廊楼地面。子弟送入问渠书院就读。200多年来，书院为村里培养了许多人才，后畲在乾隆七年、十三年分别考取了王廷枢、王定符两名进士。解放后，书院作为村小的前身，仍然是教',3,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',504,NULL,'2026-08-16 21:12:09'),(137,9,1,4,'200多年来，书院为村里培养了许多人才，后畲在乾隆七年、十三年分别考取了王廷枢、王定符两名进士。解放后，书院作为村小的前身，仍然是教书育人的场所，一直到村小有了新的教学大楼。之图文江右书院行问渠书院全景问渠书院牌匾\n\n流坑文馆流坑文馆入贤坊流坑文馆位于乐安县牛田镇流坑村北陌兰洲大宗祠之西，始建于明初，为抚州市市级文物保护单位。流坑村距乐安县城38公里，五代南唐升元年间（937-942）开始建村，至今已有一千多年的历史。全村大都姓董，尊西汉儒学家董仲舒为始祖，实际可考的开基祖为南唐时的董合，是一个拥有相当多土地的庶族地主。其第三代董文广兴教办学，培育子弟，因而在明代科举昌盛，人才辈出。全村共有进士33名，文武状元各一。全村获举人与相当于举人功名的约100人，任知县以上官员的超过50人，最高的官员为参知政事。泮池至明代中叶，村子经其二十二代刑部郎中董燧的改建治理，规范整齐，井然有序，至今仍大体保持原貌。全村现有明清住宅260余栋，祠堂50座，宫观庙宇8处，文馆、戏台各1座。它之图文江右书院行讲堂们清一色的青砖灰瓦，朴实素雅。高峻的马头墙，仰天昂起。雕刻、彩绘，都很精致细腻，令人赏心悦目。',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',499,NULL,'2026-08-16 21:12:09'),(138,9,1,5,'江右书院行讲堂们清一色的青砖灰瓦，朴实素雅。高峻的马头墙，仰天昂起。雕刻、彩绘，都很精致细腻，令人赏心悦目。数以百计的屋宇，堂上有匾，门旁有联。联匾皆有来历，内涵丰富，意境深远，且多出自名家之手。宋代朱熹、明代杨士奇、金幼孜、罗洪先、曾同亨、清代董士标、刘绎等，均有联匾留传。文馆又称江都书院，是至今流坑村保存最大、最完好、最古老的一座书院，建于明文馆全景\n\n敕书楼道源堂楼上为“文昌阁”，上悬“日进高明”匾。“文昌阁”是文人览阅与雅会之所，其东侧代晚期，为流坑董氏一族所立。坐北朝南，前带庭院，西连藏书楼，主体为三进式砖木辟门设梯与敕书楼（藏书处）相通。藏书楼的下层为一小厅堂，其前置一小花园，园前结构的硬山式建筑，集读书、讲学、祀祖、敬贤、藏书多种功能于一体。墙两侧辟有漏窗，中有“瞻之在前”四个草书字，园中栽花植桂（寓“蟾宫折桂”之意），文馆的庭院位于前墙正中门, 上有“儒林发藻”四个行书大字。院内以花岗岩条石暗香四溢，环境雅洁清新，是文人小憩、漫谈的好场所。铺地，在其东、西两侧石砌对称的长方形泮池，中间有一单拱纵向石构步桥跨池而过，江右书院行登三级台阶至主体建筑的门廊。首进包括下堂和前天井。',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',502,NULL,'2026-08-16 21:12:09'),(139,9,1,6,'铺地，在其东、西两侧石砌对称的长方形泮池，中间有一单拱纵向石构步桥跨池而过，江右书院行登三级台阶至主体建筑的门廊。首进包括下堂和前天井。下堂两侧各置一房，瓶式门，据说是供先生课间休息的地方。前天井以条石砌铺成“回”字形，其两侧面对天井，分别以木质槅扇拦成三间耳室，做学子们的书房。第二进包括中堂和后天井。中堂为先生讲坛，后天井的西侧辟有一门与藏书楼相通。第三进为面积较大的上堂，是供奉西汉大儒董仲舒等祖先、名臣、乡贤的神圣之地，庄严肃穆。上堂顶上，建有敕书楼。文馆重工装修在上堂，其顶部、檐宇、梁枋等处均为精美的雕刻、彩绘与墨书装饰。顶棚天花以冷色海藻纹为底，以红、绿彩勾填出花卉、八宝，并相间作出石榴形、扇面形的开光，中为山水、花鸟及书写的名人诗句; 藻井周边为透雕窗花图案，顶部分六区，透雕成变形的荷叶宝瓶纹，均为暖色基调，鲜艳华丽。神奇的是多少年来藻井从未打扫，仍清爽无尘，色泽明朗。对此有如下说法：其一，制作藻井的材料能散发出特殊的气味，加上图形色彩斑谰，使虫、鸟闻（望）而却步，不敢光顾，故既无蜘蛛结网，飞虫停歇，也无燕雀筑巢; 其二，藻井的南向有略低于藻井的天井檐宇，南低北高两檐形成了一个正',5,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',502,NULL,'2026-08-16 21:12:09'),(140,9,1,7,'图形色彩斑谰，使虫、鸟闻（望）而却步，不敢光顾，故既无蜘蛛结网，飞虫停歇，也无燕雀筑巢; 其二，藻井的南向有略低于藻井的天井檐宇，南低北高两檐形成了一个正对藻井的风口，这样，南风吹来，风流直至藻井北围，并在藻井中回旋，有如清扫一般。文馆自下堂至上堂，地面逐渐升高，入其内须曲折迂回而进，这种平面设置，据说寓有学子们学业循序渐进、逐级登高之意。沿着后天井行至西侧端，穿门而过即至藏书楼。\n\n元猷书院如蘭书院书香东坑花如兰乐安县鳌溪镇的东坑村是一个书院密集的村庄，如兰书院、思南书屋、应宿弟等古代书院散落其中。如兰书院，坐落在村庄后边的半山坡上，建筑规模不大，朴实简洁，大门上横匾题字“如书院”四个字醒目大方，雄劲有力。如兰书院牌匾我站在书院的石阶上，听着远近山峰传来的缥缈风声。王谢堂前燕犹在，帝王将相已作古。沧桑世事，谁主浮沉？人的生命，与自然万物相比，真是渺若微尘。钟表上的时针是在慢慢地移动着的，移动得如此之慢，使你几乎感觉不到它的移动。人生岁月就是如此，一年又一年，到了某一天，蓦然一惊，就像眼前的破落书院，完成了它的历史使命，书院门楼之图文江右书院行不需张扬，不再光鲜，隐藏在峰林之中，漂浮在云水间。元猷书院诉兴衰',5,'null','{\"page_end\": 6, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:09'),(141,9,1,8,'此，一年又一年，到了某一天，蓦然一惊，就像眼前的破落书院，完成了它的历史使命，书院门楼之图文江右书院行不需张扬，不再光鲜，隐藏在峰林之中，漂浮在云水间。元猷书院诉兴衰元猷书院位于江西省乐安县万崇镇万坊村。该村是一个千年古村，村内古建筑众多。有二座高耸的古牌坊特别引人注目，一座是宋代的御史牌坊，一座就是元猷书院。元猷书院坐北向南，依着古祠而建。走近书院，牌坊上“元猷书院”四个大字还清晰可见。牌坊由石、砖建成，高挑的檐角，秀丽精巧的斗拱。牌坊上雕刻精美的五福祥云、锦鲤腾浪等仍然栩栩如生，牌坊门梁上方伸出的两个石狮威猛雄伟。进到书院，中间一个六米见方的天井，两边是宽大约五米的回廊；再往上，中间为厅堂，两边为东西厢房。整个书院东西对称，南北长约24米，东西宽约16米，面积近400平方米。书院建于公元1710年间，在其后的一百来年间，这所书院里陆陆续续考取功名者多达100多人，为当时社会的发展与繁荣起了积极的作用。至19世纪末，由于清朝腐败，民不聊生，元猷书院也逐步走向衰落。现在的元猷书院经历了300多年的风雨侵蚀，后面的回廊、大厅和厢房于文革其间就已倒塌，唯有前面的牌坊依然矗立在风中。',6,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',496,NULL,'2026-08-16 21:12:09'),(142,9,1,9,'现在的元猷书院经历了300多年的风雨侵蚀，后面的回廊、大厅和厢房于文革其间就已倒塌，唯有前面的牌坊依然矗立在风中。牌坊上精美的图画及斑驳的痕迹向世人诉说着历史的兴衰。如兰书院遗存建筑\n\n门楼特写盱江书院盱江书院话李觏抚州境内有一条著名的河，古称“汝水”，为江西省第二大河流，发源于广昌县驿前镇，流经广昌、南丰、南城、临川、进贤、南昌，在南昌市滕王阁附近汇入赣江，总长约400千米。而这条河有两个名字，广昌至南城段称“盱江”，南城以下则称“抚河”。李觏与盱江书院都与这条河有不解之缘。盱江书院在南城（古称建昌）县城北隅，始建于北宋庆历三年（1043），由有“盱江先生”之称的哲学家、教育家李觏所建。书院构造，中有明伦堂，前有洙泗堂，左右列诚意、正心、格物、致知四斋。当时书院，“教授自资”，属“民办”性质。同年，建昌军奉诏建立军学，知军事慎铖请李觏“出主学事”，聘为教授，主管军学教育，盱江书院也就由“民办”转“公办”了。明翰林修撰罗伦《建昌府重修泰伯先生墓记》载：“郡治北有凤凰冈，先生创书院其下，学者千余人”，这在当时算是规模很大的书院，也是江西古代书院史记载中能有“门徒千人”的三所书院之一。之图文',6,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',501,NULL,'2026-08-16 21:12:09'),(143,9,1,10,'“郡治北有凤凰冈，先生创书院其下，学者千余人”，这在当时算是规模很大的书院，也是江西古代书院史记载中能有“门徒千人”的三所书院之一。之图文李觏（1009-1059），字泰伯，号盱江先生，宋建昌军南城县人。一生贫而好学，登高公园大门\n\n李觏雕像纪念李觏的清代牌匾视富贵如浮云，安心草茅之中，教学授徒，研讨著述。著有《退居类稿》《皇祐续稿》等，后人纂集为《直讲李先生文集》或《盱江文集》。李觏当时创办的盱江书院，以学者讲学为主，对科举并不十分重视。对人的教化和教师的地位问题，李觏强调：“立人以善，立善以教”，要“教人成善，养善去恶”“学校不立，教法不行，人莫知何人可师，道莫知何道可学”“善之本在教，教之本在师”“师者所以制民命，其可以非其人哉”，故“择师不可不慎也”。书院不仅接纳本郡学子，而且接纳各郡府前来求学的“俊秀者”。李觏在盱江书院主事六年，学徒千数，培养了大量优秀人才，唐宋八大家之一的曾巩（南丰人）就是他的高足，曾任吏部、礼部、兵江右书院行部尚书、尚书左丞，积极辅佐王安石推行新法。颇有建树的邓润甫（南城人）也是盱江书院李觏的门生。此外，余畴若、邓立节、徐唐、李山甫等名儒都是李觏的弟子。盱江李觏纪念馆',7,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:09'),(144,9,1,11,'颇有建树的邓润甫（南城人）也是盱江书院李觏的门生。此外，余畴若、邓立节、徐唐、李山甫等名儒都是李觏的弟子。盱江李觏纪念馆\n\n书院成为当时东南学子闻风向往的著名书院。皇祐元年（1049），范仲淹向朝廷极力推荐李觏，次年，仁宗召李觏为太学直讲。李觏离开盱江书院后，盱江书院逐步成为培养本郡童生的场所，是建昌军、府的一所重点书院，具有广泛而深远的影响。宋代的盱江书院在“靖康之难”中被毁。此后800余年，盱江书院数毁数建，历经沧桑巨变，在20世纪50年代，还可以看见盱江书院的一点陈迹，后在城市建设中拆毁。之图文江右书院行李觏纪念馆全景\n\n2010年10月，南城县政府斥资397万元在书院原址附近的登高公园建设盱江书院仿古建筑群，内设李觏纪念馆，馆外立“盱江先生”——李觏塑像，给后人一个敬仰“盱江先生”、体验书院文化的地方。九江书院江右书院行《江西通志》中有关盱江书院的记载李觏纪念馆内有关盱江书院的评价\n\n鳌峰书院学子必经之门书院牌匾之图文遗址一角江右书院行鳌峰书院断残垣鳌峰书院在修水县义宁镇肖爷巷北。现在只剩下半堵破墙和一扇门，墙没有了任何遮挡，可喜的是“鳌峰书院”四个字还在。',8,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',490,NULL,'2026-08-16 21:12:09'),(145,9,1,12,'鳌峰书院在修水县义宁镇肖爷巷北。现在只剩下半堵破墙和一扇门，墙没有了任何遮挡，可喜的是“鳌峰书院”四个字还在。清同治八年（1869）修水县高乡众乡绅捐资兴建鳌峰书院，鳌峰书院当时兴盛修城，成为修水境内规模和影响较大的书院之一。在鳌峰书院的门口立了块“县级文物保护”的石碑。据县志记载，书院结构简朴，独具匠心，分为三重，下重左右各一个天井采光排水，中重有一大天井，站在大门口往里看，三个天井正好形成一个天然的“品”字。“品”凸显了鳌峰书院的特立个性，也体现了清贫乐道、品德为先的办学育人宗旨。鳌峰书院清末被改为高等小学。1942年，县立第一中心小学由农村迁回县城时，就设立在鳌峰书院。之后，由于学生人数增长，办学条件滞后无法改善等缘故，学校撤离了书院，鳌峰书院也结束了它遗址庭院成菜园的育人生涯。\n\n凤巘书院凤巘书院修水远在修水县城寻访凤巘书院时，曾有人告诉我说，秋收起义纪念馆就是原来的凤巘书院，其实秋收起义纪念馆对面的团部旧址才是凤巘书院。走进团部旧址，只见原先的厅堂上，摆放着一溜桌椅板凳，桌上放置阔嘴茶壶、土碗、马灯之类的，迎面的墙上悬挂着鲜艳的五星红旗，另两面墙上，绘着夺目红色箭头的大概是秋收起义作战地图吧。凤',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:09'),(146,9,1,13,'堂上，摆放着一溜桌椅板凳，桌上放置阔嘴茶壶、土碗、马灯之类的，迎面的墙上悬挂着鲜艳的五星红旗，另两面墙上，绘着夺目红色箭头的大概是秋收起义作战地图吧。凤巘书院是清末全县规模最大的书院，全县五十八乡一百三十六都均有学子就读于此，甚至毗邻修水的武宁、奉新、平江、通城、通山、崇阳等地亦有学子慕名而来。书院自创办始，培养了许多学有成就的人才。众多学子中，最著名的当是曾参与戊戌变法、被光书院内景绪帝倚为重臣的湖南巡抚桃里竹塅人陈宝箴。书院鼎盛时，塾师和书童达到1000余人，院宽20.5丈，长37.5丈，建清末书院改为义宁州高等小学堂，即今天义宁镇第一小学前身。“文革”期间，书院曾屋三重，中为讲堂，右为山长遭红卫兵打砸，损毁严重。评阅课讲卷之所，左为首事经县党办的一位朋友给我送来乡人龚良材编著的《溪山文稿》，终于从中查找到有关之图文理经费之所，前列书舍六十间，江右书院行凤巘书院的史料性文字。原文兹录于下：以“智、仁、圣、义、中、和”凤巘书院，位于州治北秀水门内，坐落在修水八景之一“凤巘朝阳”处（今县政府六字编号，为士子肄业之处，招待所所在地），清同治四年（1865）知州邓国恩倡集八乡本籍绅董按数捐费修建。书',12,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',505,NULL,'2026-08-16 21:12:09'),(147,9,1,14,'六字编号，为士子肄业之处，招待所所在地），清同治四年（1865）知州邓国恩倡集八乡本籍绅董按数捐费修建。书每岁十一月初四，八乡绅董会集一次，予聘名师，二月开课，仲冬停课。清末，奉诏改为义宁州高等小学堂，民国六年部分废，遗址曾为修水中学利用。“ 书院宽20.5丈，长37.5丈，建屋三重”，粗略计算一下，书院占地面积当在9000余平米；“书舍六十间”，以每间15张单人书桌计算，可容纳书童千余人。由此足见凤巘书院规模之大。书院内团部旧址牌匾书院遗址全景\n\n书院内景高峰书院高峰书院居高峰北宋初年，双井黄氏兄弟十人考取进士，时誉“十龙及第”。他们是黄沔、黄滋、黄湜、黄淳、黄涣、黄灏、黄浃、黄注、黄渭、黄浚。这十条名字带水的“龙”，都从杭山脚下的双井村走来。如果向他们打听“高峰”，他们的答案肯定是杭山。“黄文节（黄庭坚）所著诗书勃奥，乃得自山林秀气”，故倡建书院于杭山脚下，因书院背倚杭山，故名高峰书院。这个地方名叫明月湾，半圆形的地貌。弧形是修河，滋养着这里。直径是杭山，护佑着这里。而杭山主峰，就是圆心。其下，就是高峰书院。从记载看，高峰书院一直薪火不断，书声不绝。清朝以来仍有几次浴火重生。清同治年间，由乡人捐资重建。',12,'null','{\"page_end\": 13, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:09'),(148,9,1,15,'其下，就是高峰书院。从记载看，高峰书院一直薪火不断，书声不绝。清朝以来仍有几次浴火重生。清同治年间，由乡人捐资重建。续因兵荒又一度败落。光绪二十三年（1897）进行了一些大修整，后虽几经毁坏，总能得到及时修缮，至新中国建立时，院舍主体依然完好。高峰书院现在是一所小学，占地一千五百平米，上课的铃声依然响彻山村。这种以书院命名江右书院行的小学，全国不知还有没有第二所？学校以“承贤、启智、修身、报国”为校训，在国高峰书院全景\n\n家规定的课程外，还开设了国学、茶文化等特色课程。远看高峰书院，斗拱飞檐，气势恢宏，栩栩如生的“先同文书院师孔子行教像”镶嵌在高高门头的额顶上。据说这个雕像为万里车书尽同文书院初创时的原物，已经在风霜雨雪中行教了近千年。同文书院位于环城路九江二中校园内。走进高峰书院，廊曲庭表舅常带着我及其他小伙伴从他就读的九江二中后门溜进去，爬上小坡，便见美国闲，好不雅致，四合院的天井教会所建的儒励女子中学；下了坡，便到了美国教会修建的“同文书院”。书院坐西朝东，铺以青砖，植以花台，阳光与为三层西式小楼，钢筋水泥结构，周身涂亮黄，二层台阶上有三对不同风格的立柱。拱蜂蝶闪烁其中。回字型的四排',13,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',502,NULL,'2026-08-16 21:12:09'),(149,9,1,16,'为三层西式小楼，钢筋水泥结构，周身涂亮黄，二层台阶上有三对不同风格的立柱。拱蜂蝶闪烁其中。回字型的四排形门洞上方嵌着“同文书院”四字石刻，一层墙角有一块汉白玉铭文，上书“公元一九房子，为进士名录室、山长文○六年建”。表舅说，这栋同文书院楼，原来有四层高，内设教室和宿舍。可惜的是，化室、阅览室等办公用房和名由于白蚁的侵蚀拆掉了一层。之“伯、仲、叔、季……”的汉初灌婴曾在此筑城，西晋为盆口关，六朝时，称湓口或湓口城，称港为湓浦港。教室。在回廊里走一走，对联鸦片战争后，九江被外国列强辟为通商口岸，湓浦港成了英租界，那个“埠阆小学”就随处可见，如“乘山谷遗风，在这附近的土桥口，是美籍卫理公会传教士赫尔利和陶理于1867年创办的。博学笃行，诗派宏扬承大雅；之图文愿杭乡子弟，达才成德，文化江右书院行书院内走廊同文书院全景蔚起步先贤”，又如“双井连江湖孤灯听雨；一村关邦国仁者诵经”。黄庭坚雕像',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',395,NULL,'2026-08-16 21:12:09'),(150,10,1,0,'同文铭当时办的是小学、中学两级体制的学校，取校名为“九江同文书院”。为什么叫同文书院呢？那是参《中庸》中“普天之下，车同轨，书同文”之意，大金完颜亮的“万里车书尽混同”和“同文”表达的也是同等的意思。1905年，同文书院增设大学，取名为“九江南伟烈大学”，又称 “南伟烈书院”。九江南伟烈大学分预科、专科两类。我在这里读了小学、中学、大学。只可惜，1917年，因学校经济困难，创办了12年的南伟烈大学不得不停办，重新改为三三制的之图文完全中学，更名为“九江江右书院行同文中学”。1950年6月11日，人民政府正式接办同文中学，更名为“江西省立浔阳中学”。第二年，儒励女中与九江同文中学合并。1952年，又更名为“九江市第二中学”。政权更替，社会嬗变，我作为同文教书匠的身份一直未变。2001年，经九江市政府批准，“九江市二中”恢复使用原校名——九江市同文中学。2013年5月3日，同文书院荣登全国重点文物保护单位名录。同文书院门头同文书院承重柱\n\n云溪书院探访云溪书院行嘉靖皇帝赐匾现在的云溪书院是修水县路口乡路口村村民2001年捐款在原址新建的，一层，砖木结构。进大门是一个厅堂，左右两旁建两间偏房，之后是天井。',1,'null','{\"page_end\": 2, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:09'),(151,10,1,1,'现在的云溪书院是修水县路口乡路口村村民2001年捐款在原址新建的，一层，砖木结构。进大门是一个厅堂，左右两旁建两间偏房，之后是天井。天井两边有回廊联通第二重房宇，依然中间是堂屋，堂屋左右两边是房间。乍见以为是乡村人家，只是它毕竟不是乡村人家。第二重堂屋正中摆放的一块“云溪书院”牌匾可是大有来历，是由明嘉靖皇帝亲书，笔迹清瘦遒劲，颇见功力。云溪书院的创始人为丁云溪，路口小段人，曾任明礼部省祭大夫，在京为官14年，为侍奉百岁老父辞官归乡。回乡后，丁云溪动用私产建驺益书院，亲定课目，亲自授课，一时名闻乡里，慕名到书院求学的学童高峰时过百人。丁云溪去世后，乡人深切缅怀，改驺益书院为云溪书院，当地富庶人家捐钱捐粮，鼎力支持书院发展，历经明、清、民国而不衰，培育大批人才。科举期间的不说，就说之图文江右书院行云溪书院重修碑记民国期间，路口本土人氏、黄埔军校第一期军官雷德、修水大革命时期党的领导人物丁健亚都是在该书院接受启蒙教育，踏上人生征途。土地革命战争时期，红军队伍以书院为依托创办列宁小学；抗日战争时期，国民政府在云溪书院建设国民小学，履行教育救国宗旨。这一个偏远的书院，见证时代变迁，感受到历史脉搏的强劲跳动。',2,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:09'),(152,10,1,2,'为依托创办列宁小学；抗日战争时期，国民政府在云溪书院建设国民小学，履行教育救国宗旨。这一个偏远的书院，见证时代变迁，感受到历史脉搏的强劲跳动。斯人已去而风范长存，据丁氏家谱记载，丁云溪辞官归家时，朝廷赐五针松五棵、朝珠一串、朝笏一块、香炉一只，我向丁支书打听这些宝贵物品下落。他带我到书院隔壁的云溪殿，这是一座小型圣殿，殿堂正中设香案，香案上供奉着朝笏，香案前立着一个香炉。丁支书说 ：“这两件就是丁老先生留下的。为纪念他开书院启民智之功，清代乡人建云溪殿祭祀他。每到年节，附近村民翻山越岭来供奉香火，所许愿望没有不实现的。”我听了肃然起敬，面对神案行鞠躬礼。云溪书院全景\n\n柳山书院山门柳山书院柳山书院亦感怀柳山之于武宁，就如石钟山之于湖口，南山之于都昌，南崖之于修水，是古老县城近旁一座文化积淀深厚的山。相比较而言，柳山更为高大挺拔，更加峻峭秀丽罢了。汉唐时武宁古城西安和新县均在柳山脚下。唐天宝四年，武宁县城迁至修河北岸的玉枕山前，南望柳山二十余里。柘林水库建成后，武宁县城又迁修河南岸南市岭，与柳山又靠近了一步。地方志载，柳山原名飞来峰。县志上说，柳浑授浙江衢州司马时，弃官隐居此山，筑精舍读书。',2,'null','{\"page_end\": 3, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',502,NULL,'2026-08-16 21:12:09'),(153,10,1,3,'柘林水库建成后，武宁县城又迁修河南岸南市岭，与柳山又靠近了一步。地方志载，柳山原名飞来峰。县志上说，柳浑授浙江衢州司马时，弃官隐居此山，筑精舍读书。后征拜监察御史，官做到同中书门下平章事，封宜城伯，谥曰“贞”。后人就将此山改名为柳山。柳公修筑的精舍是他在此读书修道的所在，也成为这里最早的书院。宋绍兴年间，世居柳山之下的陈功显在柳浑精舍旧址建柳贞公祠，且辟讲肄称柳山书堂，后毁于兵乱。功显之孙陈时章重建，丞相章鉴作记。元代又毁。明成化间，知县江右书院行冯琦再建，并作记。其间屡废屡建。直至民国期间仍在柳公祠内设小学。后毁不复重建。柳山书院重修碑石\n\n东佳书院千年文脉思东佳义门陈氏七世孙陈崇于唐大顺元年（890）建书堂，东佳书院由原来只为本族提供教学的书堂，逐步形成 “兼亭台楼阁，耸延四方”的建筑群，是当时的江南三大书院之一，所藏书、帖“号天下第一”。从中国书院史角度看，东佳书堂是最早具备学田、教规的私办书院，比白鹿洞书院早半个世纪。曾任江州长史的陈崇针对族人的实际和教学特点，出资创建了宗族两级学校，低级的称书屋，高级的为书堂。除建有专用校舍，还置有学田，作为保障办学的固定经济来源。',3,'null','{\"page_end\": 4, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',495,NULL,'2026-08-16 21:12:09'),(154,10,1,4,'曾任江州长史的陈崇针对族人的实际和教学特点，出资创建了宗族两级学校，低级的称书屋，高级的为书堂。除建有专用校舍，还置有学田，作为保障办学的固定经济来源。书屋就是基础教育，供7-15岁的少儿入读，相当于现在的小学、初中；书堂近乎于现在的高中和大学。《五代史》《湘山野录》书里都给东佳书堂很高的史评：“江南名士皆肄业于其家。”东佳书院位于德安县城西北32公里（今德安县爱民乡岩泉桂村），是我国最早的之图文江右书院行东佳书院近景东佳书院远景书院之一。书院坐落在“群峦逶迤，起伏沧浪，泉流浩涌，飞瀑千丈”的东佳山下，这里环境清幽，风景秀丽，无车马之喧，无俗尘之染，是一个读书治学的佳处。历史文献大致呈现了东佳书院的原貌：书院入道口，立一门闾，全然竹构。约行里许，有石阍突出院墙。入院，院阁九幢，约三十间。其中，两幢傍西岭，三幢依南麓，四幢临东山。集贤院是主建筑，院内“堂庑数十间，冠垛丛立，甍榭参差”。此外，还有礼圣殿、衮公亭、师寓、讲堂、试堂、书楼、赏莲亭、寄咏舒、望云庵等建筑，布局精巧，错落有致。对此规模宏大、美轮美奂的建筑群，北宋学者钱若水赋诗赞道：“楼上落霞粘笔砚，池边怪石间松筠”“朱实垂庭红橘熟，清香袭座药畦春”。',4,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:09'),(155,10,1,5,'对此规模宏大、美轮美奂的建筑群，北宋学者钱若水赋诗赞道：“楼上落霞粘笔砚，池边怪石间松筠”“朱实垂庭红橘熟，清香袭座药畦春”。唐宋时期，从书院走出了18位朝官（其中有3人担任过宰相），29个地方官，55位进士，陈氏“八英九才子”“同榜三进士”在当时传为美谈。书院重视人伦教化，通过对家族子弟宗法伦理意识的培养，形成了“世守家法，孝谨不衰，闺门之内，肃如公门”的良好家风，使德安陈氏成为古代封建家族的典范。\n\n云物清丽，赞叹不已，说不愧是前辈道仙丁义、吴猛的故乡啊！于是，他披荆剪莽，在此营建房屋，祭祀吕洞宾以及丁义、吴猛诸位仙人，同时自己潜修静业，参悟大道。李致庵文武兼修，气度不凡，极爱读书，携带书籍近万卷，又懂得堪舆、医药之术。他凭藉自身修为，个人魅力，使得净明堂声名日著。于是净明堂四时香火鼎盛，往来香净明堂书院客游人，络绎不绝，文人云集，车马纷至。因此，有些好善乐施的富人，慷慨捐助，辟旷土为田，购业置产，时有水田20亩，山林百余亩，收入颇丰。遂大兴土木，建造篁山观。篁竹深处护讲筵净明堂书院还有一段耀眼的历史，那就是1943年初，武宁人刑肃夫在此创办了篁山学馆。设有三名教师，其中一名为武术教官。',4,'null','{\"page_end\": 5, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',503,NULL,'2026-08-16 21:12:09'),(156,10,1,6,'净明堂书院还有一段耀眼的历史，那就是1943年初，武宁人刑肃夫在此创办了篁山学馆。设有三名教师，其中一名为武术教官。招收了山里失学儿童和逃难到此的从武宁县杨洲乡南屏村张家湾屋场沿山溪溯源而上，踏入狭径，分开草丛，推开树枝，14-15岁少年50人。主要课程是国文、军事、美术、音乐等。为激励学子发奋雪耻，避开蛛网，步行约半小时，便至半山腰。翠竹掩映中，有一平坦处，矗立着一栋瓦盖土还根据岳飞曾填写的《满江红》曲牌创作了《篁山校歌》。1945年9月2日，日本投降，筑平房。这，便是当年的净明堂书院遗址。抗战结束，举国狂喜，篁山学馆的师生们也走出大山，参加庆祝活动。师生们纷纷返回净明堂最初是道教观院，又名篁山观，是南昌人李致庵营建的。他在明朝末年曾任家园，篁山学堂也完成了历史使命，随之解散。在此就学的少年后来有的参军成为解放先锋营都司。明朝灭亡后，他因爱慕道术，游历至武宁杨洲瓜源，看到当地溪壑幽窅，军指战员，有的参加抗美援朝战争，有的参加土改，有的继续学业，做了人民教师。篁山学馆虽然只办了两年多，但那是在抗战最困难的时期为无家可归的少年办的一所特殊学校。目的就是为了给之图文沦陷区培养抗日的种子，激起抗日救亡江右书院行',5,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:09'),(157,10,1,7,'是在抗战最困难的时期为无家可归的少年办的一所特殊学校。目的就是为了给之图文沦陷区培养抗日的种子，激起抗日救亡江右书院行的斗志和决心。岁月变迁，如今的净明堂书院，只剩下一栋普通的平房。残留的石碑，依然在讲述前尘往事。书院万卷藏书虽然羽化，但山中翠竹年年劲节凌云。有风吹过，竹林飒飒作响，似乎是当年书院的琅琅书声，一直传送到很远很远。净明堂书院\n\n长芗书院景德镇里读长芗长芗书院兴建于南宋庆元三年（1197），由景德镇监镇李齐愈“援白鹿例”提议创建。书院地址在景德镇市西，今禅师山一带，因其区域属长芗都，故名长芗书院。1974年在景德镇市郊一个元代墓中，出土了一件陪葬瓷器——青花釉里浮梁一中内七贤园红堆塑人物阁楼式谷仓，谷仓通高29景德镇书院厘米，背面底层正中以青花书写159字墓志铭：“夫人，故景德镇长芗书院山长凌颖山之孙女也。……”且有凌氏准确的生卒之图文年月。这件陪葬品成为我国目前仅见的有确切纪年的青花釉里红瓷器，也是元代中期景德镇瓷器的杰出代表作品，被列为中国第一批禁止出国展览的64件文物之一，现被江浮梁一中内七贤园碑铭，七贤曾为长芗书院先生\n\n长芗书院规划图长芗书院先生李椿年雕像长芗书院山门遗址之图文江右书院行',5,'null','{\"page_end\": 7, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',512,NULL,'2026-08-16 21:12:09'),(158,10,1,8,'浮梁一中内七贤园碑铭，七贤曾为长芗书院先生\n\n长芗书院规划图长芗书院先生李椿年雕像长芗书院山门遗址之图文江右书院行元代元贞三年长芗书院重修时留下的碑刻西省博物馆收藏，成为当之无愧的国宝。长芗书院为景德镇的学子提供了就学的机会，尤其是历任山长，尊崇理学，致力于程朱理学的普及与推广，促进了景德镇地方文化的普及、社会风气的改善和教化的昌明。书院文化与陶瓷文化一样，同属景德镇地方文化的一个有机整体。\n\n复礼书院复礼书院且复礼武功山南麓的复礼书院，坐落在赣西边陲莲花县暖水江畔的石城洞前，是一所古老的学府。它的建校历史可以追溯到明朝隆庆六年（1572）。它的第一任校长是明朝理学家、文学家、教育家刘元卿。复礼书院创办人刘元卿，号泸潇。这位从莲花坊楼南溪走出来的西江才俊，孜孜于理学，人称“正学先生”，曾经两次受到神宗皇帝的征聘，授“国子博士”“阶前承德郎”，官至礼部主事，因此又称刘聘君。刘元卿回到家乡南溪（当时属安福管辖），绝意功名，致力于治学著书，他奔走呼号，以自己的影响力带动武功山二十四姓创办书院，并将书院冠名为“复礼”。书院奉王阳萍乡书院明为先师，在正厅设立八条屏，镌刻王阳明的道德文章，要让世人回归先贤倡导的礼义上来。',6,'null','{\"page_end\": 8, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',512,NULL,'2026-08-16 21:12:09'),(159,10,1,9,'书院奉王阳萍乡书院明为先师，在正厅设立八条屏，镌刻王阳明的道德文章，要让世人回归先贤倡导的礼义上来。从此，刘元卿孜孜于正学的传播。之图文复礼中学，复礼书院旧址所在地\n\n历经近五百年的风雨沧桑，复礼书院早已面目全非，但王阳明的书匾流传下来了，他目光窎远，注视着今天与未来。巨大的鹅卵当年的明德堂旧址残存。在文化遭受钳制的封建时代，复礼书院几番改头换面，以神庙石块矗立花圃，以阴刻漆书大大的红字“礼”。的名义掩藏薪火的传递与儒学的传承。刘元卿创办的复礼书院，供奉四位儒学大如今，这里依然是传播思想与知识的殿堂，而且规模越办越大。这是刘元卿所想不师神位。最后，先生自己也被后人立牌祭祀。到的。复礼中学就设在明德堂前，一进大门便可以看见刘元卿儒雅高古、手不释卷的塑像。于是，四贤祠成为五贤祠。在乡民的心目中，刘元卿已经上升为一颗照耀夜空的星辰。刘元卿倡导的一个“礼”字，提纲挈领，代表忠信与礼义，可以定亲疏，决嫌疑，别同异，明是非。民国以来，书院演变为新式教育学堂。1945年，出身于湖上江背的科学家李鸣冈在书院的基础上创办“私立复礼中学”。“复礼”一名，沿用至今，代有传人，这也是奇迹。复礼书院旧址之图文江右书院行书院模型原书院布局',8,'null','{\"page_end\": 9, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',513,NULL,'2026-08-16 21:12:09'),(160,10,1,10,'书院的基础上创办“私立复礼中学”。“复礼”一名，沿用至今，代有传人，这也是奇迹。复礼书院旧址之图文江右书院行书院模型原书院布局刘元卿雕像\n\n龙溪书院信江侧畔会龙溪冬日，寒雨溯风，我驾车沿信江北去，一路寻访，来到岗底李家。这里就是余江县龙溪书院所在地，信江从遥远的武夷山流来，滔滔江水，横无涯际。绕过丛林山路，绕过溪流小桥，突显于眼前的是一片清丽的原野，在硕大的古樟树前，古老而庄严的龙溪书院，像一位守候历史的老人，伫立在冬季的寒风之中，等待着我们这些远方客人的造访。村民们把我领进了书院，有一个老者，祖辈三代都曾读过书院，他娓娓向我讲述了书院的往事。龙溪书院距离锦江镇约五公里，坐落在群山环抱、山清水秀的云盖峰山下，是清朝鹰潭书院乾隆癸未年（1763年）安仁举人李尚宗在江浙就任左堂告老返乡后领族人所建。书院占地约500平方米，正房一连三进，砖木梁架结构，进深26米，宽23米，高6米，内立之图文书院门楼\n\n随着老者的讲述，我的目光跨越250多年的历史，重新审视眼前的龙溪书院：书院门楼历经岁月沧桑依然挺立，十分雄伟，门牌楼上的字迹已经剥落，模糊，无法辨识。原先精美的雕画历经二百年多年的日晒风吹雨蚀，斑驳脱落了大半，已无',9,'null','{\"page_end\": 11, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',511,NULL,'2026-08-16 21:12:09'),(161,10,1,11,'楼上的字迹已经剥落，模糊，无法辨识。原先精美的雕画历经二百年多年的日晒风吹雨蚀，斑驳脱落了大半，已无法再现当年风华。从大门走进去，里面的大堂、天井、厢房等，格局虽算完整，但残垣断壁，梁腐墙歪，天井青苔厚，窗台草茎狂，门框尘土堆，檐破四漏风。牌楼旁高大的芭蕉早被初冬的霜雨打落得一片破败，几个孤零零的石盂在冬日里独守着书院的大门，一块不锈钢的文物保护单位的牌子被冬雨打得滴答作响，与古老的书院相伴……门楼特写书院天井之图文江右书院行门楼上文保单位牌匾九十九根木柱，中设讲堂，左右分立窗舍，有学舍十余间。大门为牌坊式“八字”门楼建筑，门楼青麻石结构，上下三层，呈塔形，翘起的沟檐，镂空的雕刻与栩栩如生的戏曲人物图案融为一体，展现了古代精美的建筑艺术和高超的建筑水平。清大文学家、戏曲家蒋士铨曾为之撰写《龙溪书院记》，描绘了书院当时的盛况。解放后书院成为团黄小学的校舍，直到上世纪的90年代初。书院内景\n\n寒风中，我伫立在龙溪书院门口，再次打量这个古老的书院，心情很是复杂，很是沉重，很是悲戚。觉得它就像一个被历史遗忘、被时代遗弃的老人，在寒风中挣扎和呻吟……好在当我抬眼远望，在古樟树的掩映下，一座崭新的学校拔地而起，宽阔明亮的教',11,'null','{\"page_end\": 12, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',513,NULL,'2026-08-16 21:12:09'),(162,10,1,12,'觉得它就像一个被历史遗忘、被时代遗弃的老人，在寒风中挣扎和呻吟……好在当我抬眼远望，在古樟树的掩映下，一座崭新的学校拔地而起，宽阔明亮的教室和平坦硬化的球场，让我紧戚着的心情舒爽了许多。后记千年书院话沧桑之图文江右书院行浩浩苍穹之下，莽莽林野之中，那一座座古朴而散落的书院，像是一尊尊历史的雕塑，守望在丛林山野或溪泉河畔。也许，倾覆剥落的墙垣失去了往昔的风采；也许，空寞寥寂的院落远不比梵宇的香火与虔诚的朝觐，独守一隅，孤伴一溪，似一个个思考的老人，与岁月和时代渐渐远去，与往事和历史渐渐淡去。但，南方江右之地，北去浪淘之江，那不管是薪火相传还是堙没于草野的书院，都有一段段历史，都有一个个传奇，都有一部部故事。江西书院众多，远不止笔触所能指，据不完全统计，迄今为止有史可查的书院有一千二百多所。然而，在浩如烟海的沉浮中，在长恨如歌的历史长河中，废毁拆弃，到如今仅存有六十多所，而重建复建之十余所，尚有遗存，但已破败的二十余所，余者仅有些遗址遗迹罢了。考录之，不免有些许扼腕之叹……好在历代传承人士，矢志不移，葺修不辍，使书院文化一直维系和传载。时至今日，虽散失大部，仍尚有遗存，也是值得庆幸之事。',12,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',499,NULL,'2026-08-16 21:12:09'),(163,10,1,13,'好在历代传承人士，矢志不移，葺修不辍，使书院文化一直维系和传载。时至今日，虽散失大部，仍尚有遗存，也是值得庆幸之事。只是，时不我待，必须加强保护，加快修复，这是时代赋予我们的责任和担当。书院内景二\n\n我们有责任让历史在这里而定格，让传说在这里而铭记，让书院文化从这而传承到的设立是书院与理学结合的标志。永远……“尊德性”与“道问学”的鹅湖之会。南宋淳熙二年（1175），朱熹、吕祖谦、陆我想，无论是一种文化抑或是一段历史，只有真正传承到了你的心底，那才能挥之九龄、陆九渊等人会讲于铅山鹅湖寺，讨论“尊德性”与“道问学”及无极而太极等问不去，那才是永久的栖地——题，朱陆“相与讲其所闻之学”，各持己见，不合而罢，史称“鹅湖之会”。因著名的“鹅让我们记住这些人物：湖之会”而兴起的鹅湖书院是我国古代不同学派争鸣互辩、君子和而不同精神的写照。胡仲尧，拓建华林书院，集书万卷，一时云游者常数千人。韩愈，兴办书院，释解昭告天下通规的《白鹿洞书院揭示》。南宋淳熙六年，朱熹知南康军，不遗余力兴奴婢，写下“莫以宜春远，江山多胜游”佳句。周敦颐，北宋敦祐六年创濂溪书堂，倡',12,'null','{\"page_end\": 13, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',478,NULL,'2026-08-16 21:12:09'),(164,10,1,14,'南宋淳熙六年，朱熹知南康军，不遗余力兴奴婢，写下“莫以宜春远，江山多胜游”佳句。周敦颐，北宋敦祐六年创濂溪书堂，倡复“莽为榛墟”的白鹿洞书院，他身兼洞主，亲订《白鹿洞书院揭示》，书院为之大盛。“出淤泥而不染，濯清涟而不妖”之说，公认理学鼻祖。曾巩，与曾肇等并称“南丰七《白鹿洞书院揭示》经宋理宗颁赐天下，成为天下学宫书院之通规。白鹿洞因之被称为“天曾”，创办兴鲁书院，意在“兴五帝三王之道”。朱熹，理学集大成者，世称“考亭学下书院之首”“海内书院第一”，是中国书院文化最杰出的代表。派”，辑定《大学》《中庸》《论语》《孟子》四书，淳熙六年兴复白鹿洞书院，亲订《白象山精舍与赣学的兴起。南宋时期大儒陆九渊应门生彭世昌之请结庐应天山讲学，鹿洞书院揭示》，使之成为天下书院之通规。陆九渊，宋明两代“心学”的开山之祖，陆九渊“登而乐之，乃建精舍”，陆门弟子“结庐而居”“裹粮相迎”“相与讲习”，与朱熹齐名，而见解多不合，主“心即理”说。江万里，是南宋末年士林和文坛领袖，前后五年达数千人。象山精舍后迁至贵溪县城外三峰山之徐岩，宋理宗为之赐额，成为创办白鹭洲书院，一生为官清廉，政绩斐然，直言敢谏，忧国忧民。吴澄，潜心著述，',13,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',507,NULL,'2026-08-16 21:12:09'),(165,10,1,15,'象山精舍后迁至贵溪县城外三峰山之徐岩，宋理宗为之赐额，成为创办白鹭洲书院，一生为官清廉，政绩斐然，直言敢谏，忧国忧民。吴澄，潜心著述，南宋时期象山学派中心，是以陆九渊为代表的赣学兴起的重要标志。学界称其为“草庐”先生，与当世经学大师许衡齐名，并称为“北许南吴”。胡居仁，“文章节义”的白鹭洲书院。白鹭洲书院在吉安市区，南宋淳祐元年江万里建于赣明朝理学家、书院教育家，成“余干之学”，名闻当时，影响后世，曾两主白鹿洞书院，江白鹭洲上。书院初建江万里自任导师，教学生徒，“载色载笑，从容水竹间”。白鹭以布衣终身。王守仁，陆王心学之集大成者，其武功、文治多成就于江右，对推动明代洲书院培养了民族英雄文天祥、爱国词人邓光荐、刘辰翁等名垂青史的历史人物，成为江西书院讲会与会讲功莫大焉。江西“文章节义之邦”的杰出代表。王勃的《滕王阁序》中备述江西“物华天宝，龙光射牛斗之墟; 人杰地灵, 徐孺下省会设立豫章书院。清雍正十一年颁发上谕，命在各省省会设立省会书院，南昌豫之图文陈蕃之榻”，可谓恰如其分。当我们记住这些人物的时候，其实我们在铭记历史，感恩先贤。章书院的改建是此令之产物，从此豫章书院成为巡抚负责督办的省级书院。江右书院行',13,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',510,NULL,'2026-08-16 21:12:09'),(166,10,1,16,'当我们记住这些人物的时候，其实我们在铭记历史，感恩先贤。章书院的改建是此令之产物，从此豫章书院成为巡抚负责督办的省级书院。江右书院行同时，我们还不能忘记发生在江右大地上的那些脍炙人口的书院传奇。客家特色的奎光书院。清光绪年间，散居于赣西北的客籍人士因土籍士绅的抵制，让我们记住这些事件：在求学上受到限制，遂众筹捐金，于当时的义宁州铜鼓厅创立奎光书院，专课客籍生徒，义门陈氏与东佳书堂。东佳书堂位于德安县，建于唐大顺元年前后（890），为江遂使书院成为赣西北客家人创立的第一所书院，影响深远。这种客家与土著人分而治学，州义门陈氏的高等学堂。东佳书堂是目前所知史料最为可靠的始建于唐代的书院代表，作为特定的历史现象，也是江西书院文化的一个特别现象。是中国书院发展史上的第一个里程碑，是书院早期形态的古老化石，标志着书院在民间红色遗址潋江书院。潋江书院在兴国县，建于清乾隆年间，形制完整，规制完备，的兴起。雄伟壮观。大革命时期，红四军党代表毛泽东在潋江书院传达中共六大会议精神并主办胡氏宗风与华林书院。华林书院位于奉新县，宋真宗曾御笔赐诗称“一门三刺史，',13,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',474,NULL,'2026-08-16 21:12:09'),(167,10,1,17,'大革命时期，红四军党代表毛泽东在潋江书院传达中共六大会议精神并主办胡氏宗风与华林书院。华林书院位于奉新县，宋真宗曾御笔赐诗称“一门三刺史，土地革命干部培训班，1930年至1934年，书院为兴国县苏维埃政府所在地，潋江书院四代五尚书。他族未闻有，朕今止见胡”。华林书院文学派道教色彩浓厚，也是目前所遂成为江西红色书院的代表。知我国最早招收女性的书院，为胡氏培养了许多杰出人才，胡耀邦即为其后嗣。江西书院始于唐、盛于宋、兴于元、繁于明、终于清，历经一千多年。演绎了无数明宗敕额与匡山书院。匡山书院位于泰和县，建于后唐长兴年间（930—933），后的精彩和故事，为中华文明的历史进程起到了很好的推动作用。江西书院沿“理学”“心唐明宗李嗣源敕翰林学士赵凤书“匡山书院”额并颁布御书，称书院“馆起匡山之下，学”“汉学”之路前行，一直引领中国书院文化击楫中流，可谓独占鳌头，江右魁首。民风日盛……而风教之裨未必无小补焉”，此为中国书院史上第一个由皇帝发布褒旌书随着历史的进程，书院的使命结束于百年之前，就在我们的历史门槛前，书院的角色谢院的文告。幕了，书院的精舍凋敝了，书院的使命终结了。但是，它所传承的文化，它所沉淀的历',13,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',505,NULL,'2026-08-16 21:12:09'),(168,10,1,18,'随着历史的进程，书院的使命结束于百年之前，就在我们的历史门槛前，书院的角色谢院的文告。幕了，书院的精舍凋敝了，书院的使命终结了。但是，它所传承的文化，它所沉淀的历濂溪书堂与理学发端。濂溪书堂在九江市区，北宋嘉祐六年（1061）周敦颐建。周史，由它而衍生的大学堂及现今的高等学府如逐日的夸父，正随着朝阳前行，成为赣鄱爱庐山之美，筑堂于其麓，堂前有溪发源于莲花峰下，遂以周故乡濂溪名之。濂溪书堂大地上一道亮丽的风景。那高大明亮的校舍，那繁花似锦的校园，那书颂琅琅的校区……\n\n无不在再现传统书院文化的时代风采，无不在诉说书院曾经文明的历史传承。我们正站在新时代的起跑线上，我们有必要去打捞已经失落的宅院，我们有必要去寻找已经失去的记忆，我们有必要去恢复已经倾覆的墙垣，我们有必要去把书院文化的秘笈传承给我们的下一代……再下一代……滚滚赣江水，浩浩鄱阳湖，我们踏着历史的肩膀走到今天，我们也要用肩膀担负起未来。古人尚且可以“裹粮而来”“结庐而居”，我们完全可以承载历史，精进前行，让历史告诉未来，让我们创复历史……乙未年春，至北京汇报工作，言及江右书院文化，慷慨激昂，跃跃欲试，当即立下',13,'null','{\"page_end\": 14, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',490,NULL,'2026-08-16 21:12:09'),(169,10,1,19,'让历史告诉未来，让我们创复历史……乙未年春，至北京汇报工作，言及江右书院文化，慷慨激昂，跃跃欲试，当即立下军令状，一年内编印《江右书院行——之美文》 《江右书院行——之论文》 《江右书院行——之图文》，同时举办江西书院遗存摄影展，号称为“3+1”工程，随后还有《江右书院行——之诗文》行将出版。一言既出，驷马难追。立下“军令状”对于我们而言，那便是“开弓没有回头箭”！更何况，在某某大会上，公然地宣称要付诸于行动，当别无选择的时候，我们只有奋发努力，去践行自己曾经许下的诺言。于是，从姚电、王金平、邬小辉、肖霞、张劲松、陈俊鸿、韩春萌、王迁丽等一干人等，不舍昼夜，伏案而作。时至如今，心怀忐忑交付出版，择期展之。当然，仅有一干人等是不够的，在此我们还要鸣谢艾威、蔡晓明、陈凤鸣、陈连平、崔小华、戴淑华、丁潮康、何长恩、何志清、洪东亮、黄一魏、蒋德先、康健、康文财、李代发、李诗彪、刘敏、刘晓雪、刘耀金、罗钢、罗磊、邱小强、宋小勇、田承新、王承栋、易延玲、曾江右书院行健等图片拍摄者（提供者）以及《江右书院行之美文》的美文作者们，是大家共同的努力才有今日之成果。',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',480,NULL,'2026-08-16 21:12:09'),(170,10,1,20,'江右书院行健等图片拍摄者（提供者）以及《江右书院行之美文》的美文作者们，是大家共同的努力才有今日之成果。囿于人力有限，有些文章、图片从网上及刊物上撷取，甚至于来不及与作者照会。当然，来不及并不意味着我们对您的不尊重或不愿意。相信为弘扬书院文化，您定会鼎力相助，亦会宽容我们的不敬与不妥，在此请让我真诚地道一声：谢谢！由于时间关系，难免挂一漏万。再者，书院文化千年沧桑，少有遗存，荏苒光阴，蹉跎岁月，恢复和解读历史尚需时日。所以，疏漏之处，敬请批评。南昌师范学院书院研究中心2015年冬',14,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',242,NULL,'2026-08-16 21:12:09'),(171,11,1,0,'图书在版编目（ＣＩＰ）数据江右书院行之图文 / 邬小辉主编. -- 南昌 ： 江西美术出版社, 2015.12ISBN 978-7-5480-4106-1Ⅰ. ①江… Ⅱ. ①邬… Ⅲ. ①书院－教育史－江西省－文集 Ⅳ. ①G649.299.56-53中国版本图书馆CIP数据核字(2015)第320412号项目负责：李  佳责任编辑：陈  军  李  佳责任印制：谭  勋书籍设计：郭  阳  林思同  先锋设计江右书院行之图文JIANGYOUSHUYUANXINGZHITUWEN 主       编：邬小辉出       版：江西美术出版社社       址：南昌市子安路66号邮       编：330025电       话：0791-86566241发       行：全国新华书店印       刷：浙江海虹彩色印务有限公司版       次：2015年12月第1版印       次：2015年12月第1次印刷开       本：787×1092  1/16印       张：17.5字       数：270千字ISBN 978-7-5480-4106-1定       价：100.00元',1,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',506,NULL,'2026-08-16 21:12:09'),(172,11,1,1,'字       数：270千字ISBN 978-7-5480-4106-1定       价：100.00元本书由江西美术出版社出版。未经出版者书面许可，不得以任何方式抄袭、复制或节录本书的任何部分。本书法律顾问：江西豫章律师事务所　晏辉律师赣版权登字-06-2015-804版权所有，侵权必究',1,'null','{\"page_end\": null, \"block_types\": [\"text\"], \"parser_version\": \"parser-v2-layout-table\", \"chunker_version\": \"chunker-v2-block-aware\"}',147,NULL,'2026-08-16 21:12:09');
