INSERT  IGNORE INTO `question_bank` (`id`, `kb_id`, `topic`, `question_type`, `difficulty`, `question`, `reference_answer`, `rubric`, `max_score`, `citations`, `created_at`, `options`) VALUES (1,1,'','single_choice','normal','豫章书院在清代经过改建后，成为由巡抚负责督办的省级书院。这一变化直接源于当时推行的哪项政令？','B','正确选择B得10分；选择其他选项得0分。',10,'[{\"idx\": 7, \"page\": 13, \"kb_id\": 1, \"chunk_id\": 166, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}]','2026-08-16 21:14:49','[{\"key\": \"A\", \"text\": \"明代书院扩建令\"}, {\"key\": \"B\", \"text\": \"清代书院整顿令\"}, {\"key\": \"C\", \"text\": \"客家移民鼓励令\"}, {\"key\": \"D\", \"text\": \"理学复兴诏令\"}]'),(2,1,'','single_choice','normal','南宋理学家朱熹在淳熙六年兴复白鹿洞书院，并亲订《白鹿洞书院揭示》。该揭示后来产生了什么重要影响？','B','正确选择B得10分；选择其他选项得0分。',10,'[{\"idx\": 9, \"page\": 13, \"kb_id\": 1, \"chunk_id\": 164, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}]','2026-08-16 21:14:49','[{\"key\": \"A\", \"text\": \"使书院完全取代官学成为教育主体\"}, {\"key\": \"B\", \"text\": \"成为天下书院共同遵守的规章通规\"}, {\"key\": \"C\", \"text\": \"导致书院教育逐渐被科举制度束缚\"}, {\"key\": \"D\", \"text\": \"标志着书院从民间向官办的全面转型\"}]'),(3,1,'','judge','normal','濂溪书堂是北宋理学家周敦颐于嘉祐六年（1061年）在九江市区创建的书院，因其堂前小溪发源于莲花峰下，且周敦颐故乡有濂溪，故以“濂溪”命名。','对','判断正确得10分；判断错误得0分。',10,'[{\"idx\": 5, \"page\": 13, \"kb_id\": 1, \"chunk_id\": 168, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}]','2026-08-16 21:14:49','[{\"key\": \"对\", \"text\": \"正确\"}, {\"key\": \"错\", \"text\": \"错误\"}]'),(4,1,'','judge','normal','东佳书堂建于唐代大顺元年（890年），是江州义门陈氏的高等学堂，被学界认为是中国书院发展史上的第一个里程碑。','对','判断正确得10分；判断错误得0分。',10,'[{\"idx\": 7, \"page\": 13, \"kb_id\": 1, \"chunk_id\": 166, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}]','2026-08-16 21:14:49','[{\"key\": \"对\", \"text\": \"正确\"}, {\"key\": \"错\", \"text\": \"错误\"}]'),(5,1,'','short_answer','normal','南昌师范学院书院研究中心在2015年冬编纂《江右书院行》时，指出传统书院的使命虽已终结，但其文化通过现代教育机构得以延续。请简要说明书院文化在现代社会中的传承方式。','书院文化通过现代高等学府（如大学校舍、校园）再现其时代风采，教育机构承载并弘扬书院的历史传承与文化精神，使传统书院精粹在新时代得以延续和发展。','答案需包含以下要点：现代教育机构（如大学）对书院文化的再现（4分）；书院历史传承在教育中的延续（3分）；语言准确、逻辑清晰（3分）。满分10分，缺少要点酌情扣分。',10,'[{\"idx\": 3, \"page\": 14, \"kb_id\": 1, \"chunk_id\": 170, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}, {\"idx\": 5, \"page\": 13, \"kb_id\": 1, \"chunk_id\": 168, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}]','2026-08-16 21:14:49','null'),(6,1,'','essay','normal','江西书院文化呈现出丰富的类型多样性，包括官方主导的省级书院、反映移民文化的客家书院、标志书院起源的唐代书院，以及承载革命记忆的红色遗址书院。请结合具体例子，论述这种多样性如何体现江西在历史进程中的文化、教育与社会变迁意义。','江西书院文化的多样性体现在：省级书院如豫章书院（清代改建为巡抚督办），代表官方教育体系的发展；客家书院如奎光书院（清代客籍人士创立），反映移民群体的文化适应与自强；唐代书院如东佳书堂（890年建），标志书院从民间兴起的早期形态；红色遗址如潋江书院（毛泽东曾在此传达中共会议精神），融合革命历史记忆。这种多样性展示了江西作为文化重镇，在教育制度、族群融合、学术传承和社会变革中的关键作用，体现了书院文化跨越时代的适应性与生命力。','答案需涵盖以下维度：举例说明至少三种书院类型（4分）；分析每种类型的历史背景或特点（3分）；论述多样性对江西历史、文化、社会的意义（2分）；结构完整、语言流畅（1分）。满分10分，内容不全或论述单薄酌情扣分。',10,'[{\"idx\": 7, \"page\": 13, \"kb_id\": 1, \"chunk_id\": 166, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}, {\"idx\": 9, \"page\": 13, \"kb_id\": 1, \"chunk_id\": 164, \"filename\": \"江右书院行之图文内文(4)0508_compressed (1)_compressed (1)-10.pdf\", \"document_id\": 10}]','2026-08-16 21:14:49','null');
